const CACHE_NAME = 'emotion-companion-cache-v4';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/App.tsx',
  '/types.ts',
  '/constants.ts',
  '/hooks/useLocalStorage.ts',
  '/contexts/AppContext.tsx',
  '/components/Icons.tsx',
  '/components/TabNavigator.tsx',
  '/components/LiveTab.tsx',
  '/components/ChatTab.tsx',
  '/components/ActivitiesTab.tsx',
  '/components/ActivityModal.tsx',
  '/components/StatsTab.tsx',
  '/components/SettingsTab.tsx',
  '/components/SplashScreen.tsx',
  'https://cdn.tailwindcss.com'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          response => {
            // Check if we received a valid response
            // We must allow 'cors' type to cache CDN scripts (React, Tailwind, etc.)
            // 'basic' is for same-origin, 'cors' is for valid cross-origin
            if (!response || response.status !== 200 || (response.type !== 'basic' && response.type !== 'cors')) {
              return response;
            }

            // IMPORTANT: Clone the response. A response is a stream
            // and because we want the browser to consume the response
            // as well as the cache consuming the response, we need
            // to clone it so we have two streams.
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then(cache => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import React, { useState, useEffect } from 'react';
import LiveTab from './components/LiveTab';
import ChatTab from './components/ChatTab';
import ActivitiesTab from './components/ActivitiesTab';
import StatsTab from './components/StatsTab';
import SettingsTab from './components/SettingsTab';
import TabNavigator from './components/TabNavigator';
import SplashScreen from './components/SplashScreen';
import { Tab } from './types';
import { useAppContext } from './contexts/AppContext';

const App: React.FC = () => {
  const { theme } = useAppContext();
  const [activeTab, setActiveTab] = useState<Tab>('live');
  const [appState, setAppState] = useState<'splash' | 'login' | 'main'>('splash');

  useEffect(() => {
    const timer = setTimeout(() => {
      setAppState('login');
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = () => {
    setAppState('main');
  };

  const handleLogout = () => {
    setAppState('login');
    setActiveTab('live');
  };

  if (appState === 'splash') {
    return <SplashScreen />;
  }

  if (appState === 'login') {
    return <LoginScreen onLoginSuccess={handleLoginSuccess} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'live':
        return <LiveTab />;
      case 'chat':
        return <ChatTab />;
      case 'activities':
        return <ActivitiesTab />;
      case 'stats':
        return <StatsTab />;
      case 'settings':
        return <SettingsTab onLogout={handleLogout} />;
      default:
        return <LiveTab />;
    }
  };

  return (
    <div key={theme} className="h-screen w-screen bg-gradient-to-br from-indigo-100 via-purple-100 to-blue-100 dark:from-slate-900 dark:via-indigo-900 dark:to-gray-900 font-sans flex flex-col overflow-hidden transition-colors duration-300">
      <main className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
        {renderContent()}
      </main>
      <TabNavigator activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

export default App;

