        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-indigo-600 dark:text-indigo-400 mb-2">
            {isFirstTime ? 'Welcome to PelioScope' : 'Sign In'}
          </h1>
          <p className="text-gray-500 dark:text-gray-400">
            {isFirstTime ? 'Let\'s set up your profile to begin.' : 'Enter your 4-digit PIN to continue.'}
          </p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Name
            </label>
            <div className="relative">
                <input
                  type="text"
                  value={inputName}
                  onChange={(e) => setInputName(e.target.value)}
                  disabled={!isFirstTime} // Only allow name input if no profile exists
                  className={`w-full px-4 py-3 rounded-xl border ${!isFirstTime ? 'bg-gray-100 dark:bg-gray-800 text-gray-500 cursor-not-allowed font-semibold' : 'bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white'} border-gray-300 dark:border-gray-600 focus:ring-2 focus:ring-indigo-500 outline-none transition-all`}
                  placeholder="Your Name"
                />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              4-Digit PIN
            </label>
            <input
              type="password"
              inputMode="numeric"
              maxLength={4}
              value={inputPin}
              onChange={(e) => setInputPin(e.target.value.replace(/[^0-9]/g, ''))}
              className="w-full px-4 py-3 rounded-xl border border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all tracking-widest text-center text-2xl"
              placeholder="••••"
            />
          </div>

          {error && (
            <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-300 text-sm rounded-lg text-center font-medium animate-pulse">
              {error}
            </div>
          )}

          <button
            type="submit"
            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-xl shadow-lg transform transition hover:scale-[1.02] active:scale-95"
          >
            {isFirstTime ? 'Get Started 🚀' : 'Unlock 🔓'}
          </button>
        </form>

        <div className="mt-8 text-center">
            <p className="text-[10px] uppercase tracking-widest text-gray-400 font-bold">Secure Local Profile</p>
        </div>
