import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const QUICK_REPLIES: Record<string, string[]> = {
  Happy: ["I'm feeling great!", "Something good happened!", "Today is awesome!"],
  Angry: ["I am frustrated.", "Things aren't going right.", "I need to calm down."],
  Neutral: ["I'm doing okay.", "Just chilling.", "I'm bored."],
  Disgust: ["That is gross.", "I don't like this.", "Yuck!"],
  Fear: ["I am scared.", "I feel nervous.", "I need help."],
  Surprised: ["I didn't expect that!", "Wow, that's amazing!", "Really?"],
  Sad: ["I feel lonely.", "I had a bad day.", "Can you cheer me up?"],
};

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [selectedQuickEmotion, setSelectedQuickEmotion] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Gemini Chat Session Reference
  const chatSessionRef = useRef<any>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  // Initialize Chat Session
  useEffect(() => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `You are ${companionName}, a friendly and supportive emotion companion for ${userName || 'a user'} who has Autism Spectrum Disorder (ASD). 
        Your goal is to provide clear, simple, and reassuring communication. 
        Acknowledge the user's emotions. Currently, the device detects they are feeling: ${currentEmotion}.
        Use visual descriptions when helpful (e.g., "Imagine a calm blue ocean"). 
        Keep responses concise (1-3 sentences). Avoid idioms or complex metaphors. 
        Always be kind and patient.`,
      },
    });
    chatSessionRef.current = chat;

    setMessages([
      {
        id: 'welcome',
        text: `Hello ${userName}! I'm ${companionName}. I see you're feeling ${currentEmotion.toLowerCase()} right now. How can I help you?`,
        sender: 'companion',
        timestamp: Date.now(),
      }
    ]);
  }, [companionName, userName]); // Re-init if name changes

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping) return;

    const userMsgId = Date.now().toString();
    const newUserMessage: ChatMessage = {
      id: userMsgId,
      text: text,
      sender: 'user',
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newUserMessage]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) throw new Error("Chat session not initialized");

      // Send message to Gemini
      // We include the current emotion in the message context for the AI
      const prompt = `[Context: Current detected emotion is ${currentEmotion}] ${text}`;
      const result = await chatSessionRef.current.sendMessage({ message: prompt });
      const responseText = result.text;

      const companionResponse: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: responseText || "I'm here for you. Can you tell me more?",
        sender: 'companion',
        timestamp: Date.now() + 1,
      };

      setMessages(prev => [...prev, companionResponse]);
    } catch (error) {
      console.error("Gemini API Error:", error);
      const errorMsg: ChatMessage = {
        id: 'error-' + Date.now(),
        text: "I'm having a little trouble connecting to my brain right now, but I'm still here for you!",
        sender: 'companion',
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    processMessage(userInput);
  };

  const handleQuickReply = (text: string) => {
    processMessage(text);
  };

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100 text-center mb-2 px-4">
        Chat with {companionName}
      </h1>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-8 h-8 rounded-full bg-indigo-400 flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm">
                {companionName.charAt(0)}
              </div>
            )}
            <div className={`max-w-[80%] p-3.5 rounded-2xl shadow-sm border ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white border-indigo-500 rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm leading-relaxed">{msg.text}</p>
              <span className={`text-[10px] mt-1.5 block font-medium opacity-60 ${msg.sender === 'user' ? 'text-indigo-100 text-right' : 'text-gray-400 dark:text-gray-500 text-left'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex items-center gap-2 animate-pulse">
            <div className="w-8 h-8 rounded-full bg-indigo-200 dark:bg-indigo-900/40 flex items-center justify-center text-indigo-400 font-bold text-sm shrink-0">
              {companionName.charAt(0)}
            </div>
            <div className="bg-gray-100 dark:bg-gray-800 px-4 py-2 rounded-2xl rounded-bl-none border border-gray-200 dark:border-gray-700">
               <div className="flex gap-1">
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
               </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Quick Reply Section */}
      <div className="px-4 py-2 border-t border-gray-100 dark:border-gray-800 bg-gray-50/50 dark:bg-gray-900/50 backdrop-blur-sm">
         <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {Object.keys(QUICK_REPLIES).map(emo => (
                <button 
                    key={emo}
                    onClick={() => setSelectedQuickEmotion(selectedQuickEmotion === emo ? null : emo)}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all border shadow-sm ${
                        selectedQuickEmotion === emo 
                        ? 'bg-indigo-600 text-white border-indigo-600 scale-105' 
                        : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 border-gray-200 dark:border-gray-700 hover:border-indigo-300'
                    }`}
                >
                    {(EMOTION_DETAILS[emo as Emotion] || {emoji: '😐'}).emoji} {emo}
                </button>
            ))}
         </div>

         {selectedQuickEmotion && (
             <div className="flex gap-2 overflow-x-auto pt-1 pb-2 scrollbar-hide animate-fadeInUp">
                 {QUICK_REPLIES[selectedQuickEmotion].map((phrase, idx) => (
                     <button
                        key={idx}
                        onClick={() => handleQuickReply(phrase)}
                        className="bg-indigo-50 dark:bg-indigo-900/30 border border-indigo-100 dark:border-indigo-800/50 text-indigo-700 dark:text-indigo-300 px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap hover:bg-indigo-100 transition-all active:scale-95 shadow-sm"
                     >
                         {phrase}
                     </button>
                 ))}
             </div>
         )}
      </div>

      <form onSubmit={handleSendMessage} className="p-4 pt-2 flex items-center gap-2 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-gray-800">
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder={isTyping ? "Wait a moment..." : "Type to talk to Peli..."}
          disabled={isTyping}
          className="flex-1 p-3.5 border border-gray-200 dark:border-gray-700 dark:bg-gray-900 dark:text-white rounded-2xl focus:ring-2 focus:ring-indigo-500 focus:outline-none transition-all text-sm placeholder:text-gray-400"
          aria-label="Chat input"
        />
        <button 
          type="submit" 
          disabled={isTyping || !userInput.trim()}
          className={`p-3.5 rounded-2xl transition-all shadow-md ${
            isTyping || !userInput.trim() 
              ? 'bg-gray-200 text-gray-400 cursor-not-allowed' 
              : 'bg-indigo-600 text-white hover:bg-indigo-700 active:scale-90'
          }`} 
          aria-label="Send message"
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

export default ChatTab;

