// --- AUDIO UTILITIES FOR GEMINI TTS ---
function decodeBase64ToUint8(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodePCM(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

// --- Peli Character Component (Virtual Pet) ---
interface PeliProps {
  emotion: string; 
  animationClass?: string;
  showParticles?: string; 
  customEyes?: string; 
  isGlowing?: boolean; 
  scale?: number; 
  accessories?: 'headphones' | null;
  isDirty?: boolean; 
  isWet?: boolean; 
  isHungry?: boolean; 
  bubbles?: boolean; 
}

export const PeliCharacter: React.FC<PeliProps> = ({ 
    emotion, 
    animationClass, 
    showParticles, 
    customEyes, 
    isGlowing, 
    scale = 1, 
    accessories = null,
    isDirty = false,
    isWet = false,
    isHungry = false,
    bubbles = false
}) => {
  const { equippedItems } = useAppContext();

  const traits = useMemo(() => {
    let color = '#FFE8C7'; 
    let eyes = 'normal'; 
    let mouth = 'smile'; 
    let eyebrows = 'neutral'; 

    const normEmo = emotion.toLowerCase();

    if (normEmo === 'happy' || normEmo === 'excited' || normEmo === 'proud' || normEmo === 'confident') {
      color = '#fcd34d'; 
      eyes = 'squint';
      mouth = 'open-smile';
      eyebrows = 'up';
    } else if (normEmo === 'sad' || normEmo === 'lonely') {
      color = '#93c5fd'; 
      eyes = 'sad';
      mouth = 'frown';
      eyebrows = 'sad';
    } else if (normEmo === 'angry' || normEmo === 'mad' || normEmo === 'tense') {
      color = '#f87171'; 
      eyes = 'angry';
      mouth = 'frown';
      eyebrows = 'angry';
    } else if (normEmo === 'fear' || normEmo === 'scared' || normEmo === 'nervous' || normEmo === 'worried') {
      color = '#a5b4fc'; 
      eyes = 'wide';
      mouth = 'wavy';
      eyebrows = 'up';
    } else if (normEmo === 'surprised' || normEmo === 'curious') {
      color = '#d8b4fe'; 
      eyes = 'wide';
      mouth = 'o-shape';
      eyebrows = 'up';
    } else if (normEmo === 'disgust') {
      color = '#84cc16'; 
      eyes = 'squint';
      mouth = 'wavy';
      eyebrows = 'angry';
    } else if (normEmo === 'love' || normEmo === 'grateful' || normEmo === 'relaxed' || normEmo === 'calm') {
      color = '#f472b6'; 
      eyes = 'happy-closed';
      mouth = 'smile';
      eyebrows = 'neutral';
    } else if (normEmo === 'neutral' || normEmo === 'idle' || normEmo === 'peaceful' || normEmo === 'focus' || normEmo === 'brave') {
      color = '#FFE8C7'; 
      eyes = 'normal';
      mouth = 'smile';
      eyebrows = 'neutral';
    } else if (normEmo === 'sleeping' || normEmo === 'meditating' || normEmo === 'tired') {
        color = '#a5f3fc'; 
        eyes = 'happy-closed';
        mouth = 'smile';
        eyebrows = 'neutral';
    } else if (normEmo === 'nature' || normEmo === 'serene' || normEmo === 'bird') {
        color = '#86efac'; 
        eyes = 'happy-closed';
        mouth = 'smile';
        eyebrows = 'neutral';
    }

    if (customEyes) {
        eyes = customEyes;
    }

    return { color, eyes, mouth, eyebrows };
