const StoryMode: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
    const { currentEmotion, userName, companionName } = useAppContext();
    const [storyList, setStoryList] = useState(STORIES);
    const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
    const [sceneIndex, setSceneIndex] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [isNarrating, setIsNarrating] = useState(false);
    const [hasStarted, setHasStarted] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);

    const audioContextRef = useRef<AudioContext | null>(null);
    const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
    const isCancelledRef = useRef(false);

    const initAudio = () => {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        if (audioContextRef.current.state === 'suspended') {
            audioContextRef.current.resume();
        }
    };

    const stopPlayback = useCallback(() => {
        isCancelledRef.current = true;
        if (sourceNodeRef.current) {
            try { sourceNodeRef.current.stop(); } catch(e) {}
            sourceNodeRef.current = null;
        }
        setIsPlaying(false);
        setIsNarrating(false);
    }, []);

    const speakSceneGemini = async (index: number) => {
        if (selectedStoryIndex === null) return;
        const currentStory = storyList[selectedStoryIndex];
        const scene = currentStory.scenes[index];

        isCancelledRef.current = false;
        setIsNarrating(true);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: [{ parts: [{ text: scene.text }] }],
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: 'Kore' },
                        },
                    },
                },
            });

            if (isCancelledRef.current) return;

            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                initAudio();
                const ctx = audioContextRef.current!;
                const audioData = decodeBase64ToUint8(base64Audio);
                const buffer = await decodePCM(audioData, ctx, 24000, 1);

                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                sourceNodeRef.current = source;

                source.onended = () => {
                    setIsNarrating(false);
                    if (isCancelledRef.current) return;
                    setTimeout(() => {
                        if (isCancelledRef.current) return;
                        if (index < currentStory.scenes.length - 1) {
                            setSceneIndex(index + 1);
                            speakSceneGemini(index + 1);
                        } else {
                            onComplete();
                        }
                    }, 1200);
                };

                source.start();
            }
        } catch (error) {
            console.error("Gemini TTS error:", error);
            setIsNarrating(false);
            // Fallback: Skip to next after dummy delay
            setTimeout(() => {
                if (index < currentStory.scenes.length - 1) {
                    setSceneIndex(index + 1);
                    speakSceneGemini(index + 1);
                } else {
                    onComplete();
                }
            }, 3000);
        }
    };

    const handleGenerateStory = async () => {
        setIsGenerating(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const result = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Create a 5-scene children's story for ${userName}. 
                Current Emotion context: ${currentEmotion}. 
                Theme: Comfort, growth, and understanding feelings.
                Respond strictly in JSON format: 
                { "title": "Story Title", "scenes": [ { "text": "Scene 1 text...", "emotion": "EmotionLabel" }, ... ] }
                Supported emotions for character: Happy, Sad, Angry, Surprised, Fear, Neutral, Disgust, Love, Relaxed.`,
                config: { responseMimeType: "application/json" }
            });

            const storyData = JSON.parse(result.text);
            const newStory = {
                id: Date.now(),
                title: storyData.title,
                icon: "✨",
                scenes: storyData.scenes
            };

            setStoryList(prev => [newStory, ...prev]);
            handleSelectStory(0); // Select the first one (the generated one)
        } catch (e) {
            console.error("Generation failed", e);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleSelectStory = (index: number) => {
        setSelectedStoryIndex(index);
        setHasStarted(false);
        setSceneIndex(0);
    };

    const handleStart = () => {
        initAudio();
        setHasStarted(true);
        setIsPlaying(true);
        speakSceneGemini(0);
    };

    if (selectedStoryIndex === null) {
        return (
            <div className="flex flex-col items-center w-full h-full animate-fadeIn">
                <h2 className="text-2xl font-bold mb-4">Choose a Story</h2>
                <div className="w-full space-y-3 mb-6">
                    <button 
                        disabled={isGenerating}
                        onClick={handleGenerateStory}
                        className="w-full bg-gradient-to-r from-purple-500 to-indigo-500 p-4 rounded-2xl flex items-center gap-4 transition-transform active:scale-95 text-left shadow-lg"
                    >
                        <span className="text-4xl">{isGenerating ? "🌀" : "✨"}</span>
                        <div>
                            <h3 className="font-bold text-lg leading-tight">{isGenerating ? "Writing your story..." : "AI Personalized Story"}</h3>
                            <p className="text-xs opacity-80">Based on your mood: {currentEmotion}</p>
                        </div>
                    </button>
                </div>
                <div className="flex-1 w-full overflow-y-auto px-2 space-y-3 pb-4 scrollbar-hide">
                    {storyList.map((story, idx) => (
                        <button
                            key={story.id}
                            onClick={() => handleSelectStory(idx)}
                            className="w-full bg-white/20 hover:bg-white/30 p-4 rounded-2xl flex items-center gap-4 transition-transform active:scale-95 text-left"
                        >
                            <span className="text-4xl">{story.icon}</span>
                            <div>
                                <h3 className="font-bold text-lg leading-tight">{story.title}</h3>
                                <p className="text-xs opacity-80">{story.scenes.length} scenes</p>
                            </div>
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    const currentStory = storyList[selectedStoryIndex];
    const currentScene = currentStory.scenes[sceneIndex];

    if (!hasStarted) {
        return (
            <div className="flex flex-col items-center justify-center flex-grow text-center relative w-full h-full">
                <button onClick={() => setSelectedStoryIndex(null)} className="absolute top-0 left-0 text-sm opacity-70">← Back</button>
                <h2 className="text-2xl font-bold mb-2">{currentStory.title}</h2>
                <div className="w-48 h-48 mb-6 mt-4">
                    <PeliCharacter emotion="Happy" />
                </div>
                <p className="mb-8 opacity-90 max-w-xs">Narration powered by Gemini AI</p>
                <button onClick={handleStart} className="bg-white text-indigo-600 px-8 py-4 rounded-full font-bold text-xl shadow-lg">Start Story 📖</button>
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center justify-between flex-grow h-full py-4 w-full relative">
             <button onClick={stopPlayback} className="absolute top-0 left-0 text-sm opacity-70">← Stop</button>
            <h3 className="text-xl font-bold opacity-70 text-center px-4 pt-4">{currentStory.title}</h3>
            <div className="flex-grow flex items-center justify-center w-full my-4">
                <div className={`w-64 h-64 transition-transform duration-500 ${isNarrating ? 'scale-105' : 'scale-100'}`}>
                    <PeliCharacter emotion={currentScene.emotion} animationClass={isNarrating ? 'animate-pulse' : ''} />
                </div>
            </div>
            <div className="bg-white/20 backdrop-blur-md p-6 rounded-3xl w-full max-w-xs mb-8 min-h-[150px] flex flex-col justify-center shadow-lg">
                <p className="text-2xl font-bold text-center leading-relaxed">"{currentScene.text}"</p>
            </div>
            {isNarrating && (
                <div className="flex items-center gap-2 text-sm font-bold animate-pulse text-indigo-100">
                    <span>Narrating...</span>
                </div>
            )}
        </div>
    );
};

const GenericTimer: React.FC<{ activity: Activity; onComplete: () => void }> = ({ activity, onComplete }) => {
  const [timeLeft, setTimeLeft] = useState(activity.duration);
  useEffect(() => {
    if (timeLeft <= 0) { onComplete(); return; }
    const timerId = setInterval(() => setTimeLeft((prev) => prev - 1), 1000);
    return () => clearInterval(timerId);
  }, [timeLeft, onComplete]);
  const progress = ((activity.duration - timeLeft) / activity.duration) * 100;
  const Icon = activity.icon;
  return (
    <div className="flex flex-col items-center justify-center flex-grow w-full py-8">
      <Icon className="w-20 h-20 mx-auto mb-6 drop-shadow-lg" />
      <h2 className="text-3xl font-bold mb-2">{activity.name}</h2>
      <p className="text-6xl font-mono font-bold my-8">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</p>
      <div className="w-full bg-white/30 rounded-full h-3 max-w-xs">
        <div className="bg-white h-3 rounded-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
      </div>
    </div>
  );
};

const PhysicalExercise: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [phase, setPhase] = useState<'intro' | 'active' | 'outro'>('intro');
  const [currentStep, setCurrentStep] = useState(0);
  const [timeLeft, setTimeLeft] = useState(5);

  const movements = useMemo(() => [
    { name: "Stretch Arms Up", text: "Reach high… feel your chest open.", duration: 8, animation: "scale-y-125", peliEmotion: "Neutral" },
    { name: "Shake Hands", text: "Release tightness from your fingers.", duration: 6, animation: "animate-shake", peliEmotion: "Happy" },
    { name: "Slow Neck Roll", text: "Move gently… front → side → back.", duration: 8, animation: "rotate-6", peliEmotion: "Relaxed" },
    { name: "Step in Place", text: "Warm your feet, loosen your legs.", duration: 8, animation: "animate-bounce", peliEmotion: "Excited" }
  ], []);

  useEffect(() => {
    if (timeLeft <= 0) {
      if (phase === 'intro') { setPhase('active'); setTimeLeft(movements[0].duration); }
      else if (phase === 'active') {
        if (currentStep < movements.length - 1) { setCurrentStep(c => c + 1); setTimeLeft(movements[currentStep + 1].duration); }
        else { setPhase('outro'); setTimeLeft(5); }
      } else if (phase === 'outro') { onComplete(); }
      return;
    }
    const timer = setInterval(() => setTimeLeft(t => t - 1), 1000);
    return () => clearInterval(timer);
  }, [timeLeft, phase, currentStep, movements, onComplete]);

  if (phase === 'intro') {
    return (
      <div className="flex flex-col items-center justify-center flex-grow text-center animate-fadeIn">
        <h2 className="text-3xl font-bold mb-6">Let's Move!</h2>
        <div className="w-40 h-40 mb-6"><PeliCharacter emotion="Neutral" /></div>
        <p className="mt-4 text-4xl font-bold">{timeLeft}</p>
      </div>
    );
  }
  if (phase === 'active') {
    const move = movements[currentStep];
    return (
      <div className="flex flex-col items-center justify-center flex-grow text-center animate-fadeIn">
        <h2 className="text-2xl font-bold mb-2">{move.name}</h2>
        <div className="w-48 h-48 my-6"><PeliCharacter emotion={move.peliEmotion} animationClass={move.animation} /></div>
        <p className="text-xl px-6 min-h-[3rem]">{move.text}</p>
      </div>
    );
  }
  return (
    <div className="flex flex-col items-center justify-center flex-grow text-center animate-fadeIn">
        <h2 className="text-3xl font-bold mb-6">All Done!</h2>
        <div className="w-40 h-40 mb-6"><PeliCharacter emotion="Relaxed" isGlowing /></div>
    </div>
  );
};

const FindFaceGame: React.FC<{ onComplete: () => void; setPeliReaction: (emo: string) => void; setFeedback: (text: string) => void; peliReaction: string; }> = ({ onComplete, setPeliReaction, setFeedback, peliReaction }) => {
    const [difficulty, setDifficulty] = useState<'easy'|'medium'|'hard'>('easy');
    const [grid, setGrid] = useState<Emotion[]>([]);
    useEffect(() => {
        const count = difficulty === 'easy' ? 3 : difficulty === 'medium' ? 5 : 8;
        const distractors: Emotion[] = ['Sad', 'Angry', 'Fear', 'Surprised', 'Disgust', 'Neutral'];
        const newGrid: Emotion[] = [];
        for(let i=0; i<count-1; i++) newGrid.push(distractors[Math.floor(Math.random() * distractors.length)]);
        const insertIdx = Math.floor(Math.random() * count);
        newGrid.splice(insertIdx, 0, 'Happy');
        setGrid(newGrid);
        setPeliReaction('Neutral');
        setFeedback("Tap the Happy face!");
    }, [difficulty, setPeliReaction, setFeedback]);
