const MusicPlayer: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTrack, setCurrentTrack] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const tracks = [
    { title: "Ocean Calm", emotion: "Relaxed", src: "https://assets.mixkit.co/active_storage/sfx/1196/1196-preview.mp3" }, 
    { title: "Forest Rain", emotion: "Peaceful", src: "https://assets.mixkit.co/active_storage/sfx/2393/2393-preview.mp3" }, 
    { title: "Soft Clouds", emotion: "Focus", src: "https://assets.mixkit.co/active_storage/sfx/1175/1175-preview.mp3" }, 
  ];

  useEffect(() => {
    audioRef.current = new Audio(tracks[currentTrack].src);
    audioRef.current.loop = true;
    const updateTime = () => setCurrentTime(audioRef.current?.currentTime || 0);
    const updateDuration = () => setDuration(audioRef.current?.duration || 0);
    audioRef.current.addEventListener('timeupdate', updateTime);
    audioRef.current.addEventListener('loadedmetadata', updateDuration);
    if (isPlaying) audioRef.current.play().catch(() => {});
    return () => { audioRef.current?.pause(); audioRef.current = null; };
  }, [currentTrack]);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play().catch(() => {});
    setIsPlaying(!isPlaying);
  };

  return (
    <div className="flex flex-col items-center justify-between h-full w-full animate-fadeIn">
      <div className="w-full text-center mt-2">
        <h2 className="text-2xl font-bold">Music Player</h2>
      </div>
      <div className="flex-grow flex items-center justify-center relative w-full">
         <div className="w-56 h-56 transition-transform duration-500">
            <PeliCharacter emotion={tracks[currentTrack].emotion} accessories="headphones" showParticles={isPlaying ? 'notes' : null} />
         </div>
      </div>
      <div className="w-full bg-white/20 backdrop-blur-md rounded-3xl p-6 mb-2">
          <h3 className="text-xl font-bold text-center mb-1">{tracks[currentTrack].title}</h3>
          <div className="flex items-center justify-center gap-6 mt-4">
               <button onClick={togglePlay} className="w-16 h-16 bg-white text-indigo-500 rounded-full flex items-center justify-center text-3xl shadow-lg">
                 {isPlaying ? '⏸️' : '▶️'}
