const BreathingMode: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [phase, setPhase] = useState<'inhale' | 'hold' | 'exhale'>('inhale');
  const [timeLeft, setTimeLeft] = useState(4); 
  const [cycles, setCycles] = useState(0);
  useEffect(() => {
    if (cycles >= 3) { onComplete(); return; }
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (phase === 'inhale') { setPhase('hold'); return 4; }
          else if (phase === 'hold') { setPhase('exhale'); return 4; }
          else { setPhase('inhale'); setCycles(c => c + 1); return 4; }
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [phase, cycles, onComplete]);
  return (
    <div className="flex flex-col items-center justify-center flex-grow w-full py-8 text-center">
      <h2 className="text-2xl font-bold mb-8">Deep Breathing</h2>
      <div className="w-48 h-48 mb-8"><PeliCharacter emotion={phase === 'exhale' ? 'Calm' : 'Relaxed'} scale={phase === 'inhale' ? 1.1 : phase === 'exhale' ? 0.9 : 1} /></div>
      <p className="text-3xl font-bold mb-2">{phase === 'inhale' ? 'Breathe In' : phase === 'hold' ? 'Hold' : 'Breathe Out'}</p>
      <p className="text-5xl font-mono font-bold">{timeLeft}</p>
    </div>
  );
};

