const MusicPlayer: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTrack, setCurrentTrack] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const tracks = [
    { title: "Ocean Calm", emotion: "Relaxed", src: "https://assets.mixkit.co/active_storage/sfx/1196/1196-preview.mp3" }, 
    { title: "Forest Rain", emotion: "Peaceful", src: "https://assets.mixkit.co/active_storage/sfx/2393/2393-preview.mp3" }, 
    { title: "Soft Clouds", emotion: "Focus", src: "https://assets.mixkit.co/active_storage/sfx/1175/1175-preview.mp3" }, 
  ];

  useEffect(() => {
    audioRef.current = new Audio(tracks[currentTrack].src);
    audioRef.current.loop = true;
    if (isPlaying) audioRef.current.play().catch(() => {});
    return () => { audioRef.current?.pause(); audioRef.current = null; };
  }, [currentTrack]);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play().catch(() => {});
