    };
    return (
        <div className="flex flex-col items-center w-full">
            <h3 className="text-xl font-bold mb-4">Find the Happy Face!</h3>
            <div className="w-24 h-24 mb-4"><PeliCharacter emotion={peliReaction} /></div>
            <div className="flex flex-wrap gap-4 justify-center items-center max-w-xs">{grid.map((emo, idx) => (<button key={`${difficulty}-${idx}`} onClick={() => handleTap(emo)} className="text-5xl bg-white/20 p-4 rounded-2xl w-20 h-20 flex items-center justify-center">{EMOTION_DETAILS[emo].emoji}</button>))}</div>
