         </div>
      </div>
      <div className="w-full bg-white/20 backdrop-blur-md rounded-3xl p-6 mb-2">
          <h3 className="text-xl font-bold text-center mb-1">{tracks[currentTrack].title}</h3>
          <div className="flex items-center justify-center gap-6 mt-4">
               <button onClick={togglePlay} className="w-16 h-16 bg-white text-indigo-500 rounded-full flex items-center justify-center text-3xl shadow-lg">
                 {isPlaying ? '⏸️' : '▶️'}
