const MoodBoost: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [bgIndex, setBgIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const gradients = ['from-yellow-400 to-orange-400', 'from-pink-400 to-rose-400', 'from-sky-400 to-indigo-400'];
  const addInteraction = () => {
    const next = progress + 1;
    setProgress(next);
    if (next >= 10) setTimeout(onComplete, 1500);
  };
  return (
    <div className={`absolute inset-0 w-full h-full flex flex-col transition-colors duration-700 bg-gradient-to-br ${gradients[bgIndex]} overflow-hidden`}>
