const MusicPlayer: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setProgress(p => {
          if (p >= 100) {
            clearInterval(interval);
            onComplete();
            return 100;
          }
          return p + 0.5; // Roughly 200 steps to 100%
        });
      }, 900); // 180s total duration
    }
    return () => clearInterval(interval);
  }, [isPlaying, onComplete]);

  return (
    <div className="flex flex-col items-center justify-center flex-grow w-full text-center">
      <div className={`w-48 h-48 mb-8 transition-transform duration-500 ${isPlaying ? 'scale-110 animate-pulse' : 'scale-100'}`}>
