const MoodBoost: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [progress, setProgress] = useState(0);
  const [targets, setTargets] = useState<{ id: number, x: number, y: number, isGood: boolean }[]>([]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (targets.length < 5) {
        setTargets(prev => [...prev, {
          id: Date.now(),
          x: 10 + Math.random() * 80,
          y: 10 + Math.random() * 60,
          isGood: Math.random() > 0.3
        }]);
      }
    }, 1200);
    return () => clearInterval(interval);
  }, [targets]);

  const pop = (id: number, isGood: boolean) => {
    setTargets(prev => prev.filter(t => t.id !== id));
    if (isGood) {
      const next = Math.min(progress + 10, 100);
      setProgress(next);
      if (next >= 100) setTimeout(onComplete, 1000);
    } else {
      setProgress(prev => Math.max(0, prev - 15));
    }
  };

  return (
    <div className="flex flex-col items-center justify-between h-full w-full animate-fadeIn p-4 relative overflow-hidden">
      <div className="w-full text-center z-10">
        <h2 className="text-2xl font-black mb-2 drop-shadow-md">Happy Tap!</h2>
