const BathTime: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [dirtySpots, setDirtySpots] = useState([
    { id: 1, top: '40%', left: '30%' },
    { id: 2, top: '60%', left: '60%' },
    { id: 3, top: '30%', left: '55%' },
    { id: 4, top: '55%', left: '40%' }
  ]);

  const scrub = (id: number) => {
    setDirtySpots(prev => {
      const next = prev.filter(s => s.id !== id);
      if (next.length === 0) setTimeout(onComplete, 1500);
      return next;
    });
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full animate-fadeIn p-4 select-none">
      <h2 className="text-3xl font-black mb-8 text-center drop-shadow-md uppercase tracking-tighter italic">Scrub Peli Clean! 🧼</h2>
      <div className="w-64 h-64 relative bg-blue-400/20 rounded-full p-4 border-2 border-white/20">
        <PeliCharacter emotion="Neutral" isWet showParticles="bubbles" />
        {dirtySpots.map(s => (
          <div
            key={s.id}
            onMouseEnter={() => scrub(s.id)}
            onTouchStart={() => scrub(s.id)}
            className="absolute w-12 h-12 bg-amber-900/60 rounded-full blur-md animate-pulse cursor-pointer"
            style={{ top: s.top, left: s.left }}
          />
        ))}
      </div>
      <p className="mt-8 text-sm font-bold opacity-70">Wipe away the mud spots!</p>
    </div>
  );
};

const MusicPlayer: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [track, setTrack] = useState('Happy');
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    let interval: any;
    if (isPlaying) {
      interval = setInterval(() => {
        setProgress(p => {
          if (p >= 100) { onComplete(); return 100; }
          return p + 1;
        });
      }, 500);
    }
    return () => clearInterval(interval);
  }, [isPlaying, onComplete]);

  return (
    <div className="flex flex-col items-center justify-between h-full w-full animate-fadeIn p-4">
      <div className="w-full flex justify-center gap-2 mb-4">
        {['Calm', 'Happy', 'Energy'].map(t => (
          <button 
            key={t}
            onClick={() => { setTrack(t); setProgress(0); }}
            className={`px-4 py-1.5 rounded-full text-xs font-bold border transition-all ${track === t ? 'bg-white text-indigo-600' : 'bg-transparent text-white border-white/40'}`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="relative flex items-center justify-center w-full flex-grow">
        <div className={`w-56 h-56 transition-transform duration-500 ${isPlaying ? 'scale-110 animate-pulse' : 'scale-100'}`}>
          <PeliCharacter emotion={track === 'Calm' ? 'Relaxed' : track === 'Happy' ? 'Happy' : 'Excited'} accessories="headphones" showParticles={isPlaying ? 'notes' : null} />
        </div>
      </div>

      <div className="w-full bg-white/10 p-6 rounded-[2.5rem] backdrop-blur-md border border-white/20">
        <div className="flex items-center justify-center gap-8 mb-6">
          <button onClick={() => setIsPlaying(!isPlaying)} className="w-20 h-20 bg-white text-indigo-600 rounded-full flex items-center justify-center text-4xl shadow-xl active:scale-90 transition-all">
            {isPlaying ? '⏸️' : '▶️'}
          </button>
        </div>
        <div className="w-full h-1.5 bg-black/20 rounded-full overflow-hidden">
          <div className="h-full bg-white transition-all duration-300" style={{ width: `${progress}%` }} />
        </div>
      </div>
    </div>
  );
};

