          <div className="h-full bg-white transition-all duration-300 shadow-[0_0_10px_white]" style={{ width: `${progress}%` }} />
        </div>
        <p className="text-xs font-bold mt-2 opacity-80 uppercase tracking-widest">Pop the Happy Faces!</p>
      </div>

      <div className="flex-grow w-full relative">
        {targets.map(t => (
          <button
            key={t.id}
            onClick={() => pop(t.id, t.isGood)}
            className="absolute p-4 text-4xl animate-bounce transition-transform active:scale-150"
            style={{ left: `${t.x}%`, top: `${t.y}%` }}
          >
            {t.isGood ? '😊' : '☁️'}
