        ))}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-48 h-48 opacity-60">
            <PeliCharacter emotion={progress > 50 ? 'Happy' : 'Neutral'} scale={1 + (progress / 200)} />
          </div>
        </div>
      </div>
    </div>
  );
};

