        </div>
        <p className="text-xs font-bold mt-2 opacity-80 uppercase tracking-widest">Catch the Happy Faces, avoid clouds!</p>
      </div>

      <div className="flex-grow w-full relative">
        {targets.map(t => (
          <button
            key={t.id}
            onClick={() => pop(t.id, t.isGood)}
            className="absolute p-4 text-5xl animate-bounce transition-transform active:scale-150"
            style={{ left: `${t.x}%`, top: `${t.y}%` }}
          >
            {t.isGood ? '😊' : '☁️'}
          </button>
        ))}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-48 h-48 opacity-40">
            <PeliCharacter emotion={progress > 50 ? 'Happy' : 'Neutral'} scale={1 + (progress / 200)} />
          </div>
        </div>
      </div>
    </div>
  );
};

