// --- ENHANCED MEDITATE ---
const BreathingMode: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [phase, setPhase] = useState<'inhale' | 'hold' | 'exhale'>('inhale');
  const [timeLeft, setTimeLeft] = useState(4); 
  const [cycles, setCycles] = useState(0);

  useEffect(() => {
    if (cycles >= 3) { onComplete(); return; }
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (phase === 'inhale') { setPhase('hold'); return 4; }
          else if (phase === 'hold') { setPhase('exhale'); return 4; }
          else { setPhase('inhale'); setCycles(c => c + 1); return 4; }
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [phase, cycles, onComplete]);

  return (
    <div className="flex flex-col items-center justify-center flex-grow w-full py-8 text-center animate-fadeIn">
      <h2 className="text-4xl font-black mb-16 drop-shadow-md uppercase italic tracking-tighter">Breathe Peace</h2>

      <div className="relative mb-16 flex items-center justify-center">
        <div className={`absolute rounded-full border-[6px] border-white/40 transition-all duration-[4000ms] ease-in-out ${phase === 'inhale' ? 'w-80 h-80 scale-150 opacity-100' : phase === 'exhale' ? 'w-40 h-40 scale-75 opacity-20' : 'w-80 h-80 scale-150 opacity-60'}`} />
        <div className="w-56 h-56 relative z-10">
          <PeliCharacter 
            emotion={phase === 'exhale' ? 'Relaxed' : 'Neutral'} 
            scale={phase === 'inhale' ? 1.3 : phase === 'exhale' ? 0.7 : 1.3} 
            animationClass="transition-all duration-[4000ms] ease-in-out"
          />
        </div>
      </div>

      <p className="text-4xl font-black mb-4 uppercase tracking-[0.2em] text-white italic drop-shadow-sm">{phase === 'inhale' ? 'Breathe In' : phase === 'hold' ? 'Hold It' : 'Breathe Out'}</p>
      <div className="flex gap-4 mb-8">
        {[1, 2, 3].map(i => (
          <div key={i} className={`w-4 h-4 rounded-full transition-all duration-500 shadow-sm ${i <= cycles ? 'bg-white scale-125' : 'bg-white/20 scale-100'}`} />
        ))}
      </div>
      <p className="text-7xl font-mono font-black drop-shadow-lg">{timeLeft}</p>
    </div>
  );
};

// --- PRESERVED STORY AND FEEDING ACTIVITIES ---

const MAX_VOICEOVERS_PER_DAY = 10;
const STORIES = [
  {
    id: 1,
    title: "Peli's Colorful Day",
    icon: "🌈",
    scenes: [
