        { text: "Now I feel ready for a great day. Thanks for listening!", emotion: "Love" }
    ]
  },
  {
    id: 2,
    title: "The Brave Little Star",
    icon: "⭐",
    scenes: [
      { text: "Once there was a little star who was afraid of the dark.", emotion: "Fear" },
      { text: "He tried to hide behind a cloud, feeling very small.", emotion: "Sad" },
      { text: "But the moon said, 'You have a light inside you!'", emotion: "Neutral" },
      { text: "The little star took a deep breath and sparkled.", emotion: "Surprised" },
      { text: "He shone brighter than ever before! He felt so proud.", emotion: "Neutral" }
    ]
  }
];

const StoryMode: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
    const { userName, companionName } = useAppContext();
    const [storyList, setStoryList] = useState(STORIES);
    const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
    const [sceneIndex, setSceneIndex] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [isPaused, setIsPaused] = useState(false);
    const [isNarrating, setIsNarrating] = useState(false);
    const [hasStarted, setHasStarted] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isPickingTheme, setIsPickingTheme] = useState(false);

    const [quotaData, setQuotaData] = useState(() => {
        const saved = localStorage.getItem('story_quota');
        const today = new Date().toLocaleDateString();
        if (saved) {
            const parsed = JSON.parse(saved);
            if (parsed.date === today) return parsed;
        }
        return { date: today, count: 0 };
    });

    useEffect(() => {
        localStorage.setItem('story_quota', JSON.stringify(quotaData));
    }, [quotaData]);

    const audioContextRef = useRef<AudioContext | null>(null);
    const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
    const isCancelledRef = useRef(false);

    const initAudio = () => {
        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();
    };

    const stopPlayback = useCallback(() => {
        isCancelledRef.current = true;
        if (sourceNodeRef.current) {
            try { sourceNodeRef.current.stop(); } catch(e) {}
            sourceNodeRef.current = null;
        }
        setIsPlaying(false);
        setIsNarrating(false);
    }, []);

    const speakSceneGemini = async (index: number) => {
        if (selectedStoryIndex === null || isCancelledRef.current) return;
        if (quotaData.count >= MAX_VOICEOVERS_PER_DAY) {
            setIsNarrating(false);
            return;
        }
        const currentStory = storyList[selectedStoryIndex];
        const scene = currentStory.scenes[index];
        setIsNarrating(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: [{ parts: [{ text: scene.text }] }],
                config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } } },
            });
            if (isCancelledRef.current) return;
            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                initAudio();
                const ctx = audioContextRef.current!;
                const buffer = await decodePCM(decodeBase64ToUint8(base64Audio), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                sourceNodeRef.current = source;
                source.onended = () => {
                    setIsNarrating(false);
                    if (isCancelledRef.current) return;
                    setTimeout(() => {
                        if (isCancelledRef.current) return;
                        if (index < currentStory.scenes.length - 1) { setSceneIndex(index + 1); speakSceneGemini(index + 1); }
                        else onComplete();
                    }, 1200);
                };
                source.start();
                if (index === 0) setQuotaData(prev => ({ ...prev, count: prev.count + 1 }));
            }
        } catch (error) {
            setIsNarrating(false);
            setTimeout(() => {
                if (index < currentStory.scenes.length - 1) { setSceneIndex(index + 1); speakSceneGemini(index + 1); }
                else onComplete();
            }, 3000);
        }
    };

    const handleGenerateStory = async (selectedTheme: string) => {
        setIsPickingTheme(false);
        setIsGenerating(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const result = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Create an 8-scene children's story for ${userName}. Theme: ${selectedTheme}. Strict JSON: { "title": "...", "scenes": [{ "text": "...", "emotion": "..." }] }`,
                config: { responseMimeType: "application/json" }
            });
            const storyData = JSON.parse(result.text);
            const newStory = { id: Date.now(), title: storyData.title, icon: "✨", scenes: storyData.scenes };
            setStoryList(prev => [newStory, ...prev]);
            setSelectedStoryIndex(0);
            setHasStarted(false);
            setSceneIndex(0);
        } catch (e) {
            console.error("Generation failed", e);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleStart = () => {
        initAudio();
        isCancelledRef.current = false;
        setHasStarted(true);
        setIsPlaying(true);
        setIsPaused(false);
        if (quotaData.count < MAX_VOICEOVERS_PER_DAY) speakSceneGemini(0);
        else setIsPlaying(false);
    };

    const handleTogglePause = () => {
        if (isPaused) { setIsPaused(false); isCancelledRef.current = false; if (quotaData.count < MAX_VOICEOVERS_PER_DAY) speakSceneGemini(sceneIndex); }
        else { setIsPaused(true); stopPlayback(); isCancelledRef.current = true; }
    };

    const handleExitToLibrary = () => { stopPlayback(); isCancelledRef.current = true; setSelectedStoryIndex(null); setHasStarted(false); setIsPlaying(false); setIsPickingTheme(false); };

    if (isPickingTheme) {
        return (
            <div className="flex flex-col items-center w-full h-full animate-fadeIn p-4 overflow-y-auto scrollbar-hide">
                <div className="w-full flex justify-between items-center mb-6">
                    <button onClick={() => setIsPickingTheme(false)} className="w-12 h-12 flex items-center justify-center bg-white/20 hover:bg-white/30 rounded-full text-white border border-white/20 shadow-xl text-2xl">📚</button>
                    <span className="text-xl font-black text-white/80">Themes</span>
                </div>
                <h2 className="text-3xl font-black mb-2 text-center text-white drop-shadow-md">What theme?</h2>
                <div className="grid grid-cols-2 gap-4 w-full max-w-sm pb-10 mt-6">
                    {['Brave', 'Happy', 'Calm', 'Curious', 'Kind', 'Proud', 'Safe', 'Strong'].map(emo => (
                        <button key={emo} onClick={() => handleGenerateStory(emo)} className="bg-white/10 hover:bg-white/30 backdrop-blur-md p-6 rounded-[2.5rem] flex flex-col items-center gap-3 transition-all active:scale-95 border-2 border-white/10 shadow-xl group">
                            <span className="text-5xl group-hover:scale-125 transition-transform">{emo === 'Brave' ? '🛡️' : emo === 'Happy' ? '🎈' : emo === 'Calm' ? '☁️' : emo === 'Curious' ? '🔍' : emo === 'Kind' ? '💗' : emo === 'Safe' ? '🏠' : emo === 'Strong' ? '⚡' : '🏆'}</span>
                            <span className="font-black text-lg text-white uppercase tracking-tighter">{emo}</span>
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    if (selectedStoryIndex === null) {
        const quotaExceeded = quotaData.count >= MAX_VOICEOVERS_PER_DAY;
        return (
            <div className="flex flex-col items-center w-full h-full animate-fadeIn p-4">
                <h2 className="text-3xl font-black mb-6 text-center text-white drop-shadow-md">Story Library 📚</h2>
                <button disabled={isGenerating} onClick={() => setIsPickingTheme(true)} className="w-full bg-gradient-to-r from-violet-600 to-indigo-600 p-6 rounded-3xl flex items-center gap-4 transition-all active:scale-95 text-left shadow-2xl mb-8 border-2 border-white/20">
                    <span className="text-5xl">{isGenerating ? "🌀" : "✨"}</span>
                    <div>
                        <h3 className="font-black text-xl leading-tight text-white">{isGenerating ? "Writing..." : "Magic AI Story"}</h3>
                        <p className="text-sm font-bold text-indigo-100 opacity-90 italic">{quotaExceeded ? "Narrator sleeping 😴" : `${MAX_VOICEOVERS_PER_DAY - quotaData.count} narrations left today`}</p>
                    </div>
                </button>
                <div className="w-full space-y-4 overflow-y-auto pr-1 scrollbar-hide pb-10">
                    {storyList.map((story, idx) => (
                        <button key={story.id} onClick={() => { setSelectedStoryIndex(idx); setHasStarted(false); setSceneIndex(0); }} className="w-full bg-white/10 hover:bg-white/20 backdrop-blur-md p-5 rounded-3xl flex items-center gap-5 transition-all active:scale-95 text-left border border-white/10 shadow-lg group">
                            <span className="text-4xl group-hover:scale-110 transition-transform">{story.icon}</span>
                            <div className="flex-1">
                                <h3 className="font-black text-lg leading-tight text-white">{story.title}</h3>
                                <p className="text-xs font-bold text-white/60 uppercase">{story.scenes.length} Scenes</p>
                            </div>
                            <span className="text-white/30 text-2xl group-hover:translate-x-1 transition-transform">→</span>
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    const currentStory = storyList[selectedStoryIndex];
    const currentScene = currentStory.scenes[sceneIndex];
    const quotaExceeded = quotaData.count >= MAX_VOICEOVERS_PER_DAY;
    const progress = ((sceneIndex + 1) / currentStory.scenes.length) * 100;

    if (!hasStarted) {
        return (
            <div className="flex flex-col items-center justify-center flex-grow text-center relative w-full h-full p-6">
                <button onClick={() => setSelectedStoryIndex(null)} className="absolute top-4 left-4 w-12 h-12 flex items-center justify-center bg-white/20 hover:bg-white/30 rounded-full transition-all text-white border border-white/20 shadow-xl text-2xl">📚</button>
                <span className="text-8xl mb-6">{currentStory.icon}</span>
                <h2 className="text-4xl font-black mb-3 text-white drop-shadow-lg">{currentStory.title}</h2>
                <div className="w-48 h-48 mb-6"><PeliCharacter emotion="Happy" /></div>
                <p className="mb-10 text-lg font-bold text-indigo-100 max-w-xs leading-relaxed">{quotaExceeded ? "Narrator is resting, but you can still read it yourself!" : "Ready for an adventure narrated by Gemini AI?"}</p>
                <button onClick={handleStart} className="bg-white text-indigo-600 px-12 py-6 rounded-full font-black text-2xl shadow-2xl transform active:scale-90 transition-all hover:bg-indigo-50">READ NOW 📖</button>
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center justify-between flex-grow h-full py-4 w-full relative px-4">
            <div className="w-full h-2 bg-black/20 rounded-full overflow-hidden mb-4">
                <div className="h-full bg-white transition-all duration-500 ease-out" style={{ width: `${progress}%` }} />
            </div>
            <div className="w-full flex justify-between items-center mb-2">
                <button onClick={handleExitToLibrary} className="w-10 h-10 flex items-center justify-center bg-rose-500 hover:bg-rose-600 rounded-full transition-colors text-white shadow-lg text-xl">📚</button>
                <div className="text-[10px] font-black text-white bg-black/30 px-4 py-2 rounded-full border border-white/10 uppercase tracking-widest">Scene {sceneIndex + 1} of {currentStory.scenes.length}</div>
            </div>
            <div className="flex-grow flex items-center justify-center w-full max-h-[35%] my-4">
                <div className={`w-64 h-64 transition-transform duration-500 ${(isNarrating && !isPaused) ? 'scale-110' : 'scale-100'}`}>
                    <PeliCharacter emotion={currentScene.emotion} animationClass={(isNarrating && !isPaused) ? 'animate-pulse' : ''} />
                </div>
            </div>
            <div className="flex items-center w-full gap-2 mb-6">
                <button onClick={() => { stopPlayback(); setSceneIndex(prev => Math.max(0, prev - 1)); }} disabled={sceneIndex === 0} className={`w-12 h-12 rounded-full bg-white/10 flex items-center justify-center text-2xl transition-all ${sceneIndex === 0 ? 'opacity-20' : 'hover:bg-white/20 active:scale-90'}`}>⬅️</button>
                <div className="flex-1 bg-white/20 backdrop-blur-lg p-6 rounded-[40px] shadow-2xl border-2 border-white/20 flex flex-col justify-center min-h-[160px]">
                    <p className="text-xl font-black text-center text-white leading-relaxed drop-shadow-sm whitespace-pre-line font-serif">"{currentScene.text}"</p>
                </div>
                <button onClick={() => { stopPlayback(); setSceneIndex(prev => Math.min(currentStory.scenes.length - 1, prev + 1)); }} disabled={sceneIndex === currentStory.scenes.length - 1} className={`w-12 h-12 rounded-full bg-white/10 flex items-center justify-center text-2xl transition-all ${sceneIndex === currentStory.scenes.length - 1 ? 'opacity-20' : 'hover:bg-white/20 active:scale-90'}`}>➡️</button>
            </div>
            <div className="bg-white/10 p-6 rounded-[3rem] backdrop-blur-xl border border-white/10 flex items-center gap-10 shadow-2xl mb-6">
                <button onClick={handleTogglePause} disabled={quotaExceeded && !isPlaying} className={`w-20 h-20 bg-white text-indigo-600 rounded-full flex items-center justify-center text-4xl shadow-2xl transform active:scale-90 transition-all ${quotaExceeded && !isPlaying ? 'opacity-50 grayscale' : ''}`}>{isPaused ? '▶️' : '⏸️'}</button>
                <button onClick={handleExitToLibrary} className="w-16 h-16 bg-rose-500 text-white rounded-full flex items-center justify-center text-3xl shadow-xl transform active:scale-90 transition-all">⏹️</button>
            </div>
            {isNarrating && !isPaused && (
                <div className="flex items-center gap-3 text-[11px] font-black uppercase tracking-widest text-white/40 animate-pulse">
                    <div className="flex gap-1">
                        <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:-0.3s]" />
                        <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:-0.15s]" />
                        <span className="w-1 h-1 bg-white rounded-full animate-bounce" />
                    </div>
                    GEMINI AI NARRATING
                </div>
            )}
        </div>
    );
};

