      <div className="w-64 h-64 relative bg-blue-500/20 rounded-full p-8 border-4 border-white/20 shadow-inner">
        <PeliCharacter emotion="Neutral" isWet={phase === 'rinse'} bubbles={phase === 'lather' && dirtySpots.length < 4} />
        {phase === 'lather' && dirtySpots.map(s => (
          <div
            key={s.id}
            onMouseMove={() => scrub(s.id)}
