const StoryMode: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
    const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
    const [sceneIndex, setSceneIndex] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [hasStarted, setHasStarted] = useState(false);
    const isSpeechSupported = useMemo(() => typeof window !== 'undefined' && 'speechSynthesis' in window, []);
    const fallbackTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const isCancelledRef = useRef(false);

    useEffect(() => { if (isSpeechSupported) window.speechSynthesis.cancel(); }, [isSpeechSupported]);
    const stopPlayback = useCallback(() => { isCancelledRef.current = true; if (isSpeechSupported) window.speechSynthesis.cancel(); if (fallbackTimerRef.current) clearTimeout(fallbackTimerRef.current); setIsPlaying(false); }, [isSpeechSupported]);
    useEffect(() => { return () => { stopPlayback(); }; }, [stopPlayback]);

    const playScene = (index: number) => {
        if (selectedStoryIndex === null) return;
        const currentStory = STORIES[selectedStoryIndex];
        isCancelledRef.current = false;
        if (isSpeechSupported) { window.speechSynthesis.cancel(); window.speechSynthesis.resume(); }
        if (fallbackTimerRef.current) clearTimeout(fallbackTimerRef.current);
        if (index >= currentStory.scenes.length) { onComplete(); return; }
        const scene = currentStory.scenes[index];
        if (isSpeechSupported) {
            try {
                const u = new SpeechSynthesisUtterance(scene.text);
                u.rate = 0.45; u.pitch = 1.0; u.volume = 1.0;
                u.onend = () => {
                    if (isCancelledRef.current) return;
                    fallbackTimerRef.current = setTimeout(() => {
                       if (isCancelledRef.current) return;
                       if (index < currentStory.scenes.length - 1) { setSceneIndex(index + 1); playScene(index + 1); }
                       else { stopPlayback(); onComplete(); }
                    }, 1000);
                };
                (window as any)._speechUtterance = u; window.speechSynthesis.speak(u);
            } catch (e) {
                const readingTime = Math.max(2000, scene.text.split(' ').length * 300);
                fallbackTimerRef.current = setTimeout(() => { if (isCancelledRef.current) return; if (index < currentStory.scenes.length - 1) { setSceneIndex(index + 1); playScene(index + 1); } else onComplete(); }, readingTime);
            }
        }
    };

    if (selectedStoryIndex === null) {
        return (
            <div className="flex flex-col items-center w-full h-full animate-fadeIn text-white">
                <h2 className="text-2xl font-bold mb-4">Choose a Story</h2>
                <div className="flex-1 w-full overflow-y-auto px-2 space-y-3 pb-4 scrollbar-hide">
                    {STORIES.map((story, idx) => (
                        <button key={story.id} onClick={() => { setSelectedStoryIndex(idx); setHasStarted(false); }} className="w-full bg-white/20 hover:bg-white/30 p-4 rounded-2xl flex items-center gap-4 transition-transform active:scale-95 text-left"><span className="text-4xl">{story.icon}</span><div><h3 className="font-bold text-lg leading-tight">{story.title}</h3><p className="text-xs opacity-80">{story.scenes.length} scenes</p></div></button>
                    ))}
                </div>
            </div>
        );
    }
    const currentStory = STORIES[selectedStoryIndex];
    const currentScene = currentStory.scenes[sceneIndex];
    if (!hasStarted) {
        return (
            <div className="flex flex-col items-center justify-center flex-grow animate-fadeIn text-center relative w-full h-full text-white">
                <h2 className="text-2xl font-bold mb-2">{currentStory.title}</h2>
                <div className="w-48 h-48 mb-6 mt-4"><PeliCharacter emotion="Happy" /></div>
                <button onClick={() => { setHasStarted(true); setIsPlaying(true); setSceneIndex(0); playScene(0); }} className="bg-white text-indigo-600 px-8 py-4 rounded-full font-bold text-xl shadow-lg hover:scale-105 transition-transform">Start Story 📖</button>
            </div>
        );
    }
    return (
        <div className="flex flex-col items-center justify-between flex-grow animate-fadeIn h-full py-4 w-full relative text-white">
            <h3 className="text-xl font-bold opacity-70 text-center px-4 pt-4">{currentStory.title}</h3>
            <div className="flex-grow flex items-center justify-center w-full my-4"><div className={`w-64 h-64 transition-transform duration-500 ${isPlaying ? 'scale-105' : 'scale-100'}`}><PeliCharacter emotion={currentScene.emotion} /></div></div>
            <div className="bg-white/20 backdrop-blur-md p-6 rounded-3xl w-full max-w-xs mb-8 min-h-[150px] flex flex-col justify-center shadow-lg"><p className="text-2xl font-bold text-center leading-relaxed">"{currentScene.text}"</p></div>
        </div>
    );
};

