// --- ENHANCED BATH TIME ---
const BathTime: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [dirtySpots, setDirtySpots] = useState([
    { id: 1, top: '45%', left: '35%' },
    { id: 2, top: '65%', left: '55%' },
    { id: 3, top: '35%', left: '50%' },
    { id: 4, top: '55%', left: '45%' }
  ]);
  const [phase, setPhase] = useState<'lather'|'rinse'>('lather');
  const [rinseProgress, setRinseProgress] = useState(0);

  const scrub = (id: number) => {
    setDirtySpots(prev => {
      const next = prev.filter(s => s.id !== id);
      if (next.length === 0) setPhase('rinse');
      return next;
    });
  };

  useEffect(() => {
    if (phase === 'rinse' && rinseProgress >= 100) {
      setTimeout(onComplete, 1500);
    }
  }, [rinseProgress, phase, onComplete]);

  return (
    <div className="flex flex-col items-center justify-center h-full w-full animate-fadeIn p-4 select-none">
      <h2 className="text-3xl font-black mb-8 text-center drop-shadow-md uppercase italic text-white">
        {phase === 'lather' ? 'Scrub Peli! 🧼' : 'Rinse Off! 🚿'}
      </h2>
      <div className="w-64 h-64 relative bg-blue-500/20 rounded-full p-8 border-4 border-white/20 shadow-inner">
        <PeliCharacter emotion="Neutral" isWet={phase === 'rinse'} bubbles={phase === 'lather' && dirtySpots.length < 4} />
        {phase === 'lather' && dirtySpots.map(s => (
          <div
            key={s.id}
            onMouseMove={() => scrub(s.id)}
            onTouchMove={() => scrub(s.id)}
            className="absolute w-14 h-14 bg-amber-900/40 rounded-full blur-xl animate-pulse cursor-pointer hover:scale-0 transition-transform duration-500"
            style={{ top: s.top, left: s.left }}
          />
        ))}
        {phase === 'rinse' && (
          <div className="absolute inset-0 flex items-center justify-center overflow-hidden">
            <div className="w-full h-full animate-pulse bg-blue-400/20 rounded-full" />
          </div>
        )}
      </div>

      {phase === 'rinse' && (
        <button 
          onMouseDown={() => setRinseProgress(p => Math.min(p + 10, 100))}
