  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useAppContext = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

import React, { useMemo } from 'react';
import { useAppContext } from '../contexts/AppContext';

interface PeliProps {
  emotion: string; 
  animationClass?: string;
  showParticles?: 'hearts' | 'stars' | 'notes' | 'bubbles' | null; 
  customEyes?: string; 
  isGlowing?: boolean; 
  scale?: number; 
  accessories?: 'headphones' | null;
  isDirty?: boolean; 
  isWet?: boolean; 
  isHungry?: boolean; 
}

export const PeliCharacter: React.FC<PeliProps> = ({ 
    emotion, 
    animationClass = '', 
    showParticles = null, 
    customEyes, 
    isGlowing = false, 
    scale = 1, 
    accessories = null,
    isDirty = false,
    isWet = false,
    isHungry = false
}) => {
  const traits = useMemo(() => {
    let color = '#FFE8C7'; 
    let eyes = 'normal'; 
    let mouth = 'smile'; 
    let eyebrows = 'neutral'; 

    const normEmo = emotion.toLowerCase();

    if (['happy', 'excited', 'proud', 'confident', 'joy'].includes(normEmo)) {
      color = '#fcd34d'; 
      eyes = 'squint';
      mouth = 'open-smile';
      eyebrows = 'up';
    } else if (['sad', 'lonely', 'unhappy'].includes(normEmo)) {
      color = '#93c5fd'; 
      eyes = 'sad';
      mouth = 'frown';
      eyebrows = 'sad';
    } else if (['angry', 'mad', 'tense'].includes(normEmo)) {
      color = '#f87171'; 
      eyes = 'angry';
      mouth = 'frown';
      eyebrows = 'angry';
    } else if (['fear', 'scared', 'nervous', 'worried'].includes(normEmo)) {
      color = '#a5b4fc'; 
      eyes = 'wide';
      mouth = 'wavy';
      eyebrows = 'up';
    } else if (['surprised', 'curious', 'wow'].includes(normEmo)) {
      color = '#d8b4fe'; 
      eyes = 'wide';
      mouth = 'o-shape';
      eyebrows = 'up';
    } else if (normEmo === 'disgust') {
      color = '#84cc16'; 
      eyes = 'squint';
      mouth = 'wavy';
      eyebrows = 'angry';
    } else if (['love', 'grateful', 'relaxed', 'calm'].includes(normEmo)) {
      color = '#f472b6'; 
      eyes = 'happy-closed';
      mouth = 'smile';
      eyebrows = 'neutral';
    }

    if (customEyes) eyes = customEyes;

    return { color, eyes, mouth, eyebrows };
