          }
          @keyframes peliSway {
            0%, 100% { transform: translateY(0) rotate(0); }
            50% { transform: translateY(-5px) rotate(1deg); }
          }
          .animate-peli-blink {
            animation: peliBlink 4s infinite;
            transform-origin: center 80px;
          }
          .peli-idle {
            animation: peliSway 4s infinite ease-in-out;
