        <div className="absolute inset-0 text-2xl z-10 pointer-events-none overflow-hidden">
          <span className="absolute animate-bounce left-1/4 top-1/4">🫧</span>
          <span className="absolute animate-pulse right-1/4 bottom-1/4">🫧</span>
          <span className="absolute animate-ping left-1/2 bottom-1/2">🫧</span>
        </div>
      )}

      <svg
        viewBox="0 0 200 200"
        className={`w-full h-full transition-all duration-500 ease-in-out peli-idle ${isGlowing ? 'drop-shadow-[0_0_25px_rgba(255,255,255,0.8)] brightness-110' : 'drop-shadow-2xl'}`}
        style={{ transform: `scale(${scale})` }}
      >
        {/* Main Body */}
        <path
          d="M40,160 Q20,100 40,40 Q100,0 160,40 Q180,100 160,160 Q100,190 40,160 Z"
