import React, { useMemo } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { ConnectionStatus } from '../types';
import { PeliCharacter } from './PeliCharacter';

const StatusBadge: React.FC<{ status: ConnectionStatus, isDemo: boolean }> = ({ status, isDemo }) => {
  const statusConfig = useMemo(() => {
    if (isDemo) {
      return { text: 'Demo Mode (Simulated)', color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300', dotColor: 'bg-blue-500 animate-pulse' };
    }
    switch (status) {
      case 'connected':
        return { text: 'Sync Active', color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300', dotColor: 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' };
      case 'connecting':
        return { text: 'Linking to Azure...', color: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300', dotColor: 'bg-yellow-500 animate-pulse' };
      case 'error':
        return { text: 'Azure Link Offline', color: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300', dotColor: 'bg-orange-500' };
      default:
        return { text: 'Disconnected', color: 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300', dotColor: 'bg-gray-400' };
    }
  }, [status, isDemo]);

  return (
    <div className={`inline-flex items-center px-4 py-1.5 rounded-full text-xs font-bold shadow-sm transition-all duration-300 ${statusConfig.color} border border-white/20 dark:border-black/20`}>
      <span className={`w-2 h-2 mr-2 rounded-full ${statusConfig.dotColor}`}></span>
      {statusConfig.text}
    </div>
  );
};

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    connectionStatus, 
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    lastUpdate,
    isDemoMode,
    setIsDemoMode,
    isPeliDirty,
    isPeliHungry
  } = useAppContext();

  const isSyncActive = isSystemRunning && (connectionStatus === 'connected' || isDemoMode);

  const displayLabel = isSyncActive 
    ? currentEmotion 
    : isSystemRunning 
      ? 'Syncing...' 
      : 'System Idle';

  const emotionDetails = isSyncActive 
    ? EMOTION_DETAILS[currentEmotion] 
    : { color: 'text-gray-400', pulseColor: '#9ca3af' };

  const handleToggleSystem = () => {
    const newState = isSystemRunning ? 'stop' : 'start';
    toggleSystemState(newState);
  };

  const handleToggleDemo = () => {
    setIsDemoMode(!isDemoMode);
    if (!isDemoMode) {
      toggleSystemState('start');
    }
  };

  const buttonText = isSystemRunning ? 'Stop Pelioscope' : 'Start Pelioscope';
  const buttonColor = isSystemRunning ? 'bg-rose-500 hover:bg-rose-600' : 'bg-indigo-600 hover:bg-indigo-700';

  return (
    <div className="flex flex-col items-center justify-center h-full p-4 text-center">
