        <div className="relative flex items-center justify-center w-64 h-64 transition-all duration-700">
           <style>
            {`
              @keyframes pulseSlow {
                0%, 100% { transform: scale(1); opacity: 0.4; }
                50% { transform: scale(1.15); opacity: 0; }
              }
              .animate-emotion-glow {
                animation: pulseSlow 3s infinite ease-in-out;
              }
            `}
          </style>

          <div 
            className={`absolute inset-0 rounded-full transition-opacity duration-1000 ${isSyncActive ? 'opacity-100' : 'opacity-0'}`}
            style={{ backgroundColor: emotionDetails.pulseColor, filter: 'blur(50px)' }}
          ></div>

          <div 
            className={`absolute inset-0 rounded-full border-2 border-white/30 dark:border-white/10 ${isSyncActive ? 'animate-emotion-glow' : ''}`}
            style={{ borderColor: isSyncActive ? emotionDetails.pulseColor : 'rgba(156, 163, 175, 0.3)' } as React.CSSProperties}
          ></div>

           <div className={`w-64 h-64 transition-all duration-700 transform ${isSyncActive ? 'scale-110' : 'scale-90 grayscale-[0.5] opacity-40'}`}>
                <PeliCharacter 
                    emotion={isSyncActive ? currentEmotion : 'Neutral'} 
                    isDirty={isPeliDirty}
                    isHungry={isPeliHungry}
                    isGlowing={isSyncActive}
                />
           </div>
        </div>

        <h1 className={`mt-10 text-4xl font-black tracking-tight transition-colors duration-700 ${emotionDetails.color} drop-shadow-sm`}>
          {displayLabel}
        </h1>

        <div className={`mt-6 flex flex-col gap-2 items-center transition-all duration-500 ${isSystemRunning ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
             {isSyncActive && currentConfidence !== null && (
                 <div className="text-xs font-bold text-gray-600 dark:text-gray-300 bg-white/60 dark:bg-black/40 px-5 py-1.5 rounded-full shadow-sm backdrop-blur-md border border-white/20">
                     Confidence: {(currentConfidence * 100).toFixed(0)}%
                 </div>
             )}
             {lastUpdate !== null && (
                 <div className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest">
                     Last Sync: {new Date(lastUpdate).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                 </div>
             )}
        </div>

        <div className="mt-8 h-16 flex flex-col items-center justify-center max-w-[280px]">
            {connectionStatus === 'error' && isSystemRunning && !isDemoMode ? (
                <div className="bg-orange-50 dark:bg-orange-950/20 px-5 py-2.5 rounded-2xl border border-orange-200 dark:border-orange-800/50 text-orange-700 dark:text-orange-300 shadow-sm animate-fadeIn">
                    <span className="block mb-1 text-[10px] font-black uppercase">⚠️ Connection Alert</span>
                    <button 
                      onClick={handleToggleDemo}
                      className="text-xs font-bold underline decoration-2 underline-offset-4 hover:text-orange-900 dark:hover:text-white transition-colors"
                    >
                      Tap here to enable Demo Mode
                    </button>
                </div>
            ) : (
                <p className="text-gray-400 dark:text-gray-500 text-sm font-bold tracking-tight px-6 leading-tight">
                    {isDemoMode 
                      ? "Simulating emotion stream for testing..." 
                      : isSystemRunning 
                        ? "Streaming data from your Azure-linked device..." 
                        : "Connect your Pelioscope device and tap start."}
                </p>
            )}
        </div>
      </div>

      <div className="w-full max-w-sm pb-10">
        <button
          onClick={handleToggleSystem}
          className={`w-full text-white text-xl font-black py-6 px-8 rounded-3xl shadow-xl transition-all duration-300 transform active:scale-95 ${buttonColor}`}
        >
          {buttonText}
        </button>

        {isDemoMode && (
          <button 
            onClick={() => setIsDemoMode(false)}
            className="mt-6 text-xs font-black uppercase text-blue-500 tracking-wider hover:underline"
          >
            Turn Off Demo Mode
          </button>
        )}
      </div>
    </div>
  );
};

