import React, { useMemo } from 'react';

interface PeliProps {
  emotion: string; 
  animationClass?: string;
  showParticles?: 'hearts' | 'stars' | 'notes' | 'bubbles' | null; 
  customEyes?: string; 
  isGlowing?: boolean; 
  scale?: number; 
  accessories?: 'headphones' | null;
  isDirty?: boolean; 
  isWet?: boolean; 
  isHungry?: boolean; 
}

export const PeliCharacter: React.FC<PeliProps> = ({ 
    emotion, 
    animationClass = '', 
    showParticles = null, 
    customEyes, 
    isGlowing = false, 
    scale = 1, 
    accessories = null,
    isDirty = false,
    isWet = false,
    isHungry = false
}) => {
  const traits = useMemo(() => {
    let color = '#FFE8C7'; 
    let eyes = 'normal'; 
    let mouth = 'smile'; 
    let eyebrows = 'neutral'; 

    const normEmo = emotion.toLowerCase();

    if (['happy', 'excited', 'proud', 'confident', 'joy'].includes(normEmo)) {
      color = '#fcd34d'; 
      eyes = 'squint';
      mouth = 'open-smile';
      eyebrows = 'up';
    } else if (['sad', 'lonely', 'unhappy'].includes(normEmo)) {
      color = '#93c5fd'; 
      eyes = 'sad';
      mouth = 'frown';
      eyebrows = 'sad';
    } else if (['angry', 'mad', 'tense'].includes(normEmo)) {
      color = '#f87171'; 
      eyes = 'angry';
      mouth = 'frown';
      eyebrows = 'angry';
    } else if (['fear', 'scared', 'nervous', 'worried'].includes(normEmo)) {
      color = '#a5b4fc'; 
      eyes = 'wide';
      mouth = 'wavy';
      eyebrows = 'up';
    } else if (['surprised', 'curious', 'wow'].includes(normEmo)) {
      color = '#d8b4fe'; 
      eyes = 'wide';
      mouth = 'o-shape';
      eyebrows = 'up';
    } else if (normEmo === 'disgust') {
      color = '#84cc16'; 
      eyes = 'squint';
      mouth = 'wavy';
      eyebrows = 'angry';
    } else if (['love', 'grateful', 'relaxed', 'calm'].includes(normEmo)) {
      color = '#f472b6'; 
      eyes = 'happy-closed';
      mouth = 'smile';
      eyebrows = 'neutral';
    }

    if (customEyes) eyes = customEyes;

    return { color, eyes, mouth, eyebrows };
  }, [emotion, customEyes]);

  return (
    <div className={`relative w-full h-full shrink-0 flex items-center justify-center transition-all duration-500 ${animationClass}`}>
      <style>
        {`
          @keyframes peliBlink {
            0%, 90%, 100% { transform: scaleY(1); }
            95% { transform: scaleY(0.1); }
          }
          @keyframes peliSway {
            0%, 100% { transform: translateY(0) rotate(0); }
            50% { transform: translateY(-6px) rotate(1deg); }
          }
          .animate-peli-blink {
            animation: peliBlink 4s infinite;
            transform-origin: center 85px;
          }
          .peli-idle {
            animation: peliSway 5s infinite ease-in-out;
          }
