           )}

           {/* Right Eye */}
           {traits.eyes === 'normal' && (
             <g>
               <ellipse cx="130" cy="85" rx="13" ry="15" fill="#1e293b" />
               <circle cx="135" cy="79" r="4.5" fill="white" />
