           {traits.eyes === 'wide' && (
             <g>
                <circle cx="130" cy="85" r="16" fill="white" stroke="#1e293b" strokeWidth="2.5" />
                <circle cx="130" cy="85" r="7" fill="#1e293b" />
             </g>
           )}
           {traits.eyes === 'squint' && <path d="M115,90 Q130,75 145,90" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'happy-closed' && <path d="M115,85 Q130,75 145,85" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'sad' && <path d="M115,80 Q130,90 145,80" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'angry' && (
