const CACHE_NAME = 'emotion-companion-cache-v6';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/App.tsx',
  '/types.ts',
  '/constants.ts',
  '/hooks/useLocalStorage.ts',
  '/contexts/AppContext.tsx',
  '/components/Icons.tsx',
  '/components/TabNavigator.tsx',
  '/components/LiveTab.tsx',
  '/components/ChatTab.tsx',
  '/components/ActivitiesTab.tsx',
  '/components/ActivityModal.tsx',
  '/components/PeliCharacter.tsx',
  '/components/StatsTab.tsx',
  '/components/SettingsTab.tsx',
  '/components/SplashScreen.tsx',
  'https://cdn.tailwindcss.com'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          response => {
            if (!response || response.status !== 200 || (response.type !== 'basic' && response.type !== 'cors')) {
              return response;
            }

            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then(cache => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import React, { useMemo } from 'react';

interface PeliProps {
  emotion: string; 
  animationClass?: string;
  showParticles?: 'hearts' | 'stars' | 'notes' | 'bubbles' | null; 
  customEyes?: string; 
  isGlowing?: boolean; 
  scale?: number; 
  accessories?: 'headphones' | null;
  isDirty?: boolean; 
  isWet?: boolean; 
  isHungry?: boolean; 
}

export const PeliCharacter: React.FC<PeliProps> = ({ 
    emotion, 
    animationClass = '', 
    showParticles = null, 
    customEyes, 
    isGlowing = false, 
    scale = 1, 
    accessories = null,
    isDirty = false,
    isWet = false,
    isHungry = false
}) => {
  const traits = useMemo(() => {
    let color = '#FFE8C7'; 
    let eyes = 'normal'; 
    let mouth = 'smile'; 
    let eyebrows = 'neutral'; 

    const normEmo = emotion.toLowerCase();

    if (['happy', 'excited', 'proud', 'joy'].includes(normEmo)) {
      color = '#fcd34d'; 
      eyes = 'squint';
      mouth = 'open-smile';
      eyebrows = 'up';
    } else if (['sad', 'lonely', 'unhappy'].includes(normEmo)) {
      color = '#93c5fd'; 
      eyes = 'sad';
      mouth = 'frown';
      eyebrows = 'sad';
    } else if (['angry', 'mad', 'tense'].includes(normEmo)) {
      color = '#f87171'; 
      eyes = 'angry';
      mouth = 'frown';
      eyebrows = 'angry';
    } else if (['fear', 'scared', 'nervous', 'worried'].includes(normEmo)) {
      color = '#a5b4fc'; 
      eyes = 'wide';
      mouth = 'wavy';
      eyebrows = 'up';
    } else if (['surprised', 'curious', 'wow'].includes(normEmo)) {
      color = '#d8b4fe'; 
      eyes = 'wide';
      mouth = 'o-shape';
      eyebrows = 'up';
    } else if (normEmo === 'disgust') {
      color = '#84cc16'; 
      eyes = 'squint';
      mouth = 'wavy';
      eyebrows = 'angry';
    } else if (['love', 'grateful', 'relaxed', 'calm'].includes(normEmo)) {
      color = '#f472b6'; 
      eyes = 'happy-closed';
      mouth = 'smile';
      eyebrows = 'neutral';
    }

    if (customEyes) eyes = customEyes;

    return { color, eyes, mouth, eyebrows };
  }, [emotion, customEyes]);

  return (
    <div className={`relative w-full h-full flex items-center justify-center transition-all duration-500 ${animationClass}`}>
      <style>
        {`
          @keyframes peliBlink {
            0%, 90%, 100% { transform: scaleY(1); }
            95% { transform: scaleY(0.1); }
          }
          @keyframes peliSway {
            0%, 100% { transform: translateY(0) rotate(0); }
            50% { transform: translateY(-8px) rotate(1deg); }
          }
          .animate-peli-blink {
            animation: peliBlink 4s infinite;
            transform-origin: center 85px;
          }
          .peli-idle {
            animation: peliSway 5s infinite ease-in-out;
          }
        `}
      </style>

      {showParticles === 'hearts' && <div className="absolute inset-0 text-4xl animate-ping opacity-50 z-10 pointer-events-none flex items-center justify-center">❤️</div>}
      {showParticles === 'stars' && <div className="absolute -top-4 -right-4 text-4xl animate-bounce z-10 pointer-events-none">⭐</div>}
      {showParticles === 'notes' && <div className="absolute -top-4 -left-4 text-4xl animate-pulse z-10 pointer-events-none">🎵</div>}
      {showParticles === 'bubbles' && (
        <div className="absolute inset-0 text-2xl z-10 pointer-events-none overflow-hidden">
          <span className="absolute animate-bounce left-1/4 top-1/4">🫧</span>
          <span className="absolute animate-pulse right-1/4 bottom-1/4">🫧</span>
          <span className="absolute animate-ping left-1/2 bottom-1/2">🫧</span>
        </div>
      )}

      <svg
        viewBox="0 0 200 200"
        className={`w-full h-full transition-all duration-500 ease-in-out peli-idle ${isGlowing ? 'drop-shadow-[0_0_35px_rgba(255,255,255,0.7)]' : 'drop-shadow-2xl'}`}
        style={{ transform: `scale(${scale})` }}
      >
        {/* Main Body */}
        <path
          d="M40,160 Q20,100 40,40 Q100,0 160,40 Q180,100 160,160 Q100,190 40,160 Z"
          fill={traits.color}
          className="transition-colors duration-500 ease-in-out"
        />

        {/* Shine highlight */}
        <ellipse cx="140" cy="60" rx="10" ry="5" fill="white" fillOpacity="0.4" transform="rotate(-45 140 60)" />

        {/* Dirty Spots */}
        {isDirty && (
          <g fill="#78350f" fillOpacity="0.4">
             <circle cx="60" cy="140" r="8" />
             <circle cx="150" cy="130" r="10" />
             <circle cx="100" cy="50" r="6" />
