        {/* Eyes Group with Blinking */}
        <g className="animate-peli-blink">
           {/* Left Eye */}
           {traits.eyes === 'normal' && (
             <g>
               <ellipse cx="70" cy="85" rx="13" ry="15" fill="#1e293b" />
               <circle cx="75" cy="79" r="4.5" fill="white" />
             </g>
           )}
           {traits.eyes === 'wide' && (
             <g>
               <circle cx="70" cy="85" r="16" fill="white" stroke="#1e293b" strokeWidth="2.5" />
               <circle cx="70" cy="85" r="7" fill="#1e293b" />
             </g>
           )}
           {traits.eyes === 'squint' && <path d="M55,90 Q70,75 85,90" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'happy-closed' && <path d="M55,85 Q70,75 85,85" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'sad' && <path d="M55,80 Q70,90 85,80" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />}
           {traits.eyes === 'angry' && (
             <g>
                <path d="M55,77 L85,87" stroke="#1e293b" strokeWidth="4" fill="none" strokeLinecap="round" />
                <circle cx="70" cy="90" r="8" fill="#1e293b" />
