const MoodBoost: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [progress, setProgress] = useState(0);
  const [targets, setTargets] = useState<{ id: number, x: number, y: number, isGood: boolean }[]>([]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (targets.length < 5) {
        setTargets(prev => [...prev, {
          id: Date.now(),
          x: 10 + Math.random() * 80,
          y: 10 + Math.random() * 60,
          isGood: Math.random() > 0.25
        }]);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [targets]);

  const pop = (id: number, isGood: boolean) => {
    setTargets(prev => prev.filter(t => t.id !== id));
    if (isGood) {
      const next = Math.min(progress + 10, 100);
      setProgress(next);
      if (next >= 100) setTimeout(onComplete, 1000);
    } else {
      setProgress(prev => Math.max(0, prev - 15));
    }
  };

  return (
    <div className="flex flex-col items-center justify-between h-full w-full animate-fadeIn relative overflow-hidden p-4">
      <div className="w-full text-center z-10">
        <h2 className="text-3xl font-black mb-2 drop-shadow-md italic uppercase text-white">Happy Pop!</h2>
        <div className="w-full h-4 bg-black/20 rounded-full overflow-hidden border-2 border-white/20">
          <div className="h-full bg-white transition-all duration-300 shadow-[0_0_15px_white]" style={{ width: `${progress}%` }} />
        </div>
        <p className="text-xs font-bold mt-2 opacity-80 uppercase tracking-widest text-white">Catch the Happy Faces!</p>
      </div>

      <div className="flex-grow w-full relative">
        {targets.map(t => (
          <button
            key={t.id}
            onClick={() => pop(t.id, t.isGood)}
            className="absolute p-4 text-5xl animate-bounce transition-transform active:scale-150"
            style={{ left: `${t.x}%`, top: `${t.y}%` }}
          >
            {t.isGood ? '😊' : '☁️'}
          </button>
        ))}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-48 h-48 opacity-40">
            <PeliCharacter emotion={progress > 50 ? 'Happy' : 'Neutral'} scale={1 + (progress / 200)} />
          </div>
        </div>
      </div>
    </div>
  );
};

