import React, { createContext, useContext, useState, useRef, useCallback, ReactNode, useEffect, useMemo } from 'react';
import useLocalStorage from '../hooks/useLocalStorage';
import { Emotion, ActivityLog, EmotionLog, ConnectionStatus, SUPPORTED_EMOTIONS, EquippedItems } from '../types';
import { SHOP_ITEMS } from '../constants';

// The Azure host provided
const AZURE_HOST = 'emotion-pelio.qkbybag7ckc2lzii9.eastasia.azurecontainer.io:8000';

type Theme = 'light' | 'dark';

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;
  currentEmotion: Emotion;
  currentConfidence: number | null;
  lastUpdate: number | null;
  emotionHistory: EmotionLog[];
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;
  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  toggleSystemState: (state: 'start' | 'stop') => void;
  isSystemRunning: boolean;
  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliDirty: boolean;
  hungerLevel: number;
  feedPeli: (amount: number) => void;
  isPeliHungry: boolean;

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
  isDemoMode: boolean;
  setIsDemoMode: (val: boolean) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useUserNameStorage('userName', '');
  const [userPin, setUserPin] = useLocalStorage('userPin', ''); 

  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');

  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [hungerLevel, setHungerLevel] = useLocalStorage<number>('hungerLevel', 50); 
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', Date.now());

  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
      hat: null,
      clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState<boolean>(false);
  const [isDemoMode, setIsDemoMode] = useState<boolean>(false);

  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('connecting');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const socketRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const calculateDecay = () => {
        const now = Date.now();
        const diff = now - lastFedTime;
        const msPerPoint = 72000; 
        const pointsLost = Math.floor(diff / msPerPoint);

        if (pointsLost > 0) {
            setHungerLevel(prev => Math.max(0, prev - pointsLost));
            setLastFedTime(now);
        }
    };
    calculateDecay();
    const interval = setInterval(calculateDecay, 60000);
    return () => clearInterval(interval);
  }, [lastFedTime, setHungerLevel, setLastFedTime]);

  const feedPeli = useCallback((amount: number) => {
      setHungerLevel(prev => Math.min(100, prev + amount));
      setLastFedTime(Date.now());
  }, [setHungerLevel, setLastFedTime]);

  const isPeliHungry = useMemo(() => hungerLevel < 50, [hungerLevel]);
  const isPeliDirty = useMemo(() => (Date.now() - lastShowerTime) > (3 * 60 * 60 * 1000), [lastShowerTime]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isDemoMode && isSystemRunning) {
      interval = setInterval(() => {
        const emotions: Emotion[] = ['Happy', 'Sad', 'Angry', 'Surprised', 'Fear', 'Neutral', 'Disgust'];
        const randomEmotion = emotions[Math.floor(Math.random() * emotions.length)];
        setCurrentEmotion(randomEmotion);
        setCurrentConfidence(Math.random() * 0.2 + 0.8);
        setLastUpdate(Date.now());
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [isDemoMode, isSystemRunning]);

  const connectToAzure = useCallback(() => {
    if (socketRef.current) {
        socketRef.current.close();
    }

    // Determine Protocol: wss:// for https sites, ws:// for http sites
    const isSecure = window.location.protocol === 'https:';
    const protocol = isSecure ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${AZURE_HOST}`;

    setConnectionStatus('connecting');
    setConnectionError(null);

    try {
        const socket = new WebSocket(wsUrl);
        socketRef.current = socket;

        socket.onopen = () => {
          setConnectionStatus('connected');
          setConnectionError(null);
          socket.send(JSON.stringify({ type: 'request_sync' }));
        };

        socket.onmessage = (event) => {
          try {
            const message = JSON.parse(event.data);
            if (message.type === 'emotion_output') {
              if (isDemoMode) return;
              const data = message.data;
              let label = data.label || data.emotion || '';
              let confidence = data.score || data.confidence || null;
              let timestamp = data.timestamp || Date.now();
              if (!label) return;
              const normalized = label.toString().toLowerCase().trim();
              const synonymMap: Record<string, Emotion> = {
                'happy': 'Happy', 'joy': 'Happy', 'excited': 'Happy',
                'sad': 'Sad', 'angry': 'Angry', 'mad': 'Mad',
                'fear': 'Fear', 'surprised': 'Surprised',
                'disgust': 'Disgust', 'neutral': 'Neutral'
              };
              let matched = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);
              if (matched) {
                setCurrentEmotion(matched);
                setCurrentConfidence(confidence);
                setLastUpdate(timestamp);
                setEmotionHistory(prev => {
                  if (prev.length === 0 || prev[0].emotion !== matched) {
                    return [{ id: Date.now().toString(), emotion: matched!, detectedAt: Date.now() }, ...prev].slice(0, 100);
                  }
                  return prev;
                });
              }
            }
            if (message.type === 'system_state') {
              setIsSystemRunning(message.state === 'start');
            }
          } catch (err) {
            console.error("Error parsing message:", err);
          }
        };

        socket.onerror = (error) => {
          setConnectionStatus('error');
          if (isSecure) {
              setConnectionError(`Security Block: Your browser blocks insecure "ws://" connections from "https://" sites. If your Azure container doesn't have an SSL certificate, use "Demo Mode" for testing.`);
          } else {
              setConnectionError("Azure Server connection failed. Ensure the server is online.");
          }
        };

        socket.onclose = () => {
          setConnectionStatus('disconnected');
          // Wait 10 seconds and try again if system is still intended to be running
          setTimeout(() => {
              if (isSystemRunning) connectToAzure();
          }, 10000);
        };
    } catch (e) {
        setConnectionStatus('error');
        setConnectionError("Failed to initialize WebSocket. Check your connection settings.");
    }
  }, [setEmotionHistory, isDemoMode, isSystemRunning]);

  useEffect(() => {
    connectToAzure();
    return () => {
      if (socketRef.current) socketRef.current.close();
    };
  }, [connectToAzure]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({ type: 'set_state', state: state }));
      setIsSystemRunning(state === 'start');
    } else {
      setIsSystemRunning(state === 'start');
      if (state === 'start') connectToAzure();
    }
  }, [connectToAzure]);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(prev => prev === 'light' ? 'dark' : 'light'), [setTheme]);

  const earnDrachma = useCallback((amount: number) => setDrachma(prev => prev + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
      if (drachma >= amount) { setDrachma(prev => prev - amount); return true; }
      return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
      const shopItem = SHOP_ITEMS.find(i => i.id === itemId);
      const isConsumable = shopItem?.category === 'food';
      const isOwned = inventory.includes(itemId);
      if (!isConsumable && isOwned) return true;
      if (drachma >= price) {
          setDrachma(prev => prev - price);
          setInventory(prev => [...prev, itemId]);
          return true;
      }
      return false;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
      setInventory(prev => {
          const idx = prev.indexOf(itemId);
          if (idx > -1) {
              const newInv = [...prev];
              newInv.splice(idx, 1);
              return newInv;
          }
          return prev;
      });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
      setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    const newLog: ActivityLog = { id: Date.now().toString(), activityName, completedAt: Date.now() };
    setActivityHistory(prev => [newLog, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const contextValue: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError,
    toggleSystemState, isSystemRunning, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, lastFedTime, setLastFedTime, isPeliDirty, hungerLevel, feedPeli, isPeliHungry,
    drachma, earnDrachma, spendDrachma, inventory, equippedItems, buyItem, equipItem, consumeItem,
    isDemoMode, setIsDemoMode
  };

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

// Helper to handle potential naming conflicts in different app builds
function useUserNameStorage(key: string, initial: string): [string, (v: string) => void] {
    return useLocalStorage(key, initial);
}

export const useAppContext = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

import React, { useMemo } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { ConnectionStatus } from '../types';

const StatusBadge: React.FC<{ status: ConnectionStatus, isDemo: boolean }> = ({ status, isDemo }) => {
  const statusConfig = useMemo(() => {
    if (isDemo) {
        return { text: 'Demo Mode', color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200', dotColor: 'bg-blue-500 animate-pulse' };
    }
    switch (status) {
      case 'connected':
        return { text: 'Live Sync', color: 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200', dotColor: 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' };
      case 'connecting':
        return { text: 'Linking...', color: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-200', dotColor: 'bg-yellow-500 animate-pulse' };
      case 'error':
        return { text: 'Offline', color: 'bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-200', dotColor: 'bg-red-500' };
      default:
        return { text: 'Disconnected', color: 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300', dotColor: 'bg-gray-400' };
    }
  }, [status, isDemo]);

  return (
    <div className={`inline-flex items-center px-4 py-1.5 rounded-full text-xs font-bold transition-all duration-300 ${statusConfig.color}`}>
      <span className={`w-2 h-2 mr-2 rounded-full ${statusConfig.dotColor}`}></span>
      {statusConfig.text}
    </div>
  );
};

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    connectionStatus, 
    connectionError, 
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    lastUpdate,
    isDemoMode,
    setIsDemoMode
  } = useAppContext();

  const idleDetails = {
    emoji: '😴',
    color: 'text-gray-300 dark:text-gray-600',
    pulseColor: '#d1d5db'
  };

  const isSyncing = isSystemRunning && (connectionStatus === 'connected' || isDemoMode);
  const emotionDetails = isSyncing ? EMOTION_DETAILS[currentEmotion] : idleDetails;
  const displayLabel = isSyncing ? currentEmotion : 'System Idle';

  const handleToggleSystem = () => {
    const newState = isSystemRunning ? 'stop' : 'start';
    toggleSystemState(newState);
  };

  const buttonText = isSystemRunning ? 'Stop Pelioscope' : 'Start Pelioscope';
  const buttonColor = isSystemRunning ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-200 dark:shadow-rose-900/20' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200 dark:shadow-indigo-900/20';

  return (
    <div className="flex flex-col items-center justify-center h-full p-4 text-center">
      <div className="absolute top-6">
        <StatusBadge status={connectionStatus} isDemo={isDemoMode} />
      </div>

      <div className="flex-grow flex flex-col items-center justify-center w-full">
        <div className="relative flex items-center justify-center w-64 h-64 rounded-full transition-all duration-700">
           <style>
            {`
              @keyframes pulseEmotion {
                0%, 100% { transform: scale(1); opacity: 0.5; }
                50% { transform: scale(1.15); opacity: 0.1; }
              }
              .animate-glow {
                animation: pulseEmotion 3s infinite ease-in-out;
              }
            `}
          </style>

          <div 
            className={`absolute inset-0 rounded-full transition-all duration-1000 ${isSyncing ? 'animate-glow' : ''}`}
            style={{ backgroundColor: emotionDetails.pulseColor, filter: 'blur(40px)' }}
          ></div>

          <div 
            className={`absolute inset-0 rounded-full border-2 border-white/20 dark:border-white/5 ${isSyncing ? 'animate-glow' : ''}`}
            style={{ borderColor: emotionDetails.pulseColor } as React.CSSProperties}
          ></div>

           <span
            className={`text-[120px] relative z-10 transition-all duration-700 transform ${isSyncing ? 'scale-110' : 'scale-90 grayscale opacity-40'}`}
            style={{ filter: isSyncing ? `drop-shadow(0 0 20px ${emotionDetails.pulseColor}80)` : 'none'}}
            >
                {emotionDetails.emoji}
           </span>
        </div>

        <h1 className={`mt-10 text-4xl font-black tracking-tight transition-colors duration-700 ${isSyncing ? emotionDetails.color : 'text-gray-400 dark:text-gray-600'}`}>
          {displayLabel}
        </h1>

        <div className={`mt-6 flex flex-col gap-1 items-center transition-all duration-500 ${isSyncing ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
             {currentConfidence !== null && (
                 <div className="text-xs font-bold text-gray-600 dark:text-gray-300 bg-white/60 dark:bg-black/40 px-4 py-1.5 rounded-full shadow-sm backdrop-blur-md border border-white/20">
                     Confidence: {(currentConfidence * 100).toFixed(0)}%
                 </div>
             )}
             {lastUpdate !== null && (
                 <div className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest mt-1">
                     Sync: {new Date(lastUpdate).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                 </div>
             )}
        </div>

        <div className="mt-8 h-20 flex flex-col items-center justify-center">
            {connectionStatus === 'error' && isSystemRunning && !isDemoMode ? (
                <div className="bg-red-50 dark:bg-red-950/20 px-6 py-3 rounded-2xl border border-red-200 dark:border-red-900/50 max-w-xs animate-fadeIn">
                    <p className="text-xs text-red-700 dark:text-red-300 font-bold leading-relaxed">
                        {connectionError}
                    </p>
                    <button 
                        onClick={() => setIsDemoMode(true)}
                        className="mt-2 text-xs font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-tighter hover:underline"
                    >
                        Try Demo Mode instead ➔
                    </button>
                </div>
            ) : (
                <p className="text-gray-400 dark:text-gray-500 text-sm font-medium px-8 leading-relaxed">
                    {isDemoMode 
                      ? "Simulating PelioScope data stream..." 
                      : isSyncing 
                        ? "Receiving live data from your Azure server." 
                        : "Connect your edge device to start monitoring emotions."}
                </p>
            )}
        </div>
      </div>

      <div className="w-full max-w-sm pb-10">
        <button
          onClick={handleToggleSystem}
          className={`w-full text-white font-black text-lg py-5 px-4 rounded-2xl shadow-xl transition-all duration-300 transform active:scale-95 ${buttonColor}`}
        >
          {buttonText}
        </button>

        {isDemoMode && (
             <button 
                onClick={() => setIsDemoMode(false)}
                className="mt-4 text-xs font-black uppercase text-gray-400 hover:text-indigo-500 transition-colors"
             >
                Turn off Demo Mode
             </button>
        )}
      </div>
    </div>
  );
};

