import okhttp3.*
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.asRequestBody
import org.json.JSONObject
import java.io.File
import java.io.IOException

class EmotionDetectionAPI {
    private val client = OkHttpClient()
    private val apiUrl = "http://20.6.159.98:8000/predict"

    fun detectEmotion(imageFile: File, callback: (EmotionResponse?) -> Unit) {
        val requestBody = MultipartBody.Builder()
            .setType(MultipartBody.FORM)
            .addFormDataPart(
                "file",
                imageFile.name,
                imageFile.asRequestBody("image/jpeg".toMediaType())
            )
            .build()

        val request = Request.Builder()
            .url(apiUrl)
            .post(requestBody)
            .build()

        client.newCall(request).enqueue(object : Callback {
            override fun onFailure(call: Call, e: IOException) {
                callback(null)
            }

            override fun onResponse(call: Call, response: Response) {
                response.body?.string()?.let { json ->
                    val emotionResponse = parseResponse(json)
                    callback(emotionResponse)
                }
            }
        })
    }

    private fun parseResponse(json: String): EmotionResponse {
        val jsonObject = JSONObject(json)
        val results = mutableListOf<EmotionResult>()

        if (jsonObject.getBoolean("success")) {
            val resultsArray = jsonObject.getJSONArray("results")
            for (i in 0 until resultsArray.length()) {
                val result = resultsArray.getJSONObject(i)
                val bbox = result.getJSONObject("bbox")

                results.add(
                    EmotionResult(
                        emotion = result.getString("emotion"),
                        confidence = result.getDouble("confidence"),
                        bbox = BoundingBox(
                            x = bbox.getInt("x"),
                            y = bbox.getInt("y"),
                            width = bbox.getInt("width"),
                            height = bbox.getInt("height")
                        )
                    )
                )
            }
        }

        return EmotionResponse(
            success = jsonObject.getBoolean("success"),
            facesDetected = jsonObject.getInt("faces_detected"),
            results = results
        )
    }
}

data class EmotionResponse(
    val success: Boolean,
    val facesDetected: Int,
    val results: List<EmotionResult>
)

data class EmotionResult(
    val emotion: String,
    val confidence: Double,
    val bbox: BoundingBox
)

data class BoundingBox(
    val x: Int,
    val y: Int,
    val width: Int,
    val height: Int
)

