  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  // Handle Camera Stream
  useEffect(() => {
    if (isSystemRunning && dataSource === 'camera') {
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false })
            .then(s => {
                setStream(s);
                if (videoRef.current) videoRef.current.srcObject = s;
            })
            .catch(err => console.error("Camera access denied", err));
    } else {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
    }
    return () => stream?.getTracks().forEach(t => t.stop());
  }, [isSystemRunning, dataSource]);

  // Periodic Camera Capture
  useEffect(() => {
    let interval: any;
    if (isSystemRunning && dataSource === 'camera' && stream) {
        interval = setInterval(() => {
            if (videoRef.current && canvasRef.current) {
                const video = videoRef.current;
                const canvas = canvasRef.current;
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    canvas.toBlob(blob => {
                        if (blob) detectFromCamera(blob);
                    }, 'image/jpeg', 0.8);
                }
            }
        }, 3000); // Check every 3 seconds
    }
    return () => clearInterval(interval);
  }, [isSystemRunning, dataSource, stream, detectFromCamera]);

