      interval = setInterval(() => {
        const randomEmotion = SUPPORTED_EMOTIONS[Math.floor(Math.random() * SUPPORTED_EMOTIONS.length)];
        updateEmotionFromData(randomEmotion, 0.85 + Math.random() * 0.1);
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [isDemoMode, isSystemRunning]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    setIsSystemRunning(state === 'start');
  }, []);

  const toggleTheme = useCallback(() => setTheme(prev => prev === 'light' ? 'dark' : 'light'), [setTheme]);
  const earnDrachma = useCallback((amount: number) => setDrachma(prev => prev + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
      if (drachma >= amount) { setDrachma(prev => prev - amount); return true; }
      return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
      if (drachma >= price) {
          setDrachma(prev => prev - price);
          setInventory(prev => [...prev, itemId]);
          return true;
      }
      return false;
  }, [drachma, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
      setInventory(prev => {
          const idx = prev.indexOf(itemId);
          if (idx > -1) {
              const newInv = [...prev];
              newInv.splice(idx, 1);
              return newInv;
          }
          return prev;
      });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
      setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  return (
    <AppContext.Provider value={{
      companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
      currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
      addActivityLog, clearHistory, connectionStatus, connectionError,
      toggleSystemState, isSystemRunning, theme, toggleTheme,
      lastShowerTime, setLastShowerTime, lastFedTime, setLastFedTime, isPeliDirty, hungerLevel, feedPeli, isPeliHungry,
      drachma, earnDrachma, spendDrachma, inventory, equippedItems, buyItem, equipItem, consumeItem,
      isDemoMode, setIsDemoMode, dataSource, setDataSource, detectFromCamera
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppContext = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

const CACHE_NAME = 'emotion-companion-cache-v4';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/App.tsx',
  '/types.ts',
  '/constants.ts',
  '/hooks/useLocalStorage.ts',
  '/contexts/AppContext.tsx',
  '/components/Icons.tsx',
  '/components/TabNavigator.tsx',
  '/components/LiveTab.tsx',
  '/components/ChatTab.tsx',
  '/components/ActivitiesTab.tsx',
  '/components/ActivityModal.tsx',
  '/components/StatsTab.tsx',
  '/components/SettingsTab.tsx',
  '/components/SplashScreen.tsx',
  'https://cdn.tailwindcss.com'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  // FIX: Do not intercept non-GET requests (like POST to the API) 
  // and skip the Azure IP to avoid Mixed Content/CORS issues being swallowed by the SW.
  if (event.request.method !== 'GET' || event.request.url.includes('20.6.159.98')) {
    return;
  }

  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          response => {
            if (!response || response.status !== 200 || (response.type !== 'basic' && response.type !== 'cors')) {
              return response;
            }

            const responseToCache = response.clone();
            caches.open(CACHE_NAME)
              .then(cache => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import React, { createContext, useContext, useState, useRef, useCallback, ReactNode, useEffect, useMemo } from 'react';
import useLocalStorage from '../hooks/useLocalStorage';
import { Emotion, ActivityLog, EmotionLog, ConnectionStatus, SUPPORTED_EMOTIONS, EquippedItems, Theme, DataSource } from '../types';
import { SHOP_ITEMS } from '../constants';

const AZURE_SERVER_IP = '20.6.159.98';
const AZURE_WS_PORT = '8000';
const AZURE_REST_PORT = '8000';

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;
  currentEmotion: Emotion;
  currentConfidence: number | null;
  lastUpdate: number | null;
  emotionHistory: EmotionLog[];
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;
  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  toggleSystemState: (state: 'start' | 'stop') => void;
  isSystemRunning: boolean;
  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliDirty: boolean;
  hungerLevel: number;
  feedPeli: (amount: number) => void;
  isPeliHungry: boolean;

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
  isDemoMode: boolean;
  setIsDemoMode: (val: boolean) => void;

  dataSource: DataSource;
  setDataSource: (source: DataSource) => void;
  detectFromCamera: (blob: Blob) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useLocalStorage('userName', '');
  const [userPin, setUserPin] = useLocalStorage('userPin', ''); 

  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');

  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [hungerLevel, setHungerLevel] = useLocalStorage<number>('hungerLevel', 50); 
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', Date.now());

  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
      hat: null,
      clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Neutral');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState<boolean>(false);
  const [isDemoMode, setIsDemoMode] = useState<boolean>(false);
  const [dataSource, setDataSource] = useState<DataSource>('device');

  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const socketRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const calculateDecay = () => {
        const now = Date.now();
        const diff = now - lastFedTime;
        const msPerPoint = 72000; 
        const pointsLost = Math.floor(diff / msPerPoint);
        if (pointsLost > 0) {
            setHungerLevel(prev => Math.max(0, prev - pointsLost));
            setLastFedTime(now);
        }
    };
    calculateDecay();
    const interval = setInterval(calculateDecay, 60000);
    return () => clearInterval(interval);
  }, [lastFedTime, setHungerLevel, setLastFedTime]);

  const feedPeli = useCallback((amount: number) => {
      setHungerLevel(prev => Math.min(100, prev + amount));
      setLastFedTime(Date.now());
  }, [setHungerLevel, setLastFedTime]);

  const isPeliHungry = useMemo(() => hungerLevel < 50, [hungerLevel]);
  const isPeliDirty = useMemo(() => (Date.now() - lastShowerTime) > (3 * 60 * 60 * 1000), [lastShowerTime]);

  const updateEmotionFromData = useCallback((label: any, confidence: any) => {
    if (!label) return;
    const normalized = label.toString().toLowerCase().trim();
    const synonymMap: Record<string, Emotion> = {
      'happy': 'Happy', 'joy': 'Happy', 'excited': 'Happy',
      'sad': 'Sad', 'angry': 'Angry', 'mad': 'Mad',
      'fear': 'Fear', 'surprised': 'Surprised',
      'disgust': 'Disgust', 'neutral': 'Neutral'
    };
    let matched = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);
    if (matched) {
      setCurrentEmotion(matched);
      setCurrentConfidence(confidence);
      setLastUpdate(Date.now());
      setEmotionHistory(prev => {
        if (prev.length === 0 || prev[0].emotion !== matched) {
          return [{ id: Date.now().toString(), emotion: matched!, detectedAt: Date.now() }, ...prev].slice(0, 100);
        }
        return prev;
      });
    }
  }, [setEmotionHistory]);

  const connectToAzure = useCallback(() => {
    if (dataSource !== 'device') return;
    if (socketRef.current) {
        if (socketRef.current.readyState !== WebSocket.CLOSED) socketRef.current.close();
    }

    const isSecure = window.location.protocol === 'https:';
    const protocol = isSecure ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${AZURE_SERVER_IP}:${AZURE_WS_PORT}`;

    setConnectionStatus('connecting');
    setConnectionError(null);

    try {
        const socket = new WebSocket(wsUrl);
        socketRef.current = socket;

        socket.onopen = () => {
          setConnectionStatus('connected');
          socket.send(JSON.stringify({ type: 'request_sync' }));
        };

        socket.onmessage = (event) => {
          try {
            const message = JSON.parse(event.data);
            if (message.type === 'emotion_output') {
              const data = message.data;
              updateEmotionFromData(data.label || data.emotion, data.score || data.confidence);
            }
          } catch (err) { console.error("WS Parse Error", err); }
        };

        socket.onerror = (error) => {
          setConnectionStatus('error');
          if (isSecure) {
            setConnectionError("Security Block: Insecure 'ws://' blocked on HTTPS. Use local IP or enable insecure content for 20.6.159.98.");
          } else {
            setConnectionError("Failed to connect to Azure WebSocket.");
          }
        };

        socket.onclose = () => {
          setConnectionStatus('disconnected');
          if (isSystemRunning) setTimeout(connectToAzure, 5000);
        };
    } catch (e) {
        setConnectionStatus('error');
        setConnectionError("WS Construction failed.");
    }
  }, [dataSource, isSystemRunning, updateEmotionFromData]);

  const detectFromCamera = useCallback(async (blob: Blob) => {
    if (isDemoMode) return;
    const isSecure = window.location.protocol === 'https:';

    // FIX: Diagnosing 'Failed to fetch'. 
    // If the page is HTTPS, browsers block calls to 'http://' IPs (Mixed Content).
    const apiUrl = `http://${AZURE_SERVER_IP}:${AZURE_REST_PORT}/predict`;

    const formData = new FormData();
    formData.append('file', blob, 'capture.jpg');

    try {
        const response = await fetch(apiUrl, {
            method: 'POST',
            body: formData,
            // Mode: 'cors' is default but explicitly adding it can help with some browser environments.
            mode: 'cors',
        });

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status} ${response.statusText}`);
        }

        const result = await response.json();
        // The Azure response structure provided in the Kotlin snippet:
        // { success: Boolean, faces_detected: Int, results: [{ emotion: String, confidence: Double, bbox: {...} }] }
        if (result.success && result.results && result.results.length > 0) {
            const topResult = result.results[0];
            updateEmotionFromData(topResult.emotion, topResult.confidence);
        }
    } catch (err: any) {
        console.error("Camera API Fetch Error:", err);
        if (isSecure && err.message?.includes('fetch')) {
            setConnectionError("Mixed Content Error: Browsers block 'http' API calls from 'https' sites. Try using a local non-https environment or ensure the server supports 'https'.");
        } else {
            setConnectionError(`API Error: ${err.message || 'Failed to reach Azure server'}`);
        }
    }
  }, [isDemoMode, updateEmotionFromData]);

  useEffect(() => {
    if (isSystemRunning && dataSource === 'device') {
        connectToAzure();
    }
    return () => {
        if (socketRef.current) socketRef.current.close();
    };
  }, [isSystemRunning, dataSource, connectToAzure]);

  useEffect(() => {
    let interval: any;
    if (isDemoMode && isSystemRunning) {
      interval = setInterval(() => {
        const randomEmotion = SUPPORTED_EMOTIONS[Math.floor(Math.random() * SUPPORTED_EMOTIONS.length)];
        updateEmotionFromData(randomEmotion, 0.85 + Math.random() * 0.1);
      }, 3000);
    }
    return () => clearInterval(interval);
  }, [isDemoMode, isSystemRunning, updateEmotionFromData]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    setIsSystemRunning(state === 'start');
  }, []);

  const toggleTheme = useCallback(() => setTheme(prev => prev === 'light' ? 'dark' : 'light'), [setTheme]);
  const earnDrachma = useCallback((amount: number) => setDrachma(prev => prev + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
      if (drachma >= amount) { setDrachma(prev => prev - amount); return true; }
      return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
      if (drachma >= price) {
          setDrachma(prev => prev - price);
          setInventory(prev => [...prev, itemId]);
          return true;
      }
      return false;
  }, [drachma, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
      setInventory(prev => {
          const idx = prev.indexOf(itemId);
          if (idx > -1) {
              const newInv = [...prev];
              newInv.splice(idx, 1);
              return newInv;
          }
          return prev;
      });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
      setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  return (
    <AppContext.Provider value={{
      companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
      currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
      addActivityLog, clearHistory, connectionStatus, connectionError,
      toggleSystemState, isSystemRunning, theme, toggleTheme,
      lastShowerTime, setLastShowerTime, lastFedTime, setLastFedTime, isPeliDirty, hungerLevel, feedPeli, isPeliHungry,
      drachma, earnDrachma, spendDrachma, inventory, equippedItems, buyItem, equipItem, consumeItem,
      isDemoMode, setIsDemoMode, dataSource, setDataSource, detectFromCamera
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppContext = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext must be used within an AppProvider');
  return context;
};

import React, { useMemo, useRef, useEffect, useState, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { ConnectionStatus, DataSource } from '../types';

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    connectionStatus, 
    connectionError,
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    lastUpdate,
    isDemoMode,
    setIsDemoMode,
    dataSource,
    setDataSource,
    detectFromCamera
  } = useAppContext();

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  // Handle Camera Stream
  useEffect(() => {
    if (isSystemRunning && dataSource === 'camera') {
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false })
            .then(s => {
                setStream(s);
                if (videoRef.current) videoRef.current.srcObject = s;
            })
            .catch(err => {
                console.error("Camera access denied", err);
            });
    } else {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
    }
    return () => stream?.getTracks().forEach(t => t.stop());
  }, [isSystemRunning, dataSource]);

  // Periodic Camera Capture
  useEffect(() => {
    let interval: any;
    if (isSystemRunning && dataSource === 'camera' && stream) {
        interval = setInterval(() => {
            if (videoRef.current && canvasRef.current) {
                const video = videoRef.current;
                const canvas = canvasRef.current;
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    canvas.toBlob(blob => {
                        if (blob) detectFromCamera(blob);
                    }, 'image/jpeg', 0.8);
                }
            }
        }, 3000); // Check every 3 seconds
    }
    return () => clearInterval(interval);
  }, [isSystemRunning, dataSource, stream, detectFromCamera]);

  const emotionDetails = useMemo(() => EMOTION_DETAILS[currentEmotion] || { emoji: '😐', color: 'text-gray-400', pulseColor: '#d1d5db' }, [currentEmotion]);

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
      {/* Header Controls */}
      <div className="p-4 flex gap-2 justify-center">
        <button 
          onClick={() => setDataSource('device')}
          className={`px-4 py-2 rounded-full text-xs font-bold transition-all border ${dataSource === 'device' ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white dark:bg-gray-800 text-gray-500 border-gray-200 dark:border-gray-700'}`}
        >
          Device Sync
        </button>
        <button 
          onClick={() => setDataSource('camera')}
          className={`px-4 py-2 rounded-full text-xs font-bold transition-all border ${dataSource === 'camera' ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white dark:bg-gray-800 text-gray-500 border-gray-200 dark:border-gray-700'}`}
        >
          Phone Camera
        </button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center p-4 relative overflow-hidden">
        {/* Main Display Area */}
        <div className="w-full max-w-sm aspect-square relative flex items-center justify-center">
           {/* Camera Preview Overlay */}
           {dataSource === 'camera' && isSystemRunning && (
               <div className="absolute inset-0 z-0 rounded-full overflow-hidden border-4 border-indigo-500/30 shadow-2xl">
                   <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover grayscale opacity-40 scale-125" />
                   <div className="absolute inset-0 bg-gradient-to-t from-indigo-500/20 to-transparent animate-pulse" />
                   <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                       <div className="w-3/4 h-3/4 border border-white/20 rounded-lg animate-pulse" />
                   </div>
               </div>
           )}

           <canvas ref={canvasRef} className="hidden" />

           {/* Animated Character */}
           <div className="relative z-10 flex flex-col items-center">
                <style>
                    {`
                    @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
                    .animate-float { animation: float 4s ease-in-out infinite; }
                    `}
                </style>
                <div className={`text-[120px] transition-all duration-700 transform ${isSystemRunning ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`} style={{ filter: isSystemRunning ? `drop-shadow(0 0 30px ${emotionDetails.pulseColor})` : '' }}>
                    {emotionDetails.emoji}
                </div>
                <h1 className={`mt-8 text-4xl font-black transition-colors duration-500 ${isSystemRunning ? emotionDetails.color : 'text-gray-400'}`}>
                    {isSystemRunning ? currentEmotion : 'Offline'}
                </h1>
           </div>
        </div>

        {/* Connection Details */}
        <div className="mt-8 h-24 flex flex-col items-center justify-center">
            {isSystemRunning ? (
                <div className="flex flex-col items-center gap-1 animate-fadeIn">
                   {currentConfidence !== null && (
                       <span className="bg-white/80 dark:bg-gray-800/80 px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700">
                           {dataSource === 'camera' ? 'AI Analysis' : 'Sync'}: {(currentConfidence * 100).toFixed(0)}% Certainty
                       </span>
                   )}
                   <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase">
                       {dataSource === 'camera' ? 'Scanning face via REST API...' : connectionStatus === 'connected' ? 'Connected to Azure WS' : 'Connecting to Azure...'}
                   </span>
                </div>
            ) : (
                <p className="text-gray-400 dark:text-gray-600 text-sm font-medium italic">Tap start to observe emotions.</p>
            )}

            {/* FIX: Showing connectionError for both data sources to debug 'Failed to fetch' */}
            {connectionError && (
                <div className="mt-2 text-[10px] text-red-500 font-bold max-w-[280px] text-center bg-red-50 dark:bg-red-900/10 p-2 rounded-lg border border-red-100 dark:border-red-900/30">
                    {connectionError}
                </div>
            )}
        </div>
      </div>

      {/* Footer Actions */}
      <div className="p-8 pb-12 w-full max-w-sm mx-auto">
        <button
          onClick={() => toggleSystemState(isSystemRunning ? 'stop' : 'start')}
          className={`w-full py-5 rounded-3xl font-black text-xl text-white shadow-xl transition-all active:scale-95 ${isSystemRunning ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-200 dark:shadow-none' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200 dark:shadow-none'}`}
        >
          {isSystemRunning ? 'Deactivate PelioScope' : 'Activate PelioScope'}
        </button>

        <button 
            onClick={() => setIsDemoMode(!isDemoMode)}
            className={`w-full mt-4 text-[10px] font-black uppercase tracking-widest ${isDemoMode ? 'text-indigo-600' : 'text-gray-400'}`}
        >
            {isDemoMode ? 'Demo Mode: Active' : 'Switch to Demo Mode'}
        </button>
      </div>
    </div>
  );
};

export default LiveTab;

{
  "name": "PelioScope Emotion Companion",
  "description": "PelioScope displays animated emojis representing detected emotions in real-time by synchronizing with an Azure-hosted AI service via WebSockets.",
  "requestFramePermissions": []
}

import React from 'react';

export type Emotion = 'Happy' | 'Sad' | 'Angry' | 'Mad' | 'Surprised' | 'Fear' | 'Neutral' | 'Disgust';

export const SUPPORTED_EMOTIONS: Emotion[] = ['Happy', 'Sad', 'Angry', 'Mad', 'Surprised', 'Fear', 'Neutral', 'Disgust'];

export interface EmotionData {
  emoji: string;
  color: string;
