const CACHE_NAME = 'emotion-companion-cache-v4';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/App.tsx',
  '/types.ts',
  '/constants.ts',
  '/hooks/useLocalStorage.ts',
  '/contexts/AppContext.tsx',
  '/components/Icons.tsx',
  '/components/TabNavigator.tsx',
  '/components/LiveTab.tsx',
  '/components/ChatTab.tsx',
  '/components/ActivitiesTab.tsx',
  '/components/ActivityModal.tsx',
  '/components/StatsTab.tsx',
  '/components/SettingsTab.tsx',
  '/components/SplashScreen.tsx',
  'https://cdn.tailwindcss.com'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  // EXCLUSION: Strictly do not intercept any Azure-hosted or WebSocket traffic
  const isAzure = event.request.url.includes('azurewebsites.net');
  const isWebSocket = event.request.headers.get('upgrade') === 'websocket';

  if (event.request.method !== 'GET' || isAzure || isWebSocket) {
    return;
  }

  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          response => {
            if (!response || response.status !== 200 || (response.type !== 'basic' && response.type !== 'cors')) {
              return response;
            }

            const responseToCache = response.clone();
            caches.open(CACHE_NAME)
              .then(cache => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import React, {
  createContext,
  useContext,
  useState,
  useRef,
  useCallback,
  ReactNode,
  useEffect,
  useMemo,
} from 'react';

import useLocalStorage from '../hooks/useLocalStorage';
import {
  Emotion,
  ActivityLog,
  EmotionLog,
  ConnectionStatus,
  SUPPORTED_EMOTIONS,
  EquippedItems,
} from '../types';
import { SHOP_ITEMS } from '../constants';

type Theme = 'light' | 'dark';

// Azure Emotion Detection Endpoints
const AZURE_BASE_URL = 'https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net/predict';
const AZURE_WS_URL = 'wss://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net/predict';

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;

  currentEmotion: Emotion;
  currentConfidence: number | null;
  lastUpdate: number | null;

  emotionHistory: EmotionLog[];
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;

  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  retryConnection: () => void;
  toggleSystemState: (state: 'start' | 'stop') => void;
  isSystemRunning: boolean;
  isDemoMode: boolean;
  setIsDemoMode: (mode: boolean) => void;

  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  isPeliDirty: boolean;

  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliHungry: boolean;
  hungerLevel: number; // 0 (starving) to 100 (full)

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useLocalStorage('userName', '');
  const [userPin, setUserPin] = useLocalStorage('userPin', '');
  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');
  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', 0);
  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
    hat: null,
    clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState(false);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('connecting');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<number | null>(null);

  const isPeliDirty = useMemo(() => Date.now() - lastShowerTime > 3 * 60 * 60 * 1000, [lastShowerTime]);
  const isPeliHungry = useMemo(() => Date.now() - lastFedTime > 30 * 60 * 1000, [lastFedTime]);
  const hungerLevel = useMemo(() => {
    const window = 30 * 60 * 1000;
    const elapsed = Date.now() - lastFedTime;
    return Math.max(0, Math.min(100, 100 - (elapsed / window) * 100));
  }, [lastFedTime]);

  useEffect(() => {
    const root = document.documentElement;
    theme === 'dark' ? root.classList.add('dark') : root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(t => (t === 'light' ? 'dark' : 'light')), [setTheme]);

  const connectWebSocket = useCallback(() => {
    if (reconnectTimeoutRef.current) window.clearTimeout(reconnectTimeoutRef.current);

    if (wsRef.current) {
      wsRef.current.onopen = null;
      wsRef.current.onmessage = null;
      wsRef.current.onerror = null;
      wsRef.current.onclose = null;
      try { wsRef.current.close(); } catch (e) {}
      wsRef.current = null;
    }

    console.log('🔄 Attempting sync with Azure PelioScope Server...');
    setConnectionStatus('connecting');

    // Wake-up fetch to handle Azure cold starts
    fetch(AZURE_BASE_URL, { mode: 'no-cors', cache: 'no-cache' })
      .catch(() => console.log('Warm-up ping sent.'))
      .finally(() => {
        // Small delay to allow Azure internal routing to ready up
        setTimeout(() => {
          try {
            const ws = new WebSocket(AZURE_WS_URL);
            wsRef.current = ws;

            ws.onopen = () => {
              console.log('✅ Connected to PelioScope Cloud');
              setConnectionStatus('connected');
              setConnectionError(null);
            };

            ws.onmessage = (event) => {
              try {
                const data = JSON.parse(event.data);
                const label = data.label || data.emotion || (data.type === 'emotion' ? data.label : null);
                const confidence = data.confidence ?? null;
                const timestamp = data.timestamp ?? Date.now();

                if (label) {
                  const normalized = String(label).toLowerCase();
                  const synonymMap: Record<string, Emotion> = {
                    happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad', 
                    fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
                  };

                  const matchedEmotion = synonymMap[normalized] ||
                    SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);

                  if (matchedEmotion) {
                    setCurrentEmotion(matchedEmotion);
                    setCurrentConfidence(confidence);
                    setLastUpdate(timestamp);
                    setEmotionHistory(prev => {
                      if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
                        return [{ id: Date.now().toString(), emotion: matchedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
                      }
                      return prev;
                    });
                  }
                }
                if (data.type === 'control') setIsSystemRunning(data.state === 'start');
              } catch (e) { console.error('Data Parse Error:', e); }
            };

            ws.onerror = (e) => {
              console.error('❌ WebSocket Error:', e);
              setConnectionStatus('error');
              if (location.protocol === 'https:') {
                setConnectionError('SECURITY BLOCK: The browser blocked the sync. This often requires enabling "Insecure Content" in site settings.');
              } else {
                setConnectionError('CONNECTION REFUSED: The cloud server may be offline or the endpoint is incorrect.');
              }
            };

            ws.onclose = (e) => {
              console.log(`🔌 Connection closed (Code: ${e.code}).`);
              if (connectionStatus !== 'error') {
                setConnectionStatus('disconnected');
                reconnectTimeoutRef.current = window.setTimeout(connectWebSocket, 5000);
              }
            };
          } catch (err) {
            console.error('WebSocket Init Error:', err);
            setConnectionStatus('error');
            setConnectionError('LOCAL ERROR: Your browser could not initialize the connection.');
          }
        }, 500);
      });
  }, [setEmotionHistory, connectionStatus]);

  const retryConnection = useCallback(() => {
    setConnectionError(null);
    setConnectionStatus('connecting');
    connectWebSocket();
  }, [connectWebSocket]);

  useEffect(() => {
    connectWebSocket();
    return () => {
      if (wsRef.current) wsRef.current.close();
      if (reconnectTimeoutRef.current) window.clearTimeout(reconnectTimeoutRef.current);
    };
  }, [connectWebSocket]);

  useEffect(() => {
    let interval: any;
    if (isDemoMode && isSystemRunning) {
      interval = setInterval(() => {
        const randomEmotion = SUPPORTED_EMOTIONS[Math.floor(Math.random() * SUPPORTED_EMOTIONS.length)];
        setCurrentEmotion(randomEmotion);
        setCurrentConfidence(0.85 + Math.random() * 0.1);
        setLastUpdate(Date.now());
        setEmotionHistory(prev => {
          if (prev.length === 0 || prev[0].emotion !== randomEmotion) {
            return [{ id: Date.now().toString(), emotion: randomEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
          }
          return prev;
        });
      }, 4000);
    }
    return () => clearInterval(interval);
  }, [isDemoMode, isSystemRunning, setEmotionHistory]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'control', state }));
    } else if (isDemoMode) {
      setIsSystemRunning(state === 'start');
    } else {
      if (connectionStatus === 'error') {
         setConnectionError('Please check the Troubleshooting guide and tap "Retry Connection".');
      } else {
         setConnectionError('Syncing with cloud...');
         if (connectionStatus !== 'connecting') connectWebSocket();
      }
    }
  }, [isDemoMode, connectionStatus, connectWebSocket]);

  const earnDrachma = useCallback((amount: number) => setDrachma(d => d + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
    if (drachma >= amount) {
      setDrachma(d => d - amount);
      return true;
    }
    return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    const isConsumable = item?.category === 'food';
    if (!isConsumable && inventory.includes(itemId)) return true;
    if (drachma < price) return false;
    setDrachma(d => d - price);
    setInventory(inv => [...inv, itemId]);
    return true;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
    setInventory(inv => {
      const idx = inv.indexOf(itemId);
      if (idx === -1) return inv;
      const copy = [...inv];
      copy.splice(idx, 1);
      return copy;
    });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
    setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const value: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError, retryConnection,
    toggleSystemState, isSystemRunning, isDemoMode, setIsDemoMode, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, isPeliDirty, lastFedTime, setLastFedTime,
    isPeliHungry, hungerLevel, drachma, earnDrachma, spendDrachma, inventory,
    equippedItems, buyItem, equipItem, consumeItem,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useAppContext = (): AppContextType => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useAppContext must be used within AppProvider');
  return ctx;
};

