             )}

             {isError && connectionError && (
                <div className="bg-red-50 dark:bg-red-900/10 p-5 rounded-3xl border border-red-100 dark:border-red-900/30 text-left animate-fadeInUp shadow-sm">
                  <div className="flex items-center gap-2 mb-3">
                      <span className="text-xl">⚠️</span>
                      <p className="text-[11px] text-red-600 dark:text-red-400 font-black uppercase tracking-tighter">
                        Sync Alert
                      </p>
                  </div>

                  <p className="text-sm text-gray-700 dark:text-gray-300 font-medium mb-4 leading-relaxed">
                    {connectionError}
                  </p>

                  <div className="flex flex-col gap-3">
                      <button 
                        onClick={() => setShowTroubleshoot(!showTroubleshoot)}
                        className="text-[11px] font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-widest text-center py-2"
                      >
                        {showTroubleshoot ? 'Close Help' : 'View Troubleshooting Guide'}
                      </button>

                      {showTroubleshoot && (
                         <div className="bg-white/50 dark:bg-black/20 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-900/20 text-[10px] leading-relaxed text-gray-600 dark:text-gray-400 space-y-2 animate-fadeIn">
                            <p><span className="font-black text-indigo-500">1. UNBLOCK CONTENT:</span> Browsers often block WebSockets on custom domains. Click the <span className="font-bold">Lock icon (🔒)</span> in the address bar → <span className="font-bold">Site Settings</span> → Set <span className="font-bold">Insecure Content</span> to <span className="font-bold text-green-600">Allow</span>.</p>
                            <p><span className="font-black text-indigo-500">2. AZURE COLD START:</span> If the server was idle, it might take up to 60 seconds to wake up. Please wait and try again.</p>
                            <p><span className="font-black text-indigo-500">3. REFRESH:</span> If all else fails, a full page refresh often resets the security handshake.</p>
                         </div>
                      )}

                      <button 
                        onClick={retryConnection}
                        className="w-full py-3.5 bg-indigo-600 text-white font-black rounded-2xl text-xs uppercase tracking-widest shadow-lg hover:bg-indigo-700 active:scale-95 transition-all"
                      >
                        Retry Connection
                      </button>
                  </div>
                </div>
             )}
        </div>
      </div>

      {/* Control Buttons */}
      <div className="w-full max-w-sm pb-10">
        <button
          onClick={() => toggleSystemState(isSystemRunning ? 'stop' : 'start')}
          disabled={connectionStatus === 'connecting'}
          className={`w-full py-6 rounded-[2.5rem] font-black text-xl text-white shadow-xl transition-all active:scale-95 ${isSystemRunning ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-100 dark:shadow-none' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100 dark:shadow-none'} ${connectionStatus === 'connecting' ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          {connectionStatus === 'connecting' ? 'Connecting...' : isSystemRunning ? 'Stop PelioScope' : 'Start PelioScope'}
        </button>

        <button 
            onClick={() => setIsDemoMode(!isDemoMode)}
            className={`w-full mt-6 text-[10px] font-black uppercase tracking-widest ${isDemoMode ? 'text-indigo-600' : 'text-gray-400'} transition-colors`}
        >
            {isDemoMode ? 'Simulator Active' : 'Run Offline Simulator'}
        </button>
      </div>
    </div>
  );
};

