    retryConnection,
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    isDemoMode,
    setIsDemoMode
  } = useAppContext();

  const [showTroubleshoot, setShowTroubleshoot] = useState(false);

  const idleDetails = {
    emoji: '😴',
    color: 'text-gray-400 dark:text-gray-500',
    pulseColor: '#9ca3af'
  };

  const emotionDetails = isSystemRunning ? EMOTION_DETAILS[currentEmotion] : idleDetails;
  const isError = connectionStatus === 'error';
  const isSyncing = connectionStatus === 'connecting';
  const isDisconnected = connectionStatus === 'disconnected';

  return (
    <div className="flex flex-col items-center justify-center h-full p-4 text-center bg-slate-50 dark:bg-slate-950 overflow-hidden relative">
      {/* Top Status Badge */}
      <div className="absolute top-6">
         <div className="flex items-center gap-2 px-4 py-1.5 rounded-full bg-white dark:bg-gray-800 shadow-sm border border-gray-100 dark:border-gray-700">
            <div className={`w-2 h-2 rounded-full ${connectionStatus === 'connected' ? 'bg-green-500 shadow-[0_0_8px_#22c55e]' : isSyncing ? 'bg-yellow-500 animate-pulse' : isDisconnected ? 'bg-gray-400' : 'bg-red-500 shadow-[0_0_8px_#ef4444]'}`} />
            <span className="text-[10px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400">
                {connectionStatus === 'connected' ? 'Sync Active' : isSyncing ? 'Linking...' : isDisconnected ? 'Ready' : 'Handshake Failed'}
            </span>
         </div>
      </div>

      <div className="flex-grow flex flex-col items-center justify-center w-full max-w-sm">
        <div className="relative mb-12">
           <style>
            {`
              @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
              .animate-float { animation: float 4s ease-in-out infinite; }
              @keyframes scan { 0% { top: 0%; opacity: 0; } 50% { opacity: 0.5; } 100% { top: 100%; opacity: 0; } }
              .scan-line { position: absolute; left: 0; right: 0; height: 2px; background: #6366f1; animation: scan 2s linear infinite; }
            `}
          </style>
          <div 
            className={`text-[140px] transition-all duration-700 transform ${isSystemRunning ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`}
            style={{ filter: isSystemRunning && connectionStatus === 'connected' ? `drop-shadow(0 0 40px ${emotionDetails.pulseColor})` : '' }}
          >
            {emotionDetails.emoji}
            {isSyncing && <div className="scan-line" />}
          </div>
        </div>

        <h1 className={`text-5xl font-black transition-colors duration-500 tracking-tight ${isSystemRunning ? emotionDetails.color : 'text-gray-300'}`}>
          {isSystemRunning ? currentEmotion : 'Idle'}
        </h1>

        <div className="mt-8 space-y-4 w-full">
             {currentConfidence !== null && isSystemRunning && (
                 <div className="inline-block bg-white/80 dark:bg-gray-800/80 px-4 py-1.5 rounded-full border border-gray-100 dark:border-gray-700 shadow-sm animate-fadeIn">
                     <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600 dark:text-indigo-400">
                        Match Confidence: {(currentConfidence * 100).toFixed(0)}%
                     </span>
                 </div>
             )}

             {isError && connectionError && (
                <div className="bg-white dark:bg-gray-900 p-6 rounded-[2.5rem] border-2 border-red-500/20 shadow-2xl text-left animate-fadeInUp">
                  <div className="flex items-center gap-3 mb-4">
                      <div className="w-10 h-10 rounded-2xl bg-red-100 dark:bg-red-900/40 flex items-center justify-center text-xl">⚠️</div>
                      <div>
                        <p className="text-[10px] text-red-600 dark:text-red-400 font-black uppercase tracking-widest leading-none">
                            Sync Alert
                        </p>
                        <p className="text-sm font-bold text-gray-800 dark:text-gray-100">Handshake Blocked</p>
                      </div>
                  </div>

                  <p className="text-xs text-gray-600 dark:text-gray-400 font-medium mb-6 leading-relaxed">
                    {connectionError}
                  </p>

                  <div className="space-y-3">
                      <button 
                        onClick={() => setShowTroubleshoot(!showTroubleshoot)}
                        className={`w-full py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${showTroubleshoot ? 'bg-indigo-50 text-indigo-600' : 'text-indigo-600 hover:bg-indigo-50'}`}
                      >
                        {showTroubleshoot ? 'Hide Guide' : 'Troubleshoot Fixes'}
                      </button>

                      {showTroubleshoot && (
                         <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-5 rounded-3xl space-y-4 animate-fadeIn">
                            <div className="space-y-1">
                                <p className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase">1. Fix Browser Block</p>
                                <p className="text-[11px] text-gray-700 dark:text-gray-300 leading-normal">
                                    Click the <span className="font-black">Lock icon (🔒)</span> in the address bar → <span className="font-black">Site Settings</span> → Set <span className="font-black text-rose-500">Insecure Content</span> to <span className="font-black text-green-600">Allow</span>. Then refresh.
                                </p>
                            </div>
                            <div className="space-y-1 pt-2 border-t border-indigo-100/50">
                                <p className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase">2. Azure Warm-up</p>
                                <p className="text-[11px] text-gray-700 dark:text-gray-300 leading-normal">
                                    Azure servers sleep after 20 minutes. If you haven't synced in a while, it may take <span className="font-black">30-60 seconds</span> to wake up.
                                </p>
                            </div>
                         </div>
                      )}

                      <button 
                        onClick={retryConnection}
                        className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl text-xs uppercase tracking-widest shadow-lg hover:bg-indigo-700 active:scale-95 transition-all"
                      >
                        Manual Sync Retry
                      </button>
                  </div>
                </div>
             )}
        </div>
      </div>

      {/* Control Buttons */}
      <div className="w-full max-w-sm pb-10 px-4">
        <button
          onClick={() => toggleSystemState(isSystemRunning ? 'stop' : 'start')}
          disabled={isSyncing}
          className={`w-full py-6 rounded-[2.5rem] font-black text-xl text-white shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 ${isSystemRunning ? 'bg-rose-500 hover:bg-rose-600' : 'bg-indigo-600 hover:bg-indigo-700'} ${isSyncing ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          {isSyncing ? (
             <>
               <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin" />
               <span>Syncing...</span>
             </>
          ) : isSystemRunning ? 'Stop PelioScope' : 'Activate PelioScope'}
        </button>

        <button 
            onClick={() => setIsDemoMode(!isDemoMode)}
            className={`w-full mt-6 text-[10px] font-black uppercase tracking-widest transition-colors py-2 ${isDemoMode ? 'text-indigo-600' : 'text-gray-400'}`}
        >
            {isDemoMode ? 'Simulation Active (Offline)' : 'Start Offline Simulator'}
        </button>
      </div>
    </div>
  );
};

