import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const QUICK_REPLIES: Record<string, string[]> = {
  Happy: ["I'm feeling great!", "Something good happened!", "Today is awesome!"],
  Angry: ["I am frustrated.", "Things aren't going right.", "I need to calm down."],
  Neutral: ["I'm doing okay.", "Just chilling.", "I'm bored."],
  Disgust: ["That is gross.", "I don't like this.", "Yuck!"],
  Fear: ["I am scared.", "I feel nervous.", "I need help."],
  Surprised: ["I didn't expect that!", "Wow, that's amazing!", "Really?"],
  Sad: ["I feel lonely.", "I had a bad day.", "Can you cheer me up?"],
};

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [selectedQuickEmotion, setSelectedQuickEmotion] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Gemini Chat Session Reference
  const chatSessionRef = useRef<any>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  // Initialize Chat Session with robust error handling
  useEffect(() => {
    try {
      if (!process.env.API_KEY) {
        throw new Error("API Key is missing. Please check your environment configuration.");
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are ${companionName}, a friendly and supportive emotion companion for ${userName || 'a user'} who has Autism Spectrum Disorder (ASD). 
          Your goal is to provide clear, simple, and reassuring communication. 
          Acknowledge the user's emotions. Currently, the device detects they are feeling: ${currentEmotion}.
          Use visual descriptions when helpful (e.g., "Imagine a calm blue ocean"). 
          Keep responses concise (1-3 sentences). Avoid idioms or complex metaphors. 
          Always be kind and patient.`,
        },
      });
      chatSessionRef.current = chat;
      setAiError(null);

      if (messages.length === 0) {
        setMessages([
          {
            id: 'welcome',
            text: `Hello ${userName}! I'm ${companionName}. I see you're feeling ${currentEmotion.toLowerCase()} right now. How can I help you?`,
            sender: 'companion',
            timestamp: Date.now(),
          }
        ]);
      }
    } catch (error: any) {
      console.error("Failed to initialize Gemini AI:", error);
      setAiError(error.message || "Could not connect to the AI service.");
    }
  }, [companionName, userName]);

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping || aiError) return;

    const userMsgId = Date.now().toString();
    const newUserMessage: ChatMessage = {
      id: userMsgId,
      text: text,
      sender: 'user',
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newUserMessage]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) {
        throw new Error("Chat session not initialized");
      }

      // Send message to Gemini
      const prompt = `[Context: Current detected emotion is ${currentEmotion}] ${text}`;
      const result = await chatSessionRef.current.sendMessage({ message: prompt });
      const responseText = result.text;

      const companionResponse: ChatMessage = {
        id: (Date.now() + 1).toString(),
        text: responseText || "I'm here for you. Can you tell me more?",
        sender: 'companion',
        timestamp: Date.now() + 1,
      };

      setMessages(prev => [...prev, companionResponse]);
    } catch (error) {
      console.error("Gemini API Error:", error);
      const errorMsg: ChatMessage = {
        id: 'error-' + Date.now(),
        text: "I'm having a little trouble connecting to my brain right now, but I'm still here for you!",
        sender: 'companion',
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    processMessage(userInput);
  };

  const handleQuickReply = (text: string) => {
    processMessage(text);
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-gray-950">
        <div className="w-24 h-24 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-5xl mb-6 animate-pulse">
          🚫
        </div>
        <h1 className="text-2xl font-black text-gray-800 dark:text-white mb-4">Chat Unavailable</h1>
        <p className="text-gray-500 dark:text-gray-400 mb-8 max-w-xs mx-auto">
          {companionName}'s brain (AI service) couldn't be connected. This usually happens if the API key is missing or the network is blocked.
        </p>
        <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded-2xl w-full text-left font-mono text-[10px] text-rose-500 overflow-x-auto">
          Error: {aiError}
        </div>
        <p className="mt-8 text-xs text-gray-400">
          Try restarting the app or checking your internet connection.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100 text-center mb-2 px-4">
        Chat with {companionName}
      </h1>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-8 h-8 rounded-full bg-indigo-400 flex items-center justify-center text-white font-bold text-sm shrink-0 shadow-sm">
                {companionName.charAt(0)}
              </div>
            )}
