import React, {
  createContext,
  useContext,
  useState,
  useRef,
  useCallback,
  ReactNode,
  useEffect,
  useMemo,
} from 'react';

import useLocalStorage from '../hooks/useLocalStorage';
import {
  Emotion,
  ActivityLog,
  EmotionLog,
  ConnectionStatus,
  SUPPORTED_EMOTIONS,
  EquippedItems,
} from '../types';
import { SHOP_ITEMS } from '../constants';

type Theme = 'light' | 'dark';

const AZURE_BASE_URL = 'https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net/predict';
const AZURE_WS_URL = 'wss://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net/predict';

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;

  currentEmotion: Emotion;
  currentConfidence: number | null;
  lastUpdate: number | null;

  emotionHistory: EmotionLog[];
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;

  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  retryConnection: () => void;
  toggleSystemState: (state: 'start' | 'stop') => void;
  isSystemRunning: boolean;
  isDemoMode: boolean;
  setIsDemoMode: (mode: boolean) => void;

  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  isPeliDirty: boolean;

  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliHungry: boolean;
  hungerLevel: number;

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useLocalStorage('userName', '');
  const [userPin, setUserPin] = useLocalStorage('userPin', '');
  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');
  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', 0);
  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
    hat: null,
    clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState(false);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const isConnectingRef = useRef(false);

  const isPeliDirty = useMemo(() => Date.now() - lastShowerTime > 3 * 60 * 60 * 1000, [lastShowerTime]);
  const isPeliHungry = useMemo(() => Date.now() - lastFedTime > 30 * 60 * 1000, [lastFedTime]);
  const hungerLevel = useMemo(() => {
    const window = 30 * 60 * 1000;
    const elapsed = Date.now() - lastFedTime;
    return Math.max(0, Math.min(100, 100 - (elapsed / window) * 100));
  }, [lastFedTime]);

  useEffect(() => {
    const root = document.documentElement;
    theme === 'dark' ? root.classList.add('dark') : root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(t => (t === 'light' ? 'dark' : 'light')), [setTheme]);

  const cleanupSocket = useCallback(() => {
    if (wsRef.current) {
      const oldWs = wsRef.current;
      oldWs.onopen = null;
      oldWs.onmessage = null;
      oldWs.onerror = null;
      oldWs.onclose = null;
      try { oldWs.close(); } catch (e) {}
      wsRef.current = null;
    }
  }, []);

  const connectWebSocket = useCallback((shouldStartAfter: boolean = false) => {
    if (isConnectingRef.current) return;
    isConnectingRef.current = true;
    cleanupSocket();

    setConnectionStatus('connecting');
    setConnectionError(null);

    // Initial wake-up fetch
    fetch(AZURE_BASE_URL, { mode: 'no-cors', cache: 'no-cache' })
      .catch(() => {})
      .finally(() => {
        setTimeout(() => {
          try {
            const ws = new WebSocket(AZURE_WS_URL);
            wsRef.current = ws;

            ws.onopen = () => {
              setConnectionStatus('connected');
              setConnectionError(null);
              isConnectingRef.current = false;
              if (shouldStartAfter && ws.readyState === WebSocket.OPEN) {
                ws.send(JSON.stringify({ type: 'control', state: 'start' }));
              }
            };

            ws.onmessage = (event) => {
              try {
                const data = JSON.parse(event.data);
                if (data.label) {
                  const normalized = String(data.label).toLowerCase();
                  const synonymMap: Record<string, Emotion> = {
                    happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad', 
                    fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
                  };
                  const matchedEmotion = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);
                  if (matchedEmotion) {
                    setCurrentEmotion(matchedEmotion);
                    setCurrentConfidence(data.confidence ?? null);
                    setLastUpdate(data.timestamp ?? Date.now());
                    setEmotionHistory(prev => {
                      if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
                        return [{ id: Date.now().toString(), emotion: matchedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
                      }
                      return prev;
                    });
                  }
                }
                if (data.type === 'control') setIsSystemRunning(data.state === 'start');
              } catch (e) {}
            };

            ws.onerror = (e) => {
              setConnectionStatus('error');
              isConnectingRef.current = false;
              setConnectionError('HANDSHAKE FAILED: The cloud server is either sleeping or blocked by your network/APK security settings.');
            };

            ws.onclose = () => {
              setIsSystemRunning(false);
              isConnectingRef.current = false;
              if (connectionStatus !== 'error') setConnectionStatus('disconnected');
            };
          } catch (err) {
            setConnectionStatus('error');
            isConnectingRef.current = false;
            setConnectionError('CRITICAL: WebSocket initialization failed in this environment.');
          }
        }, 2000);
      });
  }, [setEmotionHistory, connectionStatus, cleanupSocket]);

  const retryConnection = useCallback(() => {
    isConnectingRef.current = false;
    connectWebSocket(true);
  }, [connectWebSocket]);

  const toggleSystemState = useCallback((state: 'start' | 'stop') => {
    if (isDemoMode) {
      setIsSystemRunning(state === 'start');
      return;
    }
    const socket = wsRef.current;
    if (state === 'start') {
        if (socket && socket.readyState === WebSocket.OPEN) {
          socket.send(JSON.stringify({ type: 'control', state: 'start' }));
        } else {
          connectWebSocket(true);
        }
    } else {
        if (socket && socket.readyState === WebSocket.OPEN) {
            socket.send(JSON.stringify({ type: 'control', state: 'stop' }));
        }
        setIsSystemRunning(false);
    }
  }, [isDemoMode, connectWebSocket]);

  const earnDrachma = useCallback((amount: number) => setDrachma(d => d + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
    if (drachma >= amount) {
      setDrachma(d => d - amount);
      return true;
    }
    return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (item?.category !== 'food' && inventory.includes(itemId)) return true;
    if (drachma < price) return false;
    setDrachma(d => d - price);
    setInventory(inv => [...inv, itemId]);
    return true;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
    setInventory(inv => {
      const idx = inv.indexOf(itemId);
      if (idx === -1) return inv;
      const copy = [...inv];
      copy.splice(idx, 1);
      return copy;
    });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
    setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const value: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, currentConfidence, lastUpdate, emotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError, retryConnection,
    toggleSystemState, isSystemRunning, isDemoMode, setIsDemoMode, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, isPeliDirty, lastFedTime, setLastFedTime,
    isPeliHungry, hungerLevel, drachma, earnDrachma, spendDrachma, inventory,
    equippedItems, buyItem, equipItem, consumeItem,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useAppContext = (): AppContextType => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useAppContext must be used within AppProvider');
  return ctx;
};

import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const QUICK_REPLIES: Record<string, string[]> = {
  Happy: ["I'm feeling great!", "Something good happened!", "Today is awesome!"],
  Angry: ["I am frustrated.", "Things aren't going right.", "I need to calm down."],
  Neutral: ["I'm doing okay.", "Just chilling.", "I'm bored."],
  Disgust: ["That is gross.", "I don't like this.", "Yuck!"],
  Fear: ["I am scared.", "I feel nervous.", "I need help."],
  Surprised: ["I didn't expect that!", "Wow, that's amazing!", "Really?"],
  Sad: ["I feel lonely.", "I had a bad day.", "Can you cheer me up?"],
};

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [selectedQuickEmotion, setSelectedQuickEmotion] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<any>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  useEffect(() => {
    const initChat = async () => {
      try {
        // SAFETY: Check if process and env are defined before access
        const key = typeof process !== 'undefined' && process.env ? process.env.API_KEY : null;

        if (!key) {
          throw new Error("ENVIRONMENT_MISSING: API Key is not detected in your APK environment.");
        }

        const ai = new GoogleGenAI({ apiKey: key });
        const chat = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName}, a friendly emotion companion for ${userName || 'a user'}. 
            Keep responses concise. Currently detecting: ${currentEmotion}.`,
          },
        });
        chatSessionRef.current = chat;
        setAiError(null);

        if (messages.length === 0) {
          setMessages([{
            id: 'welcome',
            text: `Hi ${userName}! I'm ${companionName}. I see you're feeling ${currentEmotion.toLowerCase()}! How can I help?`,
            sender: 'companion',
            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        setAiError(error.message || "Failed to start AI service.");
      }
    };
    initChat();
  }, [companionName, userName]);

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping || aiError) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), text, sender: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) throw new Error("Not connected");
      const result = await chatSessionRef.current.sendMessage({ message: `[Feeling ${currentEmotion}] ${text}` });
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: result.text || "I'm listening!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a momentary sync issue with my brain!",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-gray-950">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6">🚫</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 text-sm mb-6">{aiError}</p>
        <p className="text-xs text-indigo-500 font-bold uppercase tracking-widest">Check build env configuration</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100 text-center mb-2 px-4">Chat</h1>
      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm ${msg.sender === 'user' ? 'bg-indigo-600 text-white' : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-100 dark:border-gray-700'}`}>
              <p className="text-sm">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && <div className="text-xs text-gray-400 animate-pulse px-4">{companionName} is thinking...</div>}
        <div ref={messagesEndRef} />
      </div>
      <form onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} className="p-4 flex items-center gap-2 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-gray-800">
        <input type="text" value={userInput} onChange={(e) => setUserInput(e.target.value)} placeholder="Say something..." className="flex-1 p-3 border border-gray-200 dark:border-gray-700 dark:bg-gray-900 rounded-xl focus:outline-none" />
        <button type="submit" disabled={!userInput.trim()} className="p-3 bg-indigo-600 text-white rounded-xl active:scale-90 transition-transform"><PaperAirplaneIcon className="w-6 h-6" /></button>
      </form>
    </div>
  );
};

