import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { GoogleGenAI } from "@google/genai";

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<any>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  useEffect(() => {
    const initChat = async () => {
      try {
        // Use process.env.API_KEY directly as per SDK requirements.
        // The environment is assumed to provide this variable.
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const chat = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName || 'Pelio'}, a friendly and supportive emotion companion. 
            The user's name is ${userName || 'friend'}. 
            Current detected emotion: ${currentEmotion}. 
            Keep your responses concise, empathetic, and encouraging.`,
          },
        });

        chatSessionRef.current = chat;
        setAiError(null);

        if (messages.length === 0) {
          setMessages([{
            id: 'welcome',
            text: `Hi ${userName || 'there'}! I'm ${companionName || 'Pelio'}. I sense you're feeling ${currentEmotion.toLowerCase()}. How can I support you today?`,
            sender: 'companion',
            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        console.error("AI Initialization Error:", error);
        setAiError("Connection to the intelligence core was interrupted. Please check your network.");
      }
    };
    initChat();
  }, [companionName, userName]);

  const processMessage = async (text: string) => {
    const trimmedText = text.trim();
    if (!trimmedText || isTyping || aiError) return;

    const userMsg: ChatMessage = { 
      id: Date.now().toString(), 
      text: trimmedText, 
      sender: 'user', 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) {
        throw new Error("Intelligence session not initialized.");
      }

      // We send the current emotion context with every message to keep the AI updated
      const response = await chatSessionRef.current.sendMessage({ 
        message: `[User current emotion: ${currentEmotion}] ${trimmedText}` 
      });

      const responseText = response.text;

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: responseText || "I'm processing that. Tell me more!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error: any) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a little trouble processing that right now. Let's try again in a moment.",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6 shadow-inner">⚠️</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 dark:text-gray-400 text-sm mb-6">{aiError}</p>
        <button 
          onClick={() => window.location.reload()} 
          className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-xs shadow-lg active:scale-95 transition-all"
        >
          Retry Connection
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2 relative">
      <div className="px-6 mb-2 flex items-center justify-between">
         <h1 className="text-2xl font-black text-gray-800 dark:text-gray-100 tracking-tighter italic">Chat</h1>
         <div className="flex items-center gap-2">
            <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500 bg-indigo-50 dark:bg-indigo-900/30 px-3 py-1 rounded-full">
              {currentEmotion}
            </span>
         </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 px-4 animate-pulse">
            <div className="w-2 h-2 bg-indigo-400 rounded-full" />
            <div className="w-2 h-2 bg-indigo-400 rounded-full [animation-delay:200ms]" />
            <div className="w-2 h-2 bg-indigo-400 rounded-full [animation-delay:400ms]" />
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form 
        onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} 
        className="p-4 flex items-center gap-3 bg-white/50 dark:bg-gray-950/50 backdrop-blur-xl border-t border-gray-100 dark:border-gray-800 pb-20 sm:pb-4"
      >
        <input 
          type="text" 
          value={userInput} 
          onChange={(e) => setUserInput(e.target.value)} 
          placeholder="Type your message..." 
          className="flex-1 p-4 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-gray-800 dark:text-white font-medium" 
        />
        <button 
          type="submit" 
          disabled={!userInput.trim() || isTyping} 
          className={`p-4 rounded-2xl transition-all shadow-lg ${
            !userInput.trim() || isTyping 
              ? 'bg-gray-200 dark:bg-gray-800 text-gray-400' 
              : 'bg-indigo-600 text-white active:scale-90 hover:bg-indigo-700'
          }`}
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

