            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        console.error("AI Initialization Error:", error);
        setAiError("Connection to the intelligence core was interrupted. Please check your network.");
      }
    };
    initChat();
  }, [companionName, userName]);

  const processMessage = async (text: string) => {
    const trimmedText = text.trim();
    if (!trimmedText || isTyping || aiError) return;

    const userMsg: ChatMessage = { 
      id: Date.now().toString(), 
      text: trimmedText, 
      sender: 'user', 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) {
        throw new Error("Intelligence session not initialized.");
      }

      // We send the current emotion context with every message to keep the AI updated
      const response = await chatSessionRef.current.sendMessage({ 
        message: `[User current feeling: ${currentEmotion}] ${trimmedText}` 
      });

      const responseText = response.text;

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: responseText || "I'm processing that. Tell me more!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error: any) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a little trouble processing that right now. Let's try again in a moment.",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
