          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName || 'Pelio'}, a friendly and supportive emotion companion. 
            The user's name is ${userName || 'friend'}. 
            Current detected emotion: ${currentEmotion}. 
            Keep your responses concise, empathetic, and encouraging. You are their best friend.`,
          },
        });

        chatSessionRef.current = chat;
        setAiError(null);

        // Update welcome message if it's the only message in the thread
        setMessages(prev => {
          if (prev.length <= 1) {
            return [{
              id: 'welcome',
              text: `Hi ${userName || 'friend'}! I'm ${companionName || 'Pelio'}, your best friend and companion. I sense you're feeling ${currentEmotion.toLowerCase()} right now. I'm always here for you! How can I help today?`,
              sender: 'companion',
              timestamp: Date.now(),
            }];
          }
          return prev;
        });
      } catch (error: any) {
        console.error("AI Initialization Error:", error);
        setAiError("Connection to the intelligence core was interrupted. Please check your network.");
      }
    };
    initChat();
  }, [companionName, userName, currentEmotion]);

  const handleMoodChange = async (newEmotion: Emotion) => {
    setCurrentEmotion(newEmotion);
    setIsMoodDropdownOpen(false);

    // If a conversation has already started, have the companion acknowledge the change immediately
    if (messages.length > 1 && !isTyping && chatSessionRef.current) {
      setIsTyping(true);
      try {
        const response = await chatSessionRef.current.sendMessage({ 
          message: `(System Note: User manually updated their mood to ${newEmotion}. Acknowledge this briefly and empathetically, then wait for user input.)` 
        });

        setMessages(prev => [...prev, {
          id: Date.now().toString(),
          text: response.text || `I've updated my sensors. I see you're feeling ${newEmotion.toLowerCase()} now. I'm right here with you.`,
          sender: 'companion',
          timestamp: Date.now(),
        }]);
      } catch (e) {
        console.error("Mood acknowledgement error:", e);
      } finally {
        setIsTyping(false);
      }
    }
  };

  const processMessage = async (text: string) => {
    const trimmedText = text.trim();
    if (!trimmedText || isTyping || aiError) return;

    const userMsg: ChatMessage = { 
      id: Date.now().toString(), 
      text: trimmedText, 
      sender: 'user', 
      timestamp: Date.now() 
    };

    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) {
        throw new Error("Intelligence session not initialized.");
      }

      const response = await chatSessionRef.current.sendMessage({ 
        message: `[User current feeling: ${currentEmotion}] ${trimmedText}` 
      });

      const responseText = response.text;

      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: responseText || "I'm processing that. Tell me more!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error: any) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a little trouble processing that right now. Let's try again in a moment.",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const firstLetter = (companionName || 'P').charAt(0).toUpperCase();

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6 shadow-inner">⚠️</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 dark:text-gray-400 text-sm mb-6">{aiError}</p>
        <button 
          onClick={() => window.location.reload()} 
          className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-xs shadow-lg active:scale-95 transition-all"
        >
          Retry Connection
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2 relative">
      {/* Header */}
      <div className="px-6 mb-2 flex items-center justify-between z-20">
         <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 dark:bg-indigo-500 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20 border border-white/10">
               <span className="text-white text-xl font-black">{firstLetter}</span>
            </div>
            <h1 className="text-2xl font-black text-gray-800 dark:text-gray-100 tracking-tighter italic">
              Chat with {companionName || 'Pelio'}
            </h1>
         </div>

         {/* Mood Dropdown Selector */}
         <div className="relative" ref={dropdownRef}>
            <button 
              onClick={() => setIsMoodDropdownOpen(!isMoodDropdownOpen)}
              className="flex items-center gap-2 bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 px-3 py-1.5 rounded-full shadow-sm active:scale-95 transition-all"
            >
              <span className="text-lg leading-none">{EMOTION_DETAILS[currentEmotion]?.emoji || '😐'}</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500">
                {currentEmotion}
              </span>
              <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 text-gray-400 transition-transform ${isMoodDropdownOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {isMoodDropdownOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white dark:bg-gray-800 rounded-2xl shadow-2xl border border-gray-100 dark:border-gray-700 py-2 animate-fadeInUp backdrop-blur-xl">
                <div className="px-3 py-1 mb-1">
                   <p className="text-[8px] font-bold text-gray-400 uppercase tracking-[0.2em]">Manual Override</p>
                </div>
                {SUPPORTED_EMOTIONS.map((emo) => (
                  <button
                    key={emo}
                    onClick={() => handleMoodChange(emo)}
                    className={`w-full text-left px-4 py-2 text-xs font-bold flex items-center gap-3 transition-colors ${
                      currentEmotion === emo 
                        ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400' 
                        : 'text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
                    }`}
                  >
                    <span className="text-lg leading-none">{EMOTION_DETAILS[emo]?.emoji}</span>
                    <span>{emo}</span>
                  </button>
                ))}
              </div>
            )}
         </div>
      </div>

      {/* Message List */}
      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-8 h-8 rounded-lg bg-indigo-600 dark:bg-indigo-500 flex items-center justify-center flex-shrink-0 shadow-sm mb-1">
                <span className="text-white text-xs font-black">{firstLetter}</span>
              </div>
            )}
            <div className={`max-w-[85%] p-4 rounded-3xl shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 px-4 animate-pulse">
            <div className="w-8 h-8 rounded-lg bg-gray-200 dark:bg-gray-700 flex items-center justify-center flex-shrink-0">
               <span className="text-gray-400 text-[10px] font-black">{firstLetter}</span>
            </div>
            <div className="flex gap-1">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full" />
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full [animation-delay:200ms]" />
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full [animation-delay:400ms]" />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Form */}
      <form 
        onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} 
        className="p-4 flex items-center gap-3 bg-white/50 dark:bg-gray-950/50 backdrop-blur-xl border-t border-gray-100 dark:border-gray-800 pb-20 sm:pb-4"
      >
        <input 
          type="text" 
          value={userInput} 
          onChange={(e) => setUserInput(e.target.value)} 
          placeholder="Type your message..." 
          className="flex-1 p-4 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/50 text-gray-800 dark:text-white font-medium shadow-inner" 
        />
        <button 
          type="submit" 
          disabled={!userInput.trim() || isTyping} 
          className={`p-4 rounded-2xl transition-all shadow-lg ${
            !userInput.trim() || isTyping 
              ? 'bg-gray-200 dark:bg-gray-800 text-gray-400' 
              : 'bg-indigo-600 text-white active:scale-90 hover:bg-indigo-700 shadow-indigo-500/20'
          }`}
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

