      >
        <span className="text-white text-xs font-black block transform transition-transform group-hover:-translate-x-0.5">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
          </svg>
        </span>
      </button>

      {/* Slide-in Compact Panel */}
      <div className={`fixed top-0 right-0 h-full w-[280px] z-50 bg-white/40 dark:bg-gray-950/60 backdrop-blur-2xl border-l border-white/20 dark:border-gray-800 shadow-[-20px_0_50px_rgba(0,0,0,0.2)] transition-transform duration-500 flex flex-col ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-8">
                <h3 className="text-sm font-black uppercase tracking-widest text-gray-800 dark:text-white">Camera Studio</h3>
                <button onClick={() => setIsPanelOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full bg-black/10 dark:bg-white/10 text-gray-800 dark:text-white font-bold">
                    &times;
                </button>
            </div>

            {/* Live Preview Screen */}
            <div className="w-full aspect-video bg-black rounded-2xl overflow-hidden border border-white/10 shadow-inner mb-6 relative group">
                <video 
