  const getEmotionDetails = () => {
    // If system is OFF, OR if we are currently syncing/waiting/errored, show colorful Idle
    if (!isSystemRunning || apiStatus === 'idle' || apiStatus === 'calling' || apiStatus === 'error') {
      return idleDetails;
