                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                            </svg>
                        </span>
                        <span className="text-[9px] font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">Groundchat Priority</span>
                    </div>
                    <p className="text-[10px] text-gray-500 dark:text-gray-400 leading-tight">External USB sensors (Type-C) are prioritized for high-precision telemetry.</p>
                </div>
            </div>
        </div>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* TOP HEADER */}
      <div className="w-full px-6 py-6 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 dark:bg-indigo-500 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <span className="text-white text-xl">✨</span>
          </div>
          <div>
            <h1 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-tighter italic">Pelio<span className="text-indigo-600 dark:text-indigo-400">Scope</span></h1>
            <p className="text-[9px] text-gray-500 dark:text-gray-400 font-black uppercase tracking-[0.2em]">Real-time Intelligence</p>
          </div>
        </div>

        <div className="flex items-center gap-2 px-3 py-1.5 bg-white/60 dark:bg-gray-800/60 backdrop-blur-md rounded-full border border-white/20 dark:border-gray-700 shadow-sm">
           <div className={`w-1.5 h-1.5 rounded-full ${isSystemRunning ? (apiStatus === 'error' ? 'bg-red-500' : apiStatus === 'success' ? 'bg-green-500 animate-pulse' : 'bg-amber-400 animate-pulse') : 'bg-gray-300 dark:bg-gray-600'}`} />
           <span className="text-[9px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400">
             {isSystemRunning ? (apiStatus === 'error' ? 'Sync Error' : apiStatus === 'calling' ? 'Syncing...' : apiStatus === 'idle' ? 'Connecting...' : 'Active') : 'Idle'}
           </span>
        </div>
      </div>

      {/* MAIN EMOTION DISPLAY */}
      <div className="flex-grow w-full flex flex-col items-center justify-center px-6 text-center">
        <style>
          {`
            @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
            .animate-float { animation: float 4s ease-in-out infinite; }
          `}
        </style>

        <div className="relative mb-8">
          <div 
            className={`text-[150px] transition-all duration-1000 transform ${isSystemRunning ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`}
            style={{ 
                filter: isSystemRunning && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none',
                WebkitFilter: isSystemRunning && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none'
            }}
          >
            {display.emoji}
          </div>
        </div>

        <div className="space-y-2">
            <h2 className={`text-5xl font-black transition-all duration-500 tracking-tighter uppercase italic ${display.color}`}>
              {display.label}
            </h2>

            {isSystemRunning && apiStatus === 'success' && currentConfidence !== null && (
              <div className="inline-block bg-white/50 dark:bg-gray-800/50 px-4 py-1.5 rounded-full backdrop-blur-sm border border-white/20 dark:border-gray-700 animate-fadeInUp">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">
                  Confidence: {(currentConfidence * 100).toFixed(0)}%
                </span>
              </div>
            )}

            {apiStatus === 'error' && isSystemRunning && (
              <p className="text-[10px] font-black uppercase tracking-widest text-red-500 animate-pulse">
                Azure Sync Lost
              </p>
            )}
        </div>
      </div>

      {/* ACTIVATION CONTROL */}
      <div className="w-full max-w-sm px-6 pb-24 z-10">
        <div className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl p-6 rounded-[3rem] shadow-2xl border border-white/50 dark:border-gray-800 space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex flex-col">
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Telemetry</span>
              <span className="text-sm font-bold text-gray-800 dark:text-white">v2.5.2 Groundchat</span>
            </div>
            <div className="p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl text-indigo-600 dark:text-indigo-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
          </div>

          <button
            onClick={isCameraActive ? stopDetection : () => startDetection()}
            className={`w-full py-5 rounded-[2rem] font-black text-lg text-white shadow-xl transform active:scale-95 transition-all flex items-center justify-center gap-3 ${
              isCameraActive 
                ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-500/20' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/20'
            }`}
          >
            {isCameraActive ? "Deactivate PelioScope" : "Engage PelioScope"}
          </button>
        </div>
      </div>

      {/* Decorative Blur Backdrops */}
      <div className="fixed top-[-10%] right-[-10%] w-[50%] h-[50%] bg-indigo-400/10 dark:bg-indigo-900/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="fixed bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-400/10 dark:bg-purple-900/10 rounded-full blur-[100px] pointer-events-none" />
    </div>
  );
};

export default LiveTab;

{
  "name": "PelioScope Emotion Companion",
  "description": "PelioScope displays animated emojis representing detected emotions in real-time by synchronizing with an Azure-hosted AI service via WebSockets.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion } from '../types';

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    setCurrentEmotion,
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    setCurrentConfidence,
    setEmotionHistory
  } = useAppContext();

  // Local state for camera and detection
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [detectionInterval, setDetectionInterval] = useState(500);
  const [apiStatus, setApiStatus] = useState<'idle' | 'calling' | 'success' | 'error'>('idle');

  // Side Panel State
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');
  const [isScanning, setIsScanning] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const timerRef = useRef<number | null>(null);

  const AZURE_URL = "https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net";

  // COLORFUL IDLE: Indigo color to indicate "active loop but waiting for AI sync"
  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1',
    label: 'Idle'
  };

  // --- COMPREHENSIVE USB CAMERA DETECTION ---
  const refreshDevices = useCallback(async (forceWarmup = false) => {
    setIsScanning(true);
    try {
      /**
       * HARDWARE WARM-UP: 
       * Browsers (especially on mobile) often restrict access to device labels until a stream is opened.
       * We trigger a temporary stream to "wake up" the USB hardware stack.
       */
      if (forceWarmup || !devices.some(d => d.label)) {
        const warmupStream = await navigator.mediaDevices.getUserMedia({ video: true }).catch(() => null);
        if (warmupStream) {
          warmupStream.getTracks().forEach(track => track.stop());
        }
      }

      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);

      // Prioritization Logic: Find USB/UVC/External sensors first
      const externalCam = videoDevices.find(d => 
        d.label.toLowerCase().includes('usb') || 
        d.label.toLowerCase().includes('uvc') ||
        d.label.toLowerCase().includes('external') ||
        d.label.toLowerCase().includes('groundchat')
      );

      if (externalCam) {
        // Auto-select if a USB camera is found and nothing is selected yet, or if it's newly plugged in
        if (!selectedDeviceId || selectedDeviceId !== externalCam.deviceId) {
          setSelectedDeviceId(externalCam.deviceId);
        }
      } else if (videoDevices.length > 0 && !selectedDeviceId) {
        // Fallback to standard sensors (Front/Back)
        setSelectedDeviceId(videoDevices[0].deviceId);
      }
    } catch (err) {
      console.error("Hardware scan error:", err);
    } finally {
      setIsScanning(false);
    }
  }, [selectedDeviceId, devices]);

  // Run on mount and listen for hardware changes (USB Plug/Unplug)
  useEffect(() => {
    refreshDevices(true);

    const handleDeviceChange = () => {
      console.log("Hardware change detected. Rescanning...");
      refreshDevices();
    };

    navigator.mediaDevices.addEventListener('devicechange', handleDeviceChange);
    return () => navigator.mediaDevices.removeEventListener('devicechange', handleDeviceChange);
  }, []);

  // Determine visual state
  const getDisplayDetails = () => {
    if (!isSystemRunning || apiStatus === 'error' || apiStatus === 'idle' || apiStatus === 'calling') {
      return idleDetails;
    }
    const details = EMOTION_DETAILS[currentEmotion];
    return details ? { ...details, label: currentEmotion } : { ...idleDetails, label: 'Unknown' };
  };

  const display = getDisplayDetails();

  // --- WEBCAM CONTROL ---
  const startDetection = async (deviceId?: string) => {
    try {
      const targetId = deviceId || selectedDeviceId;
      // Using 720p or 480p constraints works best for USB UVC cameras on Android
      const constraints = { 
        video: targetId ? { deviceId: { exact: targetId }, width: { ideal: 640 }, height: { ideal: 480 } } : { width: 640, height: 480 }
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
        toggleSystemState('start');
        setApiStatus('idle');
      }
    } catch (err) {
      console.error("Failed to engage sensor:", err);
      // Fallback: If USB specific fails, try any available
      if (deviceId) startDetection();
    }
  };

  const stopDetection = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    toggleSystemState('stop');
    if (timerRef.current) clearInterval(timerRef.current);
    setApiStatus('idle');
  };

  const handleDeviceChange = (deviceId: string) => {
    setSelectedDeviceId(deviceId);
    if (isCameraActive) {
      stopDetection();
      setTimeout(() => startDetection(deviceId), 500);
    }
  };

  const performDetection = useCallback(async () => {
    if (!isCameraActive || !videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 320;
    canvas.height = 240;
    ctx.drawImage(video, 0, 0, 320, 240);

    canvas.toBlob(async (blob) => {
      if (!blob) return;
      const formData = new FormData();
      formData.append('file', blob, 'frame.jpg');

      try {
        setApiStatus('calling');
        const response = await fetch(`${AZURE_URL}/predict`, {
          method: 'POST',
          body: formData
        });
        const data = await response.json();

        if (data.success && data.results && data.results.length > 0) {
          setApiStatus('success');
          const detectedEmotion = data.results[0].emotion as Emotion;
          setCurrentEmotion(detectedEmotion);
          setCurrentConfidence(data.results[0].confidence);

          setEmotionHistory(prev => {
            if (prev.length === 0 || prev[0].emotion !== detectedEmotion) {
              return [{ id: Date.now().toString(), emotion: detectedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
            }
            return prev;
          });
        } else {
          setApiStatus('success');
        }
      } catch (err) {
        setApiStatus('error');
      }
    }, 'image/jpeg', 0.6);
  }, [isCameraActive, setCurrentEmotion, setCurrentConfidence, setEmotionHistory]);

  useEffect(() => {
    if (isCameraActive) {
      timerRef.current = window.setInterval(performDetection, detectionInterval);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isCameraActive, detectionInterval, performDetection]);

  return (
    <div className="flex flex-col items-center justify-between h-full transition-colors duration-500 overflow-hidden relative">

      {/* Side Panel Trigger */}
      {!isPanelOpen && (
        <button 
          onClick={() => setIsPanelOpen(true)}
          className="fixed right-0 top-1/2 -translate-y-1/2 z-[60] bg-white/40 dark:bg-black/40 backdrop-blur-md border border-r-0 border-white/30 dark:border-gray-700 py-10 px-2 rounded-l-3xl shadow-xl transition-all active:scale-95 group animate-fadeIn"
        >
          <span className="text-indigo-600 dark:text-indigo-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
            </svg>
          </span>
        </button>
      )}

      {/* Side Camera Control Panel */}
      <div className={`fixed top-0 right-0 h-full w-[290px] z-[70] bg-white/95 dark:bg-gray-900/95 backdrop-blur-3xl border-l border-gray-200 dark:border-gray-800 shadow-2xl transition-transform duration-500 ease-[cubic-bezier(0.19,1,0.22,1)] flex flex-col ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-pulse shadow-[0_0_10px_#6366f1]" />
                  <h3 className="text-[11px] font-black uppercase tracking-[0.2em] text-gray-500">Sensor Config</h3>
                </div>
                <button onClick={() => setIsPanelOpen(false)} className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-400 hover:text-indigo-500 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
            </div>

            {/* Live Mini Preview */}
            <div className="w-full aspect-video bg-black rounded-2xl overflow-hidden border border-white/10 shadow-2xl mb-8 relative">
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    className={`w-full h-full object-cover transition-opacity duration-700 ${isCameraActive ? 'opacity-100' : 'opacity-0'}`}
                />
                {!isCameraActive && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-600 p-4 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-3 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                        </svg>
                        <span className="text-[10px] font-black uppercase tracking-widest opacity-30">Camera Loop Standby</span>
                    </div>
                )}
                {isCameraActive && selectedDeviceId && devices.find(d => d.deviceId === selectedDeviceId)?.label.toLowerCase().includes('usb') && (
                  <div className="absolute top-2 left-2 bg-indigo-600 px-2 py-1 rounded-md shadow-lg border border-white/20">
                    <span className="text-[8px] font-black text-white uppercase tracking-tighter">USB Feed</span>
                  </div>
                )}
            </div>

            <div className="space-y-6">
                <div className="space-y-2">
                    <div className="flex items-center justify-between px-1">
                        <label className="text-[9px] font-black uppercase tracking-[0.15em] text-gray-400">Primary Sensor</label>
                        <button 
                          onClick={() => refreshDevices(true)}
                          className={`text-[9px] font-black uppercase text-indigo-500 hover:text-indigo-600 transition-colors ${isScanning ? 'animate-pulse' : ''}`}
                        >
                          {isScanning ? 'Syncing...' : 'Rescan Sensors'}
                        </button>
                    </div>
                    <div className="relative group">
                        <select 
                            value={selectedDeviceId}
                            onChange={(e) => handleDeviceChange(e.target.value)}
                            className="w-full bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-4 text-[11px] font-bold text-gray-700 dark:text-white outline-none appearance-none shadow-sm pr-10 hover:border-indigo-500 transition-colors"
                        >
                            {devices.length === 0 ? (
                                <option value="">Initializing hardware...</option>
                            ) : (
                                devices.map(d => {
                                  const isUsb = d.label.toLowerCase().includes('usb') || d.label.toLowerCase().includes('uvc') || d.label.toLowerCase().includes('external');
                                  return (
                                    <option key={d.deviceId} value={d.deviceId}>
                                        {isUsb ? '🔌 ' : '📱 '}{d.label || `Sensor [${d.deviceId.slice(0, 4)}]`}
                                    </option>
                                  );
                                })
                            )}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-400">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                        </div>
                    </div>
                </div>

                <div className="bg-indigo-50 dark:bg-indigo-500/10 p-5 rounded-3xl border border-indigo-100 dark:border-indigo-500/20">
                    <div className="flex items-center gap-2 mb-2">
                        <div className="bg-indigo-600 p-1.5 rounded-lg">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                          </svg>
                        </div>
                        <span className="text-[10px] font-black text-indigo-700 dark:text-indigo-400 uppercase tracking-widest">External Logic</span>
                    </div>
                    <p className="text-[10px] text-gray-600 dark:text-gray-400 leading-relaxed">
                      Type-C USB cameras (UVC) are prioritized for high-precision emotion telemetry. Plug in your sensor and tap <b>Rescan</b> if it doesn't appear automatically.
                    </p>
                </div>
            </div>
        </div>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* Top Header */}
      <div className="w-full px-6 py-6 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 dark:bg-indigo-500 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-500/20">
            <span className="text-white text-xl">✨</span>
          </div>
          <div>
            <h1 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-tighter italic">Pelio<span className="text-indigo-600 dark:text-indigo-400">Scope</span></h1>
            <p className="text-[9px] text-gray-500 dark:text-gray-400 font-black uppercase tracking-[0.2em]">Real-time Intelligence</p>
          </div>
        </div>

        <div className="flex items-center gap-2 px-3 py-1.5 bg-white/60 dark:bg-gray-800/60 backdrop-blur-md rounded-full border border-white/20 dark:border-gray-700 shadow-sm">
           <div className={`w-1.5 h-1.5 rounded-full ${isSystemRunning ? (apiStatus === 'error' ? 'bg-red-500' : apiStatus === 'success' ? 'bg-green-500 animate-pulse' : 'bg-amber-400 animate-pulse') : 'bg-gray-300 dark:bg-gray-600'}`} />
           <span className="text-[9px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400">
             {isSystemRunning ? (apiStatus === 'error' ? 'Sync Error' : apiStatus === 'calling' ? 'Syncing...' : 'Connected') : 'Idle'}
           </span>
        </div>
      </div>

      {/* Main Display Area */}
      <div className="flex-grow w-full flex flex-col items-center justify-center px-6 text-center">
        <style>
          {`
            @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
            .animate-float { animation: float 4s ease-in-out infinite; }
          `}
        </style>

        <div className="relative mb-8">
          <div 
            className={`text-[150px] transition-all duration-1000 transform ${isSystemRunning && apiStatus === 'success' ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`}
            style={{ 
                filter: isSystemRunning && apiStatus === 'success' && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none',
                WebkitFilter: isSystemRunning && apiStatus === 'success' && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none'
            }}
          >
            {display.emoji}
          </div>
        </div>

        <div className="space-y-2">
            <h2 className={`text-5xl font-black transition-all duration-500 tracking-tighter uppercase italic ${display.color}`}>
              {display.label}
            </h2>

            {isSystemRunning && apiStatus === 'success' && currentConfidence !== null && (
              <div className="inline-block bg-white/50 dark:bg-gray-800/50 px-4 py-1.5 rounded-full backdrop-blur-sm border border-white/20 dark:border-gray-700 animate-fadeInUp">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">
                  Confidence: {(currentConfidence * 100).toFixed(0)}%
                </span>
              </div>
            )}
        </div>
      </div>

      {/* Activation Panel */}
      <div className="w-full max-w-sm px-6 pb-24 z-10">
        <div className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl p-6 rounded-[3rem] shadow-2xl border border-white/50 dark:border-gray-800 space-y-6">
          <button
            onClick={isCameraActive ? stopDetection : () => startDetection()}
            className={`w-full py-5 rounded-[2rem] font-black text-lg text-white shadow-xl transform active:scale-95 transition-all flex items-center justify-center gap-3 ${
              isCameraActive 
                ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-500/20' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/20'
            }`}
          >
            {isCameraActive ? "Deactivate PelioScope" : "Engage PelioScope"}
          </button>
        </div>
      </div>

      {/* Decorative Blurs */}
      <div className="fixed top-[-10%] right-[-10%] w-[50%] h-[50%] bg-indigo-400/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="fixed bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-400/10 rounded-full blur-[100px] pointer-events-none" />
    </div>
  );
};

export default LiveTab;

import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<any>(null);
  const lastEmotionRef = useRef<Emotion | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  // Initialize or re-initialize chat when companion/user/emotion changes
  // We keep currentEmotion in dependencies to ensure the system instruction always knows the latest mood
  useEffect(() => {
    const initChat = async () => {
      try {
        const key = typeof process !== 'undefined' && process.env ? process.env.API_KEY : null;
        if (!key) {
          throw new Error("ENVIRONMENT_MISSING: API Key is not detected.");
        }

        const ai = new GoogleGenAI({ apiKey: key });
        const chat = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName}, a friendly emotion companion for ${userName || 'a user'}. 
            Your goal is to support the user based on their current detected emotion. 
            Keep responses concise, human-like, and empathetic. 
            Currently, the user's sensors indicate they are feeling: ${currentEmotion}. 
            Respond accordingly to this mood state.`,
          },
        });
        chatSessionRef.current = chat;
        setAiError(null);

        // Initial welcome message setup
        if (messages.length === 0) {
          setMessages([{
            id: 'welcome',
            text: `Hi ${userName || 'friend'}! I'm ${companionName}. I see you're feeling ${currentEmotion.toLowerCase()}! How can I help you today?`,
            sender: 'companion',
            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        setAiError(error.message || "Failed to start AI service.");
      }
    };
    initChat();
  }, [companionName, userName, currentEmotion]);

  // SPEC: React to emotion changes proactively (Mood Change Acknowledgement)
  useEffect(() => {
    // Skip if emotion hasn't actually changed from last check
    if (lastEmotionRef.current === currentEmotion) return;

    const acknowledgeMoodShift = async () => {
      // 1. Dynamic Welcome Message: Update the very first message if conversation hasn't started
      if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
          id: 'welcome',
          text: `Hi ${userName || 'friend'}! I'm ${companionName}. I see your mood has shifted to ${currentEmotion.toLowerCase()}! How are you doing?`,
          sender: 'companion',
          timestamp: Date.now(),
        }]);
      } 
      // 2. Mood Change Acknowledgement: Proactive AI response during active conversation
      else if (messages.length > 1 && chatSessionRef.current && !isTyping) {
        setIsTyping(true);
        try {
          const nudge = `[System Nudge: The user's detected mood has just shifted to ${currentEmotion}. Briefly acknowledge this change in persona before we continue.]`;
          const result = await chatSessionRef.current.sendMessage({ message: nudge });

          if (result.text) {
            setMessages(prev => [...prev, {
              id: 'mood-shift-' + Date.now(),
              text: result.text,
              sender: 'companion',
              timestamp: Date.now(),
            }]);
          }
        } catch (e) {
          console.error("Mood shift nudge failed", e);
        } finally {
          setIsTyping(false);
        }
      }
      lastEmotionRef.current = currentEmotion;
    };

    acknowledgeMoodShift();
  }, [currentEmotion, messages.length, userName, companionName]);

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping || aiError) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), text, sender: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) throw new Error("Not connected");
      const result = await chatSessionRef.current.sendMessage({ message: `[Feeling ${currentEmotion}] ${text}` });
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: result.text || "I'm listening!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a momentary sync issue with my brain!",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-gray-950">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6">🚫</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 text-sm mb-6">{aiError}</p>
        <p className="text-xs text-indigo-500 font-bold uppercase tracking-widest">Check build env configuration</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      <div className="flex flex-col items-center mb-2 px-4">
          <h1 className="text-2xl font-black text-gray-800 dark:text-gray-100 italic tracking-tighter">PELIO<span className="text-indigo-600">CHAT</span></h1>
          <div className="flex items-center gap-1.5 mt-1">
              <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Active with {companionName}</span>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide bg-gray-50/50 dark:bg-transparent rounded-t-[2.5rem] mt-2">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-8 h-8 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-xs shrink-0 mb-1 border border-indigo-200/50">
                ✨
              </div>
            )}
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-white border border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 px-4">
             <div className="flex gap-1">
                <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></span>
             </div>
             <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{companionName} is typing</span>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form 
        onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} 
        className="p-4 flex items-center gap-2 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-gray-800"
      >
        <input 
          type="text" 
          value={userInput} 
          onChange={(e) => setUserInput(e.target.value)} 
          placeholder={`Message ${companionName}...`} 
          className="flex-1 p-4 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm font-medium" 
        />
        <button 
          type="submit" 
          disabled={!userInput.trim() || isTyping} 
          className="p-4 bg-indigo-600 text-white rounded-2xl active:scale-90 transition-transform disabled:opacity-50 disabled:grayscale"
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

export default ChatTab;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion } from '../types';

/**
 * USBCameraEngine
 * Encapsulates hardware-specific logic for USB/UVC sensors.
 */
const USBCameraEngine = {
  scan: async (onUpdate: (devices: MediaDeviceInfo[]) => void) => {
    try {
      /**
       * HARDWARE WARM-UP: 
       * Requesting a temporary stream forces the mobile browser to index external sensors
       * and reveal their hardware labels.
       */
      const tempStream = await navigator.mediaDevices.getUserMedia({ video: true }).catch(() => null);
      if (tempStream) tempStream.getTracks().forEach(t => t.stop());

      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(d => d.kind === 'videoinput');
      onUpdate(videoDevices);
      return videoDevices;
    } catch (e) {
      console.error("Hardware scan engine failure:", e);
      return [];
    }
  },
  isExternal: (device: MediaDeviceInfo) => {
    const label = device.label.toLowerCase();
    return label.includes('usb') || label.includes('uvc') || label.includes('external') || label.includes('groundchat');
  }
};

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    setCurrentEmotion,
    toggleSystemState, 
    isSystemRunning,
    currentConfidence, 
    setCurrentConfidence,
    setEmotionHistory
  } = useAppContext();

  const [isCameraActive, setIsCameraActive] = useState(false);
  const [detectionInterval, setDetectionInterval] = useState(500);
  const [apiStatus, setApiStatus] = useState<'idle' | 'calling' | 'success' | 'error'>('idle');
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');
  const [isScanning, setIsScanning] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const timerRef = useRef<number | null>(null);

  const AZURE_URL = "https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net";

  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1',
    label: 'Idle'
  };

  const refreshDevices = useCallback(async (forceAutoSelect = false) => {
    setIsScanning(true);
    const foundDevices = await USBCameraEngine.scan(setDevices);

    // Auto-prioritize USB camera if detected
    const external = foundDevices.find(USBCameraEngine.isExternal);
    if (external && (!selectedDeviceId || forceAutoSelect)) {
      setSelectedDeviceId(external.deviceId);
    } else if (foundDevices.length > 0 && !selectedDeviceId) {
      setSelectedDeviceId(foundDevices[0].deviceId);
    }
    setIsScanning(false);
  }, [selectedDeviceId]);

  // SPEC: Detect USB camera when app starts or tab opens
  useEffect(() => {
    refreshDevices(true);

    const onHardwareChange = () => {
      console.log("Hardware connection changed, rescanning sensors...");
      refreshDevices();
    };

    navigator.mediaDevices.addEventListener('devicechange', onHardwareChange);
    return () => navigator.mediaDevices.removeEventListener('devicechange', onHardwareChange);
  }, []);

  const getDisplayDetails = () => {
    if (!isSystemRunning || apiStatus === 'error' || apiStatus === 'idle' || apiStatus === 'calling') {
      return idleDetails;
    }
    const details = EMOTION_DETAILS[currentEmotion];
    return details ? { ...details, label: currentEmotion } : { ...idleDetails, label: 'Unknown' };
  };

  const display = getDisplayDetails();

  const startDetection = async (deviceId?: string) => {
    try {
      const targetId = deviceId || selectedDeviceId;
      // Ideal resolutions for UVC sensors on Android are usually 640x480 or 1280x720
      const constraints = { 
        video: targetId ? { deviceId: { exact: targetId }, width: { ideal: 640 }, height: { ideal: 480 } } : { width: 640, height: 480 }
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
        toggleSystemState('start');
        setApiStatus('idle');
      }
    } catch (err) {
      console.error("Failed to engage sensor stream:", err);
      // Fallback: If USB specific fails, try any available
      if (deviceId) startDetection();
    }
  };

  const stopDetection = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    toggleSystemState('stop');
    if (timerRef.current) clearInterval(timerRef.current);
    setApiStatus('idle');
  };

  const handleDeviceChange = (deviceId: string) => {
    setSelectedDeviceId(deviceId);
    if (isCameraActive) {
      stopDetection();
      setTimeout(() => startDetection(deviceId), 500);
    }
  };

  const performDetection = useCallback(async () => {
    if (!isCameraActive || !videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 320;
    canvas.height = 240;
    ctx.drawImage(video, 0, 0, 320, 240);

    canvas.toBlob(async (blob) => {
      if (!blob) return;
      const formData = new FormData();
      formData.append('file', blob, 'frame.jpg');

      try {
        setApiStatus('calling');
        const response = await fetch(`${AZURE_URL}/predict`, {
          method: 'POST',
          body: formData
        });
        const data = await response.json();

        if (data.success && data.results && data.results.length > 0) {
          setApiStatus('success');
          const detectedEmotion = data.results[0].emotion as Emotion;
          setCurrentEmotion(detectedEmotion);
          setCurrentConfidence(data.results[0].confidence);

          setEmotionHistory(prev => {
            if (prev.length === 0 || prev[0].emotion !== detectedEmotion) {
              return [{ id: Date.now().toString(), emotion: detectedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
            }
            return prev;
          });
        } else {
          setApiStatus('success');
        }
      } catch (err) {
        setApiStatus('error');
      }
    }, 'image/jpeg', 0.6);
  }, [isCameraActive, setCurrentEmotion, setCurrentConfidence, setEmotionHistory]);

  useEffect(() => {
    if (isCameraActive) {
      timerRef.current = window.setInterval(performDetection, detectionInterval);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isCameraActive, detectionInterval, performDetection]);

  const selectedDeviceIsUsb = devices.find(d => d.deviceId === selectedDeviceId && USBCameraEngine.isExternal(d));

  return (
    <div className="flex flex-col items-center justify-between h-full transition-colors duration-500 overflow-hidden relative">

      {/* Sensor Control Side-Panel Trigger */}
      {!isPanelOpen && (
        <button 
          onClick={() => setIsPanelOpen(true)}
          className="fixed right-0 top-1/2 -translate-y-1/2 z-[60] bg-white/40 dark:bg-black/40 backdrop-blur-md border border-r-0 border-white/30 dark:border-gray-700 py-10 px-2 rounded-l-3xl shadow-xl transition-all active:scale-95 group animate-fadeIn"
        >
          <span className="text-indigo-600 dark:text-indigo-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
            </svg>
          </span>
        </button>
      )}

      {/* COMPACT SENSOR PANEL */}
      <div className={`fixed top-0 right-0 h-full w-[290px] z-[70] bg-white/95 dark:bg-gray-900/95 backdrop-blur-3xl border-l border-gray-200 dark:border-gray-800 shadow-2xl transition-transform duration-500 ease-[cubic-bezier(0.19,1,0.22,1)] flex flex-col ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-6 flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 bg-indigo-500 rounded-full animate-pulse shadow-[0_0_10px_#6366f1]" />
                  <h3 className="text-[11px] font-black uppercase tracking-[0.2em] text-gray-500">Sensor Matrix</h3>
                </div>
                <button onClick={() => setIsPanelOpen(false)} className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-400 hover:text-indigo-500 transition-colors">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
            </div>

            <div className="w-full aspect-video bg-black rounded-2xl overflow-hidden border border-white/10 shadow-2xl mb-8 relative">
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    className={`w-full h-full object-cover transition-opacity duration-700 ${isCameraActive ? 'opacity-100' : 'opacity-0'}`}
                />
                {!isCameraActive && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-600 p-4 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-3 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                        </svg>
                        <span className="text-[10px] font-black uppercase tracking-widest opacity-30">Camera Loop Off</span>
                    </div>
                )}
                {isCameraActive && selectedDeviceIsUsb && (
                  <div className="absolute top-2 left-2 bg-indigo-600 px-2 py-1 rounded-md shadow-lg border border-white/20">
                    <span className="text-[8px] font-black text-white uppercase tracking-tighter">USB Feed Active</span>
                  </div>
                )}
            </div>

            <div className="space-y-6">
                <div className="space-y-2">
                    <div className="flex items-center justify-between px-1">
                        <label className="text-[9px] font-black uppercase tracking-[0.15em] text-gray-400">Primary Sensor</label>
                        <button 
                          onClick={() => refreshDevices(true)}
                          className={`text-[9px] font-black uppercase text-indigo-500 hover:text-indigo-600 transition-colors ${isScanning ? 'animate-pulse' : ''}`}
                        >
                          {isScanning ? 'Syncing...' : 'Rescan Sensors'}
                        </button>
                    </div>
                    <div className="relative group">
                        <select 
                            value={selectedDeviceId}
                            onChange={(e) => handleDeviceChange(e.target.value)}
                            className="w-full bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-4 text-[11px] font-bold text-gray-700 dark:text-white outline-none appearance-none shadow-sm pr-10 hover:border-indigo-500 transition-colors"
                        >
                            {devices.length === 0 ? (
                                <option value="">Initializing hardware...</option>
                            ) : (
                                devices.map(d => {
                                  const isUsb = USBCameraEngine.isExternal(d);
                                  return (
                                    <option key={d.deviceId} value={d.deviceId}>
                                        {isUsb ? '🔌 ' : '📱 '}{d.label || `Hardware Sensor [${d.deviceId.slice(0, 4)}]`}
                                    </option>
                                  );
                                })
                            )}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-400">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                        </div>
                    </div>
                </div>

                <div className="bg-indigo-50 dark:bg-indigo-500/10 p-5 rounded-3xl border border-indigo-100 dark:border-indigo-500/20">
                    <div className="flex items-center gap-2 mb-2">
                        <div className="bg-indigo-600 p-1.5 rounded-lg">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                          </svg>
                        </div>
                        <span className="text-[10px] font-black text-indigo-700 dark:text-indigo-400 uppercase tracking-widest">Groundchat Priority</span>
                    </div>
                    <p className="text-[10px] text-gray-600 dark:text-gray-400 leading-relaxed">
                      Type-C USB cameras (UVC) are auto-detected and prioritized for high-precision emotion telemetry. Plug in your sensor and PelioScope handles the handshake.
                    </p>
                </div>
            </div>
        </div>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* TOP HEADER */}
      <div className="w-full px-6 py-6 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 dark:bg-indigo-500 rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-500/20">
            <span className="text-white text-xl">✨</span>
          </div>
          <div>
            <h1 className="text-sm font-black text-gray-800 dark:text-white uppercase tracking-tighter italic">Pelio<span className="text-indigo-600 dark:text-indigo-400">Scope</span></h1>
            <p className="text-[9px] text-gray-500 dark:text-gray-400 font-black uppercase tracking-[0.2em]">Real-time Intelligence</p>
          </div>
        </div>

        <div className="flex items-center gap-2 px-3 py-1.5 bg-white/60 dark:bg-gray-800/60 backdrop-blur-md rounded-full border border-white/20 dark:border-gray-700 shadow-sm">
           <div className={`w-1.5 h-1.5 rounded-full ${isSystemRunning ? (apiStatus === 'error' ? 'bg-red-500' : apiStatus === 'success' ? 'bg-green-500 animate-pulse' : 'bg-amber-400 animate-pulse') : 'bg-gray-300 dark:bg-gray-600'}`} />
           <span className="text-[9px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400">
             {isSystemRunning ? (apiStatus === 'error' ? 'Sync Error' : apiStatus === 'calling' ? 'Syncing...' : 'Connected') : 'Idle'}
           </span>
        </div>
      </div>

      {/* MAIN EMOTION DISPLAY AREA */}
      <div className="flex-grow w-full flex flex-col items-center justify-center px-6 text-center">
        <style>
          {`
            @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
            .animate-float { animation: float 4s ease-in-out infinite; }
          `}
        </style>

        <div className="relative mb-8">
          <div 
            className={`text-[150px] transition-all duration-1000 transform ${isSystemRunning && apiStatus === 'success' ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`}
            style={{ 
                filter: isSystemRunning && apiStatus === 'success' && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none',
                WebkitFilter: isSystemRunning && apiStatus === 'success' && display.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${display.pulseColor})` : 'none'
            }}
          >
