        <div className="flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-gray-800 rounded-full border border-gray-100 dark:border-gray-700 shadow-sm">
           <div className={`w-1.5 h-1.5 rounded-full ${isSystemRunning ? (apiStatus === 'error' ? 'bg-red-500' : 'bg-green-500 animate-pulse') : 'bg-gray-300 dark:bg-gray-600'}`} />
           <span className="text-[9px] font-black uppercase tracking-widest text-gray-500 dark:text-gray-400">
             {isSystemRunning ? (apiStatus === 'error' ? 'Sync Error' : apiStatus === 'calling' ? 'Syncing...' : 'Connected') : 'Idle'}
           </span>
        </div>
      </div>

      {/* Main Emotion Display Area */}
      <div className="flex-grow w-full flex flex-col items-center justify-center px-6 text-center">
        <style>
          {`
            @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-20px); } }
            .animate-float { animation: float 4s ease-in-out infinite; }
          `}
        </style>

        <div className="relative mb-8">
          <div 
            className={`text-[150px] transition-all duration-1000 transform ${isSystemRunning ? 'scale-110 animate-float' : 'scale-90 opacity-40 grayscale'}`}
            style={{ 
                filter: isSystemRunning && emotionDetails.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${emotionDetails.pulseColor})` : 'none',
                // FIX: Removed stray backslash that was causing a JSX syntax error
                WebkitFilter: isSystemRunning && emotionDetails.pulseColor !== 'transparent' ? `drop-shadow(0 0 50px ${emotionDetails.pulseColor})` : 'none'
            }}
          >
            {emotionDetails.emoji}
          </div>
        </div>

        <div className="space-y-2">
            <h2 className={`text-5xl font-black transition-all duration-500 tracking-tighter uppercase italic ${emotionDetails.color}`}>
              {isSystemRunning ? currentEmotion : 'Idle'}
            </h2>

            {isSystemRunning && currentConfidence !== null && (
              <div className="inline-block bg-white/50 dark:bg-gray-800/50 px-4 py-1.5 rounded-full backdrop-blur-sm border border-white/20 dark:border-gray-700 animate-fadeInUp">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">
                  Confidence: {(currentConfidence * 100).toFixed(0)}%
                </span>
              </div>
            )}
        </div>
      </div>

      {/* Main Control Panel (Visible in center bottom) */}
      <div className="w-full max-w-sm px-6 pb-24 z-10">
        <div className="bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl p-6 rounded-[3rem] shadow-2xl border border-white/50 dark:border-gray-800 space-y-6">
          <div className="flex items-center justify-between px-2">
            <div className="flex flex-col">
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Capture Loop</span>
              <span className="text-sm font-bold text-gray-800 dark:text-white">{detectionInterval}ms Telemetry</span>
            </div>
            <div className="p-3 bg-indigo-50 dark:bg-indigo-900/30 rounded-2xl text-indigo-600 dark:text-indigo-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
          </div>

          <button
            onClick={isCameraActive ? stopDetection : () => startDetection()}
            className={`w-full py-5 rounded-[2rem] font-black text-lg text-white shadow-xl transform active:scale-95 transition-all flex items-center justify-center gap-3 ${
              isCameraActive 
                ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-500/20' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/20'
            }`}
          >
            {isCameraActive ? (
              <>
                <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
                <span>Stop PelioScope</span>
              </>
            ) : (
              <>
                <span>Activate PelioScope</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Decorative Blur Backgrounds */}
      <div className="fixed top-[-10%] right-[-10%] w-[50%] h-[50%] bg-indigo-400/10 dark:bg-indigo-900/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="fixed bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-400/10 dark:bg-purple-900/10 rounded-full blur-[100px] pointer-events-none" />
    </div>
  );
};

export default LiveTab;

import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion, SUPPORTED_EMOTIONS } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, setCurrentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<any>(null);
  const lastEmotionRef = useRef<Emotion | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  // Initialize or re-initialize chat when companion/user/emotion changes
  useEffect(() => {
    const initChat = async () => {
      try {
        // ALWAYS use a named parameter for the API key as per guidelines
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const chat = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName || 'Peli'}, a friendly emotion companion for ${userName || 'a friend'}. 
            Your goal is to support the user based on their current detected emotion. 
            Keep responses concise, human-like, and empathetic. 
            Currently, the user's sensors indicate they are feeling: ${currentEmotion}. 
            Respond accordingly to this mood state.`,
          },
        });
        chatSessionRef.current = chat;
        setAiError(null);

        // Initial welcome message setup - Updated with the specific friendly text
        if (messages.length === 0) {
          setMessages([{
            id: 'welcome',
            text: `Hi ${userName || 'Friend'}! I'm ${companionName || 'Peli'}, your best friend and companion. I sense you're feeling ${currentEmotion.toLowerCase()} right now. I'm always here for you! How can I help?`,
            sender: 'companion',
            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        setAiError(error.message || "Failed to start AI service.");
      }
    };
    initChat();
  }, [companionName, userName, currentEmotion]);

  // SPEC: React to emotion changes proactively
  useEffect(() => {
    if (lastEmotionRef.current === currentEmotion) return;

    const acknowledgeMoodShift = async () => {
      // 1. Dynamic Welcome Message: Update the very first message if conversation hasn't started
      if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
          id: 'welcome',
          text: `Hi ${userName || 'Friend'}! I'm ${companionName || 'Peli'}, your best friend and companion. I sense you're feeling ${currentEmotion.toLowerCase()} right now. I'm always here for you! How can I help?`,
          sender: 'companion',
          timestamp: Date.now(),
        }]);
      } 
      // 2. Mood Change Acknowledgement during active conversation
      else if (messages.length > 1 && chatSessionRef.current && !isTyping) {
        setIsTyping(true);
        try {
          const nudge = `[System Nudge: The user's detected mood has just shifted to ${currentEmotion}. Briefly acknowledge this change in persona before we continue.]`;
          const result = await chatSessionRef.current.sendMessage({ message: nudge });

          if (result.text) {
            setMessages(prev => [...prev, {
              id: 'mood-shift-' + Date.now(),
              text: result.text,
              sender: 'companion',
              timestamp: Date.now(),
            }]);
          }
        } catch (e) {
          console.error("Mood shift nudge failed", e);
        } finally {
          setIsTyping(false);
        }
      }
      lastEmotionRef.current = currentEmotion;
    };

    acknowledgeMoodShift();
  }, [currentEmotion, messages.length, userName, companionName]);

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping || aiError) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), text, sender: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) throw new Error("Not connected");
      const result = await chatSessionRef.current.sendMessage({ message: `[Feeling ${currentEmotion}] ${text}` });
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: result.text || "I'm listening!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a momentary sync issue with my brain!",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-gray-950">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6">🚫</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 dark:text-gray-400 text-sm mb-6">{aiError}</p>
        <p className="text-xs text-indigo-500 font-bold uppercase tracking-widest">Check build env configuration</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      {/* Header with Emotion Selector - Fixed visibility of emotion text */}
      <div className="flex items-center justify-between mb-2 px-4">
          <div className="flex flex-col">
              <h1 className="text-2xl font-black text-gray-900 dark:text-gray-100 italic tracking-tighter">PELIO<span className="text-indigo-600">CHAT</span></h1>
              <div className="flex items-center gap-1.5 mt-1">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                  <span className="text-[10px] font-black uppercase text-gray-500 dark:text-gray-400 tracking-widest">Active with {companionName || 'Peli'}</span>
              </div>
          </div>

          {/* Manual Emotion Dropdown - High contrast fix for letters */}
          <div className="relative">
             <select 
               value={currentEmotion}
               onChange={(e) => setCurrentEmotion(e.target.value as Emotion)}
               className="bg-white dark:bg-gray-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-2xl px-4 py-2 text-sm font-black text-indigo-950 dark:text-indigo-50 shadow-md outline-none appearance-none cursor-pointer hover:border-indigo-500 transition-all pr-10"
             >
                {SUPPORTED_EMOTIONS.map(emo => (
                  <option key={emo} value={emo} className="bg-white dark:bg-gray-900 text-gray-900 dark:text-white font-bold">
                    {EMOTION_DETAILS[emo].emoji} {emo}
                  </option>
                ))}
             </select>
             <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
               </svg>
             </div>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide bg-white/50 dark:bg-transparent rounded-t-[2.5rem] mt-2">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-9 h-9 rounded-full bg-indigo-600 dark:bg-indigo-500 flex items-center justify-center text-white text-[11px] font-black shrink-0 mb-1 shadow-lg border-2 border-white dark:border-gray-800 uppercase tracking-tighter">
                {(companionName || 'Peli').charAt(0)}
              </div>
            )}
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-900 dark:text-white border border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 px-4">
             <div className="w-9 h-9 rounded-full bg-indigo-600/20 flex items-center justify-center shrink-0">
                <div className="flex gap-1">
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></span>
                </div>
             </div>
             <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{companionName || 'Peli'} is thinking</span>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form 
        onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} 
        className="p-4 flex items-center gap-2 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-gray-800"
      >
        <input 
          type="text" 
          value={userInput} 
          onChange={(e) => setUserInput(e.target.value)} 
          placeholder={`Message ${companionName || 'Peli'}...`} 
          className="flex-1 p-4 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm font-medium text-gray-900 dark:text-white" 
        />
        <button 
          type="submit" 
          disabled={!userInput.trim() || isTyping} 
          className="p-4 bg-indigo-600 text-white rounded-2xl active:scale-90 transition-transform disabled:opacity-50 disabled:grayscale shadow-lg shadow-indigo-500/20"
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

export default ChatTab;

import React, {
  createContext,
  useContext,
  useState,
  useRef,
  useCallback,
  ReactNode,
  useEffect,
  useMemo,
} from 'react';

import { initializeApp } from 'firebase/app';
import { getDatabase, ref, onValue, set, update } from 'firebase/database';
import { firebaseConfig } from '../firebaseConfig';

import useLocalStorage from '../hooks/useLocalStorage';
import {
  Emotion,
  ActivityLog,
  EmotionLog,
  ConnectionStatus,
  SUPPORTED_EMOTIONS,
  EquippedItems,
} from '../types';
import { SHOP_ITEMS } from '../constants';

type Theme = 'light' | 'dark';

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const db = getDatabase(app);

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;

  currentEmotion: Emotion;
  setCurrentEmotion: (emo: Emotion) => void;
  currentConfidence: number | null;
  setCurrentConfidence: (conf: number | null) => void;
  lastUpdate: number | null;

  emotionHistory: EmotionLog[];
  setEmotionHistory: React.Dispatch<React.SetStateAction<EmotionLog[]>>;
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;

  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  retryConnection: () => void;
  toggleSystemState: (state: 'start' | 'stop') => void;
  updateFirebaseEmotion: (label: string, confidence: number) => Promise<void>;
  isSystemRunning: boolean;
  isDemoMode: boolean;
  setIsDemoMode: (mode: boolean) => void;

  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  isPeliDirty: boolean;

  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliHungry: boolean;
  hungerLevel: number;

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useUserName(); 
  const [userPin, setUserPin] = useLocalStorage('userPin', '');
  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');
  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', 0);
  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
    hat: null,
    clothes: null,
  });

  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy');
  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState(false);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const isPeliDirty = useMemo(() => Date.now() - lastShowerTime > 3 * 60 * 60 * 1000, [lastShowerTime]);
  const isPeliHungry = useMemo(() => Date.now() - lastFedTime > 30 * 60 * 1000, [lastFedTime]);
  const hungerLevel = useMemo(() => {
    const window = 30 * 60 * 1000;
    const elapsed = Date.now() - lastFedTime;
    return Math.max(0, Math.min(100, 100 - (elapsed / window) * 100));
  }, [lastFedTime]);

  useEffect(() => {
    const root = document.documentElement;
    theme === 'dark' ? root.classList.add('dark') : root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(t => (t === 'light' ? 'dark' : 'light')), [setTheme]);

  // Firebase Realtime Database Listener
  useEffect(() => {
    if (isDemoMode) {
      setConnectionStatus('disconnected');
      return;
    }

    setConnectionStatus('connecting');

    // Listening to the path: emotions/current
    const emotionRef = ref(db, 'emotions/current');

    const unsubscribe = onValue(emotionRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setConnectionStatus('connected');
        setConnectionError(null);

        if (data.label) {
          const normalized = String(data.label).toLowerCase();
          const synonymMap: Record<string, Emotion> = {
            happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad', 
            fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
          };
          const matchedEmotion = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);

          if (matchedEmotion) {
            setCurrentEmotion(matchedEmotion);
            setCurrentConfidence(data.confidence ?? null);
            setLastUpdate(data.timestamp ?? Date.now());

            setEmotionHistory(prev => {
              if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
                return [{ id: Date.now().toString(), emotion: matchedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
              }
              return prev;
            });
          }
        }

        if (data.systemStatus !== undefined) {
          setIsSystemRunning(data.systemStatus === 'active');
        }
      } else {
        setConnectionStatus('connected');
        setIsSystemRunning(false);
      }
    }, (error) => {
      console.error("Firebase RTDB error:", error);
      setConnectionStatus('error');
      setConnectionError('Realtime Sync Failed: Check credentials or rules.');
    });

    return () => unsubscribe();
  }, [isDemoMode, setEmotionHistory]);

  const retryConnection = useCallback(() => {
    setIsDemoMode(false);
  }, [setIsDemoMode]);

  const toggleSystemState = useCallback(async (state: 'start' | 'stop') => {
    if (isDemoMode) {
      setIsSystemRunning(state === 'start');
      return;
    }

    try {
      const systemRef = ref(db, 'emotions/current');
      await update(systemRef, { 
        systemStatus: state === 'start' ? 'active' : 'idle',
        last_request: Date.now()
      });
    } catch (e) {
      console.error("Failed to update system state in Firebase RTDB", e);
    }
  }, [isDemoMode]);

  const updateFirebaseEmotion = useCallback(async (label: string, confidence: number) => {
    if (isDemoMode) return;
    try {
      const emotionRef = ref(db, 'emotions/current');
      await update(emotionRef, {
        label,
        confidence,
        timestamp: Date.now()
      });
    } catch (e) {
      console.error("Failed to push emotion to Firebase", e);
    }
  }, [isDemoMode]);

  const earnDrachma = useCallback((amount: number) => setDrachma(d => d + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
    if (drachma >= amount) {
      setDrachma(d => d - amount);
      return true;
    }
    return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (item?.category !== 'food' && inventory.includes(itemId)) return true;
    if (drachma < price) return false;
    setDrachma(d => d - price);
    setInventory(inv => [...inv, itemId]);
    return true;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
    setInventory(inv => {
      const idx = inv.indexOf(itemId);
      if (idx === -1) return inv;
      const copy = [...inv];
      copy.splice(idx, 1);
      return copy;
    });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
    setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const value: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, setCurrentEmotion, currentConfidence, setCurrentConfidence,
    lastUpdate, emotionHistory, setEmotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError, retryConnection,
    toggleSystemState, updateFirebaseEmotion, isSystemRunning, isDemoMode, setIsDemoMode, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, isPeliDirty, lastFedTime, setLastFedTime,
    isPeliHungry, hungerLevel, drachma, earnDrachma, spendDrachma, inventory,
    equippedItems, buyItem, equipItem, consumeItem,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

// Helper to keep local storage hook consistent
function useUserName() {
    return useLocalStorage('userName', '');
}

export const useAppContext = (): AppContextType => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useAppContext must be used within AppProvider');
  return ctx;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion } from '../types';

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    setCurrentEmotion,
    connectionStatus, 
    toggleSystemState, 
    updateFirebaseEmotion,
    isSystemRunning,
    currentConfidence, 
    setCurrentConfidence,
    setEmotionHistory
  } = useAppContext();

  // Local state for camera and detection
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [detectionInterval, setDetectionInterval] = useState(500);
  const [apiStatus, setApiStatus] = useState<'idle' | 'calling' | 'success' | 'error'>('idle');

  // Side Panel State
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const timerRef = useRef<number | null>(null);

  const AZURE_URL = "https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net";

  // COLORFUL IDLE: Using Indigo to indicate "Waiting for connection"
  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1'
  };

  // --- CAMERA ENUMERATION & PRIORITIZATION ---
  const refreshDevices = useCallback(async () => {
    try {
      // Request permission first to get labels
      await navigator.mediaDevices.getUserMedia({ video: true }).then(stream => {
        stream.getTracks().forEach(track => track.stop());
      }).catch(() => {});

      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);

      // Prioritize USB/Groundchat camera
      const usbCamera = videoDevices.find(d => 
        d.label.toLowerCase().includes('usb') || 
        d.label.toLowerCase().includes('groundchat') ||
        d.label.toLowerCase().includes('external')
      );

      if (usbCamera && !selectedDeviceId) {
        setSelectedDeviceId(usbCamera.deviceId);
      } else if (videoDevices.length > 0 && !selectedDeviceId) {
        // Fallback to first available (usually front)
        setSelectedDeviceId(videoDevices[0].deviceId);
      }
    } catch (err) {
      console.error("Error listing devices:", err);
    }
  }, [selectedDeviceId]);

  useEffect(() => {
    refreshDevices();
    // Listen for new device connections (e.g. plugging in USB-C camera)
    navigator.mediaDevices.addEventListener('devicechange', refreshDevices);
    return () => navigator.mediaDevices.removeEventListener('devicechange', refreshDevices);
  }, [refreshDevices]);

  // Safe lookup to prevent "undefined" crashes and force "Idle" when not fully connected
  const getEmotionDetails = () => {
    // If system is OFF, show colorful Idle. 
    if (!isSystemRunning) {
      return idleDetails;
    }

    const details = EMOTION_DETAILS[currentEmotion];
    if (details) return details;
    return EMOTION_DETAILS['Neutral'] || idleDetails;
  };

  const emotionDetails = getEmotionDetails();

  // --- WEBCAM & DETECTION LOGIC ---
  const startDetection = async (deviceId?: string) => {
    try {
      const targetId = deviceId || selectedDeviceId;
      const constraints = { 
        video: targetId 
          ? { deviceId: { exact: targetId }, width: 320, height: 240 } 
          : { width: 320, height: 240 }
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
        toggleSystemState('start');
        setApiStatus('idle'); 
      }
    } catch (err) {
      console.error("Camera access failed:", err);
      // If specific device fails, try default
      if (deviceId) {
        startDetection();
      } else {
        alert("Please allow camera access for emotion detection.");
      }
    }
  };

  const stopDetection = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    toggleSystemState('stop');
    if (timerRef.current) clearInterval(timerRef.current);
    setApiStatus('idle');
  };

  const handleDeviceChange = (deviceId: string) => {
    setSelectedDeviceId(deviceId);
    if (isCameraActive) {
      stopDetection();
      setTimeout(() => startDetection(deviceId), 300);
    }
  };

  const performDetection = useCallback(async () => {
    if (!isCameraActive || !videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 320;
    canvas.height = 240;
    ctx.drawImage(video, 0, 0, 320, 240);

    canvas.toBlob(async (blob) => {
      if (!blob) return;
      const formData = new FormData();
      formData.append('file', blob, 'frame.jpg');

      try {
        setApiStatus('calling');
        const response = await fetch(`${AZURE_URL}/predict`, {
          method: 'POST',
          body: formData
        });
        const data = await response.json();

        if (data.success) {
          setApiStatus('success');
          if (data.results && data.results.length > 0) {
            const detectedEmotion = data.results[0].emotion as Emotion;
            const detectedConfidence = data.results[0].confidence;

            // Local Updates
            setCurrentEmotion(detectedEmotion);
            setCurrentConfidence(detectedConfidence);

            // Cloud Sync: Push to Firebase
            updateFirebaseEmotion(detectedEmotion, detectedConfidence);

            setEmotionHistory(prev => {
              if (prev.length === 0 || prev[0].emotion !== detectedEmotion) {
                return [{ id: Date.now().toString(), emotion: detectedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
              }
              return prev;
            });
          }
        } else {
          setApiStatus('success'); 
        }
      } catch (err) {
        setApiStatus('error');
        console.error("Azure Sync Error:", err);
      }
    }, 'image/jpeg', 0.6);
  }, [isCameraActive, setCurrentEmotion, setCurrentConfidence, setEmotionHistory, updateFirebaseEmotion]);

  useEffect(() => {
    if (isCameraActive) {
      timerRef.current = window.setInterval(performDetection, detectionInterval);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isCameraActive, detectionInterval, performDetection]);

  return (
    <div className="flex flex-col items-center justify-between h-full transition-colors duration-500 overflow-hidden relative">

      {/* Side Panel Trigger Button */}
      <button 
        onClick={() => setIsPanelOpen(true)}
        className={`fixed right-0 top-1/2 -translate-y-1/2 z-[60] bg-white/40 dark:bg-black/40 backdrop-blur-md border border-r-0 border-white/30 dark:border-gray-700 py-6 px-1.5 rounded-l-2xl shadow-xl transition-all active:scale-95 group ${isPanelOpen ? 'translate-x-full' : 'translate-x-0'}`}
      >
        <span className="text-gray-600 dark:text-white text-xs font-black block transform transition-transform group-hover:-translate-x-0.5">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
          </svg>
        </span>
      </button>

      {/* Slide-in Compact Camera Panel */}
      <div className={`fixed top-0 right-0 h-full w-[260px] z-[70] bg-white/80 dark:bg-gray-950/90 backdrop-blur-2xl border-l border-gray-200 dark:border-gray-800 shadow-[-10px_0_30px_rgba(0,0,0,0.15)] transition-transform duration-500 ease-out flex flex-col ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-5 flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">Camera Studio</h3>
                <button onClick={() => setIsPanelOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-white font-bold text-xl active:scale-90 transition-transform">
                    &times;
                </button>
            </div>

            {/* Panel Live Preview */}
            <div className="w-full aspect-video bg-gray-900 rounded-xl overflow-hidden border border-white/10 shadow-inner mb-6 relative">
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive ? 'opacity-100' : 'opacity-0'}`}
                />
                {!isCameraActive && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-600 dark:text-gray-500 p-4 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mb-2 opacity-30" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                        </svg>
                        <span className="text-[8px] font-black uppercase tracking-widest opacity-40">Feed Off</span>
                    </div>
                )}
                {isCameraActive && (
                    <div className="absolute top-2 right-2 flex items-center gap-1.5 bg-black/40 backdrop-blur-md px-2 py-1 rounded-full border border-white/10">
