interface PeliProps {
  emotion: string; 
  animationClass?: string;
  showParticles?: string | null; 
  customEyes?: string; 
  isGlowing?: boolean; 
  scale?: number; 
  accessories?: 'headphones' | null;
  isDirty?: boolean; 
  isWet?: boolean; 
  isHungry?: boolean; 
  bubbles?: boolean; 
}

