import React, { useState, useEffect, useRef } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { ChatMessage, Emotion, SUPPORTED_EMOTIONS } from '../types';
import { PaperAirplaneIcon } from './Icons';
import { EMOTION_DETAILS } from '../constants';
import { GoogleGenAI } from "@google/genai";

const ChatTab: React.FC = () => {
  const { companionName, currentEmotion, setCurrentEmotion, userName } = useAppContext();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<any>(null);
  const lastEmotionRef = useRef<Emotion | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [messages, isTyping]);

  useEffect(() => {
    const initChat = async () => {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const chat = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: `You are ${companionName || 'Peli'}, a friendly emotion companion for ${userName || 'a friend'}. 
            Your goal is to support the user based on their current detected emotion. 
            Keep responses concise, human-like, and empathetic. 
            Currently, the user's sensors indicate they are feeling: ${currentEmotion}. 
            Respond accordingly to this mood state.`,
          },
        });
        chatSessionRef.current = chat;
        setAiError(null);

        if (messages.length === 0) {
          setMessages([{
            id: 'welcome',
            text: `Hi ${userName || 'Friend'}! I'm ${companionName || 'Peli'}, your best friend and companion. I sense you're feeling ${currentEmotion.toLowerCase()} right now. I'm always here for you! How can I help?`,
            sender: 'companion',
            timestamp: Date.now(),
          }]);
        }
      } catch (error: any) {
        setAiError(error.message || "Failed to start AI service.");
      }
    };
    initChat();
  }, [companionName, userName, currentEmotion]);

  useEffect(() => {
    if (lastEmotionRef.current === currentEmotion) return;

    const acknowledgeMoodShift = async () => {
      if (messages.length === 1 && messages[0].id === 'welcome') {
        setMessages([{
          id: 'welcome',
          text: `Hi ${userName || 'Friend'}! I'm ${companionName || 'Peli'}, your best friend and companion. I sense you're feeling ${currentEmotion.toLowerCase()} right now. I'm always here for you! How can I help?`,
          sender: 'companion',
          timestamp: Date.now(),
        }]);
      } 
      else if (messages.length > 1 && chatSessionRef.current && !isTyping) {
        setIsTyping(true);
        try {
          const nudge = `[System Nudge: The user's detected mood has just shifted to ${currentEmotion}. Briefly acknowledge this change in persona before we continue.]`;
          const result = await chatSessionRef.current.sendMessage({ message: nudge });

          if (result.text) {
            setMessages(prev => [...prev, {
              id: 'mood-shift-' + Date.now(),
              text: result.text,
              sender: 'companion',
              timestamp: Date.now(),
            }]);
          }
        } catch (e) {
          console.error("Mood shift nudge failed", e);
        } finally {
          setIsTyping(false);
        }
      }
      lastEmotionRef.current = currentEmotion;
    };

    acknowledgeMoodShift();
  }, [currentEmotion, messages.length, userName, companionName]);

  const processMessage = async (text: string) => {
    if (text.trim() === '' || isTyping || aiError) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), text, sender: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsTyping(true);

    try {
      if (!chatSessionRef.current) throw new Error("Not connected");
      const result = await chatSessionRef.current.sendMessage({ message: `[Feeling ${currentEmotion}] ${text}` });
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        text: result.text || "I'm listening!",
        sender: 'companion',
        timestamp: Date.now() + 1,
      }]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: 'err-' + Date.now(),
        text: "I'm having a momentary sync issue with my brain!",
        sender: 'companion',
        timestamp: Date.now(),
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (aiError) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-gray-950">
        <div className="w-20 h-20 bg-rose-100 dark:bg-rose-900/30 rounded-3xl flex items-center justify-center text-4xl mb-6">🚫</div>
        <h1 className="text-xl font-black text-gray-800 dark:text-white mb-2">Sync Error</h1>
        <p className="text-gray-500 text-sm mb-6">{aiError}</p>
        <p className="text-xs text-indigo-500 font-bold uppercase tracking-widest">Check configuration</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full pt-4 pb-2">
      <div className="flex items-center justify-between mb-2 px-4">
          <div className="flex flex-col">
              <h1 className="text-2xl font-black text-gray-900 dark:text-gray-100 italic tracking-tighter">PELIO<span className="text-indigo-600">CHAT</span></h1>
              <div className="flex items-center gap-1.5 mt-1">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                  <span className="text-[10px] font-black uppercase text-gray-500 dark:text-gray-400 tracking-widest">Active with {companionName || 'Peli'}</span>
              </div>
          </div>

          <div className="relative">
             <select 
               value={currentEmotion}
               onChange={(e) => setCurrentEmotion(e.target.value as Emotion)}
               className="bg-white dark:bg-gray-800 border-2 border-indigo-200 dark:border-indigo-800 rounded-2xl px-4 py-2 text-sm font-black text-indigo-950 dark:text-indigo-50 shadow-md outline-none appearance-none cursor-pointer hover:border-indigo-500 transition-all pr-10"
             >
                {SUPPORTED_EMOTIONS.map(emo => (
                  <option key={emo} value={emo} className="bg-white dark:bg-gray-900 text-gray-900 dark:text-white font-bold">
                    {EMOTION_DETAILS[emo].emoji} {emo}
                  </option>
                ))}
             </select>
             <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
               </svg>
             </div>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-4 p-4 scrollbar-hide bg-white/50 dark:bg-transparent rounded-t-[2.5rem] mt-2">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex items-end gap-2 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            {msg.sender === 'companion' && (
              <div className="w-9 h-9 rounded-full bg-indigo-600 dark:bg-indigo-500 flex items-center justify-center text-white text-[11px] font-black shrink-0 mb-1 shadow-lg border-2 border-white dark:border-gray-800 uppercase tracking-tighter">
                {(companionName || 'Peli').charAt(0)}
              </div>
            )}
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
              msg.sender === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white dark:bg-gray-800 text-gray-900 dark:text-white border border-gray-100 dark:border-gray-700 rounded-bl-none'
            }`}>
              <p className="text-sm font-medium leading-relaxed">{msg.text}</p>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 px-4">
             <div className="w-9 h-9 rounded-full bg-indigo-600/20 flex items-center justify-center shrink-0">
                <div className="flex gap-1">
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></span>
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></span>
                   <span className="w-1 h-1 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></span>
                </div>
             </div>
             <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{companionName || 'Peli'} is thinking</span>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form 
        onSubmit={(e) => { e.preventDefault(); processMessage(userInput); }} 
        className="p-4 flex items-center gap-2 bg-white dark:bg-gray-950 border-t border-gray-100 dark:border-gray-800"
      >
        <input 
          type="text" 
          value={userInput} 
          onChange={(e) => setUserInput(e.target.value)} 
          placeholder={`Message ${companionName || 'Peli'}...`} 
          className="flex-1 p-4 bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm font-medium text-gray-900 dark:text-white" 
        />
        <button 
          type="submit" 
          disabled={!userInput.trim() || isTyping} 
          className="p-4 bg-indigo-600 text-white rounded-2xl active:scale-90 transition-transform disabled:opacity-50 disabled:grayscale shadow-lg shadow-indigo-500/20"
        >
          <PaperAirplaneIcon className="w-6 h-6" />
        </button>
      </form>
    </div>
  );
};

export default ChatTab;

