import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion } from '../types';

const LiveTab: React.FC = () => {
  const { 
    currentEmotion, 
    setCurrentEmotion,
    connectionStatus, 
    toggleSystemState, 
    updateFirebaseEmotion,
    isSystemRunning,
    currentConfidence, 
    setCurrentConfidence,
    setEmotionHistory
  } = useAppContext();

  // Local state for camera and detection
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [detectionInterval, setDetectionInterval] = useState(500);
  const [apiStatus, setApiStatus] = useState<'idle' | 'calling' | 'success' | 'error'>('idle');

  // Side Panel State
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const timerRef = useRef<number | null>(null);

  const AZURE_URL = "https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net";

  // COLORFUL IDLE: Using Indigo to indicate "Waiting for connection"
  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1'
  };

  // --- CAMERA ENUMERATION & PRIORITIZATION ---
  const refreshDevices = useCallback(async () => {
    try {
      // Request permission first to get labels
      await navigator.mediaDevices.getUserMedia({ video: true }).then(stream => {
        stream.getTracks().forEach(track => track.stop());
      }).catch(() => {});

      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);

      // Prioritize USB/Groundchat camera
      const usbCamera = videoDevices.find(d => 
        d.label.toLowerCase().includes('usb') || 
        d.label.toLowerCase().includes('groundchat') ||
        d.label.toLowerCase().includes('external')
      );

      if (usbCamera && !selectedDeviceId) {
        setSelectedDeviceId(usbCamera.deviceId);
      } else if (videoDevices.length > 0 && !selectedDeviceId) {
        // Fallback to first available (usually front)
        setSelectedDeviceId(videoDevices[0].deviceId);
      }
    } catch (err) {
      console.error("Error listing devices:", err);
    }
  }, [selectedDeviceId]);

  useEffect(() => {
    refreshDevices();
    // Listen for new device connections (e.g. plugging in USB-C camera)
    navigator.mediaDevices.addEventListener('devicechange', refreshDevices);
    return () => navigator.mediaDevices.removeEventListener('devicechange', refreshDevices);
  }, [refreshDevices]);

  // Safe lookup to prevent "undefined" crashes and force "Idle" when not fully connected
  const getEmotionDetails = () => {
    // If system is OFF, show colorful Idle. 
    if (!isSystemRunning) {
      return idleDetails;
    }

    const details = EMOTION_DETAILS[currentEmotion];
    if (details) return details;
    return EMOTION_DETAILS['Neutral'] || idleDetails;
  };

  const emotionDetails = getEmotionDetails();

  // --- WEBCAM & DETECTION LOGIC ---
  const startDetection = async (deviceId?: string) => {
    try {
      const targetId = deviceId || selectedDeviceId;
      const constraints = { 
        video: targetId 
          ? { deviceId: { exact: targetId }, width: 320, height: 240 } 
          : { width: 320, height: 240 }
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
        toggleSystemState('start');
        setApiStatus('idle'); 
      }
    } catch (err) {
      console.error("Camera access failed:", err);
      // If specific device fails, try default
      if (deviceId) {
        startDetection();
      } else {
        alert("Please allow camera access for emotion detection.");
      }
    }
  };

  const stopDetection = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    toggleSystemState('stop');
    if (timerRef.current) clearInterval(timerRef.current);
    setApiStatus('idle');
  };

  const handleDeviceChange = (deviceId: string) => {
    setSelectedDeviceId(deviceId);
    if (isCameraActive) {
      stopDetection();
      setTimeout(() => startDetection(deviceId), 300);
    }
  };

  const performDetection = useCallback(async () => {
    if (!isCameraActive || !videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = 320;
    canvas.height = 240;
    ctx.drawImage(video, 0, 0, 320, 240);

    canvas.toBlob(async (blob) => {
      if (!blob) return;
      const formData = new FormData();
      formData.append('file', blob, 'frame.jpg');

      try {
        setApiStatus('calling');
        const response = await fetch(`${AZURE_URL}/predict`, {
          method: 'POST',
          body: formData
        });
        const data = await response.json();

        if (data.success) {
          setApiStatus('success');
          if (data.results && data.results.length > 0) {
            const detectedEmotion = data.results[0].emotion as Emotion;
            const detectedConfidence = data.results[0].confidence;

            // Local Updates
            setCurrentEmotion(detectedEmotion);
            setCurrentConfidence(detectedConfidence);

            // Cloud Sync: Push to Firebase
            updateFirebaseEmotion(detectedEmotion, detectedConfidence);

            setEmotionHistory(prev => {
              if (prev.length === 0 || prev[0].emotion !== detectedEmotion) {
                return [{ id: Date.now().toString(), emotion: detectedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
              }
              return prev;
            });
          }
        } else {
          setApiStatus('success'); 
        }
      } catch (err) {
        setApiStatus('error');
        console.error("Azure Sync Error:", err);
      }
    }, 'image/jpeg', 0.6);
  }, [isCameraActive, setCurrentEmotion, setCurrentConfidence, setEmotionHistory, updateFirebaseEmotion]);

  useEffect(() => {
    if (isCameraActive) {
      timerRef.current = window.setInterval(performDetection, detectionInterval);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isCameraActive, detectionInterval, performDetection]);

  return (
    <div className="flex flex-col items-center justify-between h-full transition-colors duration-500 overflow-hidden relative">

      {/* Side Panel Trigger Button */}
      <button 
        onClick={() => setIsPanelOpen(true)}
        className={`fixed right-0 top-1/2 -translate-y-1/2 z-[60] bg-white/40 dark:bg-black/40 backdrop-blur-md border border-r-0 border-white/30 dark:border-gray-700 py-6 px-1.5 rounded-l-2xl shadow-xl transition-all active:scale-95 group ${isPanelOpen ? 'translate-x-full' : 'translate-x-0'}`}
      >
        <span className="text-gray-600 dark:text-white text-xs font-black block transform transition-transform group-hover:-translate-x-0.5">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" />
          </svg>
        </span>
      </button>

      {/* Slide-in Compact Camera Panel */}
      <div className={`fixed top-0 right-0 h-full w-[260px] z-[70] bg-white/80 dark:bg-gray-950/90 backdrop-blur-2xl border-l border-gray-200 dark:border-gray-800 shadow-[-10px_0_30px_rgba(0,0,0,0.15)] transition-transform duration-500 ease-out flex flex-col ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-5 flex-1 flex flex-col">
            <div className="flex items-center justify-between mb-6">
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">Camera Studio</h3>
                <button onClick={() => setIsPanelOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-white font-bold text-xl active:scale-90 transition-transform">
                    &times;
                </button>
            </div>

            {/* Panel Live Preview */}
            <div className="w-full aspect-video bg-gray-900 rounded-xl overflow-hidden border border-white/10 shadow-inner mb-6 relative">
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    className={`w-full h-full object-cover transition-opacity duration-500 ${isCameraActive ? 'opacity-100' : 'opacity-0'}`}
                />
                {!isCameraActive && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-600 dark:text-gray-500 p-4 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mb-2 opacity-30" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                        </svg>
                        <span className="text-[8px] font-black uppercase tracking-widest opacity-40">Feed Off</span>
                    </div>
                )}
                {isCameraActive && (
                    <div className="absolute top-2 right-2 flex items-center gap-1.5 bg-black/40 backdrop-blur-md px-2 py-1 rounded-full border border-white/10">
                        <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse" />
                        <span className="text-[8px] font-black text-white uppercase tracking-widest">Live</span>
                    </div>
                )}
            </div>

            {/* Mini Controls */}
            <div className="space-y-6">
                <div className="flex items-center justify-between bg-gray-50 dark:bg-white/5 p-3 rounded-2xl border border-gray-100 dark:border-white/5">
                    <div className="flex flex-col">
                        <span className="text-[9px] font-black uppercase text-gray-400">Power</span>
                        <span className="text-[11px] font-bold dark:text-white">{isCameraActive ? 'Active' : 'Offline'}</span>
                    </div>
                    <button 
                        onClick={isCameraActive ? stopDetection : () => startDetection()}
                        className={`w-12 h-6 rounded-full transition-all relative ${isCameraActive ? 'bg-green-500' : 'bg-gray-300 dark:bg-gray-800'}`}
                    >
                        <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm transition-all ${isCameraActive ? 'left-7' : 'left-1'}`} />
                    </button>
                </div>

                <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase tracking-[0.15em] text-gray-400 ml-1">Select Source</label>
                    <div className="relative">
                        <select 
                            value={selectedDeviceId}
                            onChange={(e) => handleDeviceChange(e.target.value)}
                            className="w-full bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl p-3 text-[11px] font-bold text-gray-700 dark:text-white outline-none appearance-none shadow-sm pr-10"
                        >
                            {devices.length === 0 ? (
                                <option value="">No cameras found</option>
                            ) : (
                                devices.map(d => (
                                    <option key={d.deviceId} value={d.deviceId}>
                                        {d.label || `Camera ${d.deviceId.slice(0, 4)}`}
                                    </option>
                                ))
                            )}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                        </div>
                    </div>
                </div>

                {/* Priority Status Badge */}
