      const synonymMap: Record<string, Emotion> = {
        happy: 'Happy',
        sad: 'Sad',
        angry: 'Angry',
        mad: 'Mad',
        fear: 'Fear',
        surprised: 'Surprised',
        disgust: 'Disgust',
