import React, {
  createContext,
  useContext,
  useState,
  useRef,
  useCallback,
  ReactNode,
  useEffect,
  useMemo,
} from 'react';

import { initializeApp } from 'firebase/app';
import { getDatabase, ref, onValue, set, update } from 'firebase/database';
import { firebaseConfig } from '../firebaseConfig';

import useLocalStorage from '../hooks/useLocalStorage';
import {
  Emotion,
  ActivityLog,
  EmotionLog,
  ConnectionStatus,
  SUPPORTED_EMOTIONS,
  EquippedItems,
} from '../types';
import { SHOP_ITEMS } from '../constants';

type Theme = 'light' | 'dark';

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const db = getDatabase(app);

interface AppContextType {
  companionName: string;
  setCompanionName: (name: string) => void;
  userName: string;
  setUserName: (name: string) => void;
  userPin: string;
  setUserPin: (pin: string) => void;

  // Decoupled Emotion States
  currentEmotion: Emotion; // For Chat/Manual
  setCurrentEmotion: (emo: Emotion) => void;
  azureEmotion: Emotion;   // Strictly for Live Azure Feed
  setAzureEmotion: (emo: Emotion) => void;

  currentConfidence: number | null;
  setCurrentConfidence: (conf: number | null) => void;
  lastUpdate: number | null;

  emotionHistory: EmotionLog[];
  setEmotionHistory: React.Dispatch<React.SetStateAction<EmotionLog[]>>;
  activityHistory: ActivityLog[];
  addActivityLog: (activityName: ActivityLog['activityName']) => void;
  clearHistory: () => void;

  connectionStatus: ConnectionStatus;
  connectionError: string | null;
  retryConnection: () => void;
  toggleSystemState: (state: 'start' | 'stop') => void;
  updateFirebaseEmotion: (label: string, confidence: number) => Promise<void>;
  isSystemRunning: boolean;
  isDemoMode: boolean;
  setIsDemoMode: (mode: boolean) => void;

  theme: Theme;
  toggleTheme: () => void;

  lastShowerTime: number;
  setLastShowerTime: (time: number) => void;
  isPeliDirty: boolean;

  lastFedTime: number;
  setLastFedTime: (time: number) => void;
  isPeliHungry: boolean;
  hungerLevel: number;

  drachma: number;
  earnDrachma: (amount: number) => void;
  spendDrachma: (amount: number) => boolean;
  inventory: string[];
  equippedItems: EquippedItems;
  buyItem: (itemId: string, price: number) => boolean;
  equipItem: (category: keyof EquippedItems, itemId: string | null) => void;
  consumeItem: (itemId: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [companionName, setCompanionName] = useLocalStorage('companionName', 'PELI');
  const [userName, setUserName] = useUserName(); 
  const [userPin, setUserPin] = useLocalStorage('userPin', '');
  const [activityHistory, setActivityHistory] = useLocalStorage<ActivityLog[]>('activityHistory', []);
  const [emotionHistory, setEmotionHistory] = useLocalStorage<EmotionLog[]>('emotionHistory', []);
  const [theme, setTheme] = useLocalStorage<Theme>('theme', 'light');
  const [lastShowerTime, setLastShowerTime] = useLocalStorage<number>('lastShowerTime', 0);
  const [lastFedTime, setLastFedTime] = useLocalStorage<number>('lastFedTime', 0);
  const [drachma, setDrachma] = useLocalStorage<number>('drachma', 1000);
  const [inventory, setInventory] = useLocalStorage<string[]>('inventory', []);
  const [equippedItems, setEquippedItems] = useLocalStorage<EquippedItems>('equippedItems', {
    hat: null,
    clothes: null,
  });

  // Decoupled states
  const [currentEmotion, setCurrentEmotion] = useState<Emotion>('Happy'); // Used by Chat
  const [azureEmotion, setAzureEmotion] = useState<Emotion>('Neutral');  // Used by Live Tab

  const [currentConfidence, setCurrentConfidence] = useState<number | null>(null);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [isSystemRunning, setIsSystemRunning] = useState(false);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected');
  const [connectionError, setConnectionError] = useState<string | null>(null);

  const isPeliDirty = useMemo(() => Date.now() - lastShowerTime > 3 * 60 * 60 * 1000, [lastShowerTime]);
  const isPeliHungry = useMemo(() => Date.now() - lastFedTime > 30 * 60 * 1000, [lastFedTime]);
  const hungerLevel = useMemo(() => {
    const window = 30 * 60 * 1000;
    const elapsed = Date.now() - lastFedTime;
    return Math.max(0, Math.min(100, 100 - (elapsed / window) * 100));
  }, [lastFedTime]);

  useEffect(() => {
    const root = document.documentElement;
    theme === 'dark' ? root.classList.add('dark') : root.classList.remove('dark');
  }, [theme]);

  const toggleTheme = useCallback(() => setTheme(t => (t === 'light' ? 'dark' : 'light')), [setTheme]);

  // Firebase Realtime Database Listener
  useEffect(() => {
    if (isDemoMode) {
      setConnectionStatus('disconnected');
      return;
    }

    setConnectionStatus('connecting');
    const emotionRef = ref(db, 'emotions/current');

    const unsubscribe = onValue(emotionRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setConnectionStatus('connected');
        setConnectionError(null);

        if (data.label) {
          const normalized = String(data.label).toLowerCase();
          const synonymMap: Record<string, Emotion> = {
            happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad', 
            fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
          };
          const matchedEmotion = synonymMap[normalized] || SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === normalized);

          if (matchedEmotion) {
            // Keep in sync for history and defaults
            setAzureEmotion(matchedEmotion);
            setCurrentConfidence(data.confidence ?? null);
            setLastUpdate(data.timestamp ?? Date.now());

            setEmotionHistory(prev => {
              if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
                return [{ id: Date.now().toString(), emotion: matchedEmotion, detectedAt: Date.now() }, ...prev].slice(0, 100);
              }
              return prev;
            });
          }
        }

        if (data.systemStatus !== undefined) {
          setIsSystemRunning(data.systemStatus === 'active');
        }
      } else {
        setConnectionStatus('connected');
        setIsSystemRunning(false);
      }
    }, (error) => {
      setConnectionStatus('error');
      setConnectionError('Realtime Sync Failed');
    });

    return () => unsubscribe();
  }, [isDemoMode, setEmotionHistory]);

  const retryConnection = useCallback(() => {
    setIsDemoMode(false);
  }, [setIsDemoMode]);

  const toggleSystemState = useCallback(async (state: 'start' | 'stop') => {
    if (isDemoMode) {
      setIsSystemRunning(state === 'start');
      return;
    }
    try {
      const systemRef = ref(db, 'emotions/current');
      await update(systemRef, { 
        systemStatus: state === 'start' ? 'active' : 'idle',
        last_request: Date.now()
      });
    } catch (e) {
      console.error("Failed to update system state", e);
    }
  }, [isDemoMode]);

  const updateFirebaseEmotion = useCallback(async (label: string, confidence: number) => {
    if (isDemoMode) return;
    try {
      const emotionRef = ref(db, 'emotions/current');
      await update(emotionRef, {
        label,
        confidence,
        timestamp: Date.now()
      });
    } catch (e) {
      console.error("Failed to push emotion", e);
    }
  }, [isDemoMode]);

  const earnDrachma = useCallback((amount: number) => setDrachma(d => d + amount), [setDrachma]);
  const spendDrachma = useCallback((amount: number) => {
    if (drachma >= amount) {
      setDrachma(d => d - amount);
      return true;
    }
    return false;
  }, [drachma, setDrachma]);

  const buyItem = useCallback((itemId: string, price: number) => {
    const item = SHOP_ITEMS.find(i => i.id === itemId);
    if (item?.category !== 'food' && inventory.includes(itemId)) return true;
    if (drachma < price) return false;
    setDrachma(d => d - price);
    setInventory(inv => [...inv, itemId]);
    return true;
  }, [drachma, inventory, setDrachma, setInventory]);

  const consumeItem = useCallback((itemId: string) => {
    setInventory(inv => {
      const idx = inv.indexOf(itemId);
      if (idx === -1) return inv;
      const copy = [...inv];
      copy.splice(idx, 1);
      return copy;
    });
  }, [setInventory]);

  const equipItem = useCallback((category: keyof EquippedItems, itemId: string | null) => {
    setEquippedItems(prev => ({ ...prev, [category]: itemId }));
  }, [setEquippedItems]);

  const addActivityLog = useCallback((activityName: ActivityLog['activityName']) => {
    setActivityHistory(prev => [{ id: Date.now().toString(), activityName, completedAt: Date.now() }, ...prev]);
  }, [setActivityHistory]);

  const clearHistory = useCallback(() => {
    setActivityHistory([]);
    setEmotionHistory([]);
  }, [setActivityHistory, setEmotionHistory]);

  const value: AppContextType = {
    companionName, setCompanionName, userName, setUserName, userPin, setUserPin,
    currentEmotion, setCurrentEmotion, azureEmotion, setAzureEmotion,
    currentConfidence, setCurrentConfidence,
    lastUpdate, emotionHistory, setEmotionHistory, activityHistory,
    addActivityLog, clearHistory, connectionStatus, connectionError, retryConnection,
    toggleSystemState, updateFirebaseEmotion, isSystemRunning, isDemoMode, setIsDemoMode, theme, toggleTheme,
    lastShowerTime, setLastShowerTime, isPeliDirty, lastFedTime, setLastFedTime,
    isPeliHungry, hungerLevel, drachma, earnDrachma, spendDrachma, inventory,
    equippedItems, buyItem, equipItem, consumeItem,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

function useUserName() {
    return useLocalStorage('userName', '');
}

export const useAppContext = (): AppContextType => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useAppContext must be used within AppProvider');
  return ctx;
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion, SUPPORTED_EMOTIONS } from '../types';

const LiveTab: React.FC = () => {
  const { 
    azureEmotion,
    setAzureEmotion,
    isSystemRunning,
    toggleSystemState,
    currentConfidence,
    setCurrentConfidence,
    updateFirebaseEmotion,
    setEmotionHistory
  } = useAppContext();

  const [apiStatus, setApiStatus] =
    useState<'idle' | 'calling' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const pollerRef = useRef<number | null>(null);

  const AZURE_URL =
    'https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net';

  const POLL_INTERVAL = 2000;

  // -------------------------------
  // IDLE DISPLAY (Using azureEmotion)
  // -------------------------------
  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1'
  };

  const getEmotionDetails = () => {
    if (!isSystemRunning) return idleDetails;
    return EMOTION_DETAILS[azureEmotion] || idleDetails;
  };

  const emotionDetails = getEmotionDetails();

  // -------------------------------
  // AZURE POLLING
  // -------------------------------
  const fetchEmotionFromAzure = useCallback(async () => {
    try {
      setApiStatus('calling');

      const res = await fetch(`${AZURE_URL}/latest`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache'
        },
        mode: 'cors',
        credentials: 'omit'
      });

      if (!res.ok) {
        throw new Error(`Server status: ${res.status}`);
      }

      const data = await res.json();

      if (!data || data.success === false) {
        setApiStatus('success');
        return;
      }

      const rawEmotion = String(data.emotion || '').trim().toLowerCase();

      const synonymMap: Record<string, Emotion> = {
        happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad',
        fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
      };

      const matchedEmotion = synonymMap[rawEmotion] || 
                             SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === rawEmotion);

      if (matchedEmotion) {
        const detectedConfidence = typeof data.confidence === 'number' ? data.confidence : 0.85;

        setAzureEmotion(matchedEmotion);
        setCurrentConfidence(detectedConfidence);
        updateFirebaseEmotion(matchedEmotion, detectedConfidence);

        setEmotionHistory(prev => {
          if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
            return [
              {
                id: Date.now().toString(),
                emotion: matchedEmotion,
                detectedAt: Date.now()
              },
              ...prev
            ].slice(0, 100);
          }
          return prev;
        });
      }

      setApiStatus('success');
      setErrorMessage(null);
    } catch (err) {
      console.error('Azure fetch error:', err);
      setApiStatus('error');
      setErrorMessage(err instanceof Error ? err.message : 'Check connection');
    }
  }, [
    AZURE_URL,
    setAzureEmotion,
    setCurrentConfidence,
    updateFirebaseEmotion,
    setEmotionHistory
  ]);

  // -------------------------------
  // SYSTEM LIFECYCLE
  // -------------------------------
  const startSystem = () => {
    toggleSystemState('start');
    fetchEmotionFromAzure();
    if (pollerRef.current) clearInterval(pollerRef.current);
    pollerRef.current = window.setInterval(fetchEmotionFromAzure, POLL_INTERVAL);
  };

  const stopSystem = () => {
    toggleSystemState('stop');
    if (pollerRef.current) clearInterval(pollerRef.current);
    pollerRef.current = null;
    setApiStatus('idle');
  };

  useEffect(() => {
    if (isSystemRunning && !pollerRef.current) {
      pollerRef.current = window.setInterval(fetchEmotionFromAzure, POLL_INTERVAL);
    }
    return () => {
      if (pollerRef.current) clearInterval(pollerRef.current);
    };
  }, [isSystemRunning, fetchEmotionFromAzure]);

  const getStatusTextColor = () => {
    if (!isSystemRunning) return 'text-slate-500 dark:text-slate-400';
    if (apiStatus === 'error') return 'text-rose-500 font-bold animate-pulse';
    if (apiStatus === 'calling') return 'text-indigo-600 dark:text-indigo-400';
    return 'text-emerald-600 dark:text-emerald-400 font-black';
  };

  return (
    <div className="flex flex-col items-center justify-between h-full overflow-hidden relative">
      <div className="w-full px-6 py-6 flex items-center justify-between z-10">
        <div>
          <h1 className="text-sm font-black uppercase italic tracking-tighter">
            <span className="text-slate-900 dark:text-slate-100">Pelio</span>
            <span className="text-indigo-600 dark:text-indigo-400">Scope</span>
          </h1>
          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">
            Intelligent Remote Feed
          </p>
        </div>

        <div className="flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-gray-800 rounded-full border border-gray-100 dark:border-gray-700 shadow-sm">
          <div
            className={`w-1.5 h-1.5 rounded-full ${
              isSystemRunning
                ? apiStatus === 'error'
                  ? 'bg-rose-500'
                  : 'bg-emerald-500 animate-pulse'
                : 'bg-slate-400'
            }`}
          />
          <span className={`text-[9px] font-black uppercase tracking-widest ${getStatusTextColor()}`}>
            {isSystemRunning
              ? apiStatus === 'calling'
                ? 'Syncing...'
                : apiStatus === 'error'
                ? 'Link Error'
                : 'Live Sync'
              : 'Idle'}
          </span>
        </div>
      </div>

      <div className="flex-grow flex flex-col items-center justify-center text-center px-6">
        <style>{`
          @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-15px); } }
          .animate-float { animation: float 4s ease-in-out infinite; }
        `}</style>

        <div
          className={`text-[140px] transition-all duration-700 transform ${
            isSystemRunning ? 'animate-float scale-110' : 'opacity-30 grayscale scale-90'
          }`}
          style={{
            filter:
              isSystemRunning && emotionDetails.pulseColor
                ? `drop-shadow(0 0 45px ${emotionDetails.pulseColor})`
                : 'none'
          }}
        >
          {emotionDetails.emoji}
        </div>

        <div className="mt-4">
          <h2 className={`text-5xl font-black uppercase italic tracking-tighter transition-all duration-500 ${emotionDetails.color}`}>
            {isSystemRunning ? azureEmotion : 'Idle'}
          </h2>

          {isSystemRunning && (
            <div className="mt-4 flex flex-col items-center gap-1">
              <div className="px-4 py-1.5 rounded-full bg-white/60 dark:bg-gray-800/60 backdrop-blur-md border border-white/20 dark:border-gray-700 shadow-sm">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">
                  {currentConfidence !== null ? `Confidence: ${(currentConfidence * 100).toFixed(0)}%` : 'Syncing AI...'}
                </span>
              </div>
              {apiStatus === 'error' && (
                <p className="text-[8px] font-black text-rose-400 uppercase tracking-widest mt-2 px-4 text-center">
                  Error: {errorMessage || 'Azure Timeout'}
                </p>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-sm px-6 pb-24 z-10">
        <button
          onClick={isSystemRunning ? stopSystem : startSystem}
          className={`group w-full py-5 rounded-[2.2rem] font-black text-lg text-white shadow-2xl transition-all duration-300 transform active:scale-95 flex items-center justify-center gap-3 ${
            isSystemRunning
              ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-500/30'
              : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/30'
          }`}
        >
          {isSystemRunning ? (
            <>
              <div className="w-2 h-2 bg-white rounded-full animate-ping" />
              <span>Disable Link</span>
            </>
          ) : (
            <span>Enable Remote Link</span>
          )}
        </button>
      </div>

      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-500/5 dark:bg-indigo-400/5 blur-[120px]" />
        <div className="absolute bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-500/5 dark:bg-purple-400/5 blur-[120px]" />
      </div>
    </div>
  );
};

