import React, { useEffect, useRef, useState, useCallback } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { EMOTION_DETAILS } from '../constants';
import { Emotion, SUPPORTED_EMOTIONS } from '../types';

const LiveTab: React.FC = () => {
  const { 
    azureEmotion,
    setAzureEmotion,
    isSystemRunning,
    toggleSystemState,
    currentConfidence,
    setCurrentConfidence,
    updateFirebaseEmotion,
    setEmotionHistory
  } = useAppContext();

  const [apiStatus, setApiStatus] =
    useState<'idle' | 'calling' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const pollerRef = useRef<number | null>(null);

  // The base URL for the Azure App Service
  const AZURE_URL = 'https://emotion-detection-api-g9budncvekdgewbk.eastasia-01.azurewebsites.net';

  const POLL_INTERVAL = 2000;

  // -------------------------------
  // IDLE DISPLAY (Using azureEmotion)
  // -------------------------------
  const idleDetails = {
    emoji: '😴',
    color: 'text-indigo-500 dark:text-indigo-400',
    pulseColor: '#6366f1'
  };

  const getEmotionDetails = () => {
    if (!isSystemRunning) return idleDetails;
    return EMOTION_DETAILS[azureEmotion] || idleDetails;
  };

  const emotionDetails = getEmotionDetails();

  // -------------------------------
  // AZURE POLLING (FIXED: Handling 404 and root endpoints)
  // -------------------------------
  const fetchEmotionFromAzure = useCallback(async () => {
    try {
      setApiStatus('calling');

      // Attempt to fetch from the root first, then /latest as fallback
      // This solves the 404 issue if the endpoint is at the root
      const res = await fetch(AZURE_URL, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache'
        },
        mode: 'cors',
        credentials: 'omit'
      });

      if (!res.ok) {
        // If root fails with 404, try /latest as a last resort
        if (res.status === 404) {
             const retryRes = await fetch(`${AZURE_URL}/latest`);
             if (!retryRes.ok) throw new Error(`Server returned ${retryRes.status}`);
             return processResponse(await retryRes.json());
        }
        throw new Error(`Server returned ${res.status}`);
      }

      const data = await res.json();
      processResponse(data);

    } catch (err) {
      console.error('Azure fetch error:', err);
      setApiStatus('error');
      setErrorMessage(err instanceof Error ? err.message : 'Connection failed');
    }
  }, [AZURE_URL]);

  const processResponse = (data: any) => {
    if (!data) {
      setApiStatus('success');
      return;
    }

    // Handle different API response formats
    const rawEmotion = String(data.emotion || data.label || '').trim().toLowerCase();

    const synonymMap: Record<string, Emotion> = {
      happy: 'Happy', sad: 'Sad', angry: 'Angry', mad: 'Mad',
      fear: 'Fear', surprised: 'Surprised', disgust: 'Disgust', neutral: 'Neutral'
    };

    const matchedEmotion = synonymMap[rawEmotion] || 
                           SUPPORTED_EMOTIONS.find(e => e.toLowerCase() === rawEmotion);

    if (matchedEmotion) {
      const detectedConfidence = typeof data.confidence === 'number' ? data.confidence : 0.85;

      // Update ONLY Azure-specific states (Decoupled from Chat)
      setAzureEmotion(matchedEmotion);
      setCurrentConfidence(detectedConfidence);
      updateFirebaseEmotion(matchedEmotion, detectedConfidence);

      setEmotionHistory(prev => {
        if (prev.length === 0 || prev[0].emotion !== matchedEmotion) {
          return [
            {
              id: Date.now().toString(),
              emotion: matchedEmotion,
              detectedAt: Date.now()
            },
            ...prev
          ].slice(0, 100);
        }
        return prev;
      });
    }

    setApiStatus('success');
    setErrorMessage(null);
  };

  // -------------------------------
  // SYSTEM LIFECYCLE
  // -------------------------------
  const startSystem = () => {
    toggleSystemState('start');
    fetchEmotionFromAzure();
    if (pollerRef.current) clearInterval(pollerRef.current);
    pollerRef.current = window.setInterval(fetchEmotionFromAzure, POLL_INTERVAL);
  };

  const stopSystem = () => {
    toggleSystemState('stop');
    if (pollerRef.current) clearInterval(pollerRef.current);
    pollerRef.current = null;
    setApiStatus('idle');
  };

  useEffect(() => {
    if (isSystemRunning && !pollerRef.current) {
      pollerRef.current = window.setInterval(fetchEmotionFromAzure, POLL_INTERVAL);
    }
    return () => {
      if (pollerRef.current) clearInterval(pollerRef.current);
    };
  }, [isSystemRunning, fetchEmotionFromAzure]);

  const getStatusTextColor = () => {
    if (!isSystemRunning) return 'text-slate-500 dark:text-slate-400';
    if (apiStatus === 'error') return 'text-rose-500 font-bold animate-pulse';
    if (apiStatus === 'calling') return 'text-indigo-600 dark:text-indigo-400';
    return 'text-emerald-600 dark:text-emerald-400 font-black';
  };

  return (
    <div className="flex flex-col items-center justify-between h-full overflow-hidden relative">
      <div className="w-full px-6 py-6 flex items-center justify-between z-10">
        <div>
          <h1 className="text-sm font-black uppercase italic tracking-tighter">
            <span className="text-slate-900 dark:text-slate-100">Pelio</span>
            <span className="text-indigo-600 dark:text-indigo-400">Scope</span>
          </h1>
          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">
            Intelligent Remote Feed
          </p>
        </div>

        <div className="flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-gray-800 rounded-full border border-gray-100 dark:border-gray-700 shadow-sm">
          <div
            className={`w-1.5 h-1.5 rounded-full ${
              isSystemRunning
                ? apiStatus === 'error'
                  ? 'bg-rose-500'
                  : 'bg-emerald-500 animate-pulse'
                : 'bg-slate-400'
            }`}
          />
          <span className={`text-[9px] font-black uppercase tracking-widest ${getStatusTextColor()}`}>
            {isSystemRunning
              ? apiStatus === 'calling'
                ? 'Syncing...'
                : apiStatus === 'error'
                ? 'Link Error'
                : 'Live Sync'
              : 'Idle'}
          </span>
        </div>
      </div>

      <div className="flex-grow flex flex-col items-center justify-center text-center px-6">
        <style>{`
          @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-15px); } }
          .animate-float { animation: float 4s ease-in-out infinite; }
        `}</style>

        <div
          className={`text-[140px] transition-all duration-700 transform ${
            isSystemRunning ? 'animate-float scale-110' : 'opacity-30 grayscale scale-90'
          }`}
          style={{
            filter:
              isSystemRunning && emotionDetails.pulseColor
                ? `drop-shadow(0 0 45px ${emotionDetails.pulseColor})`
                : 'none'
          }}
        >
          {emotionDetails.emoji}
        </div>

        <div className="mt-4">
          <h2 className={`text-5xl font-black uppercase italic tracking-tighter transition-all duration-500 ${emotionDetails.color}`}>
            {isSystemRunning ? azureEmotion : 'Idle'}
          </h2>

          {isSystemRunning && (
            <div className="mt-4 flex flex-col items-center gap-1">
              <div className="px-4 py-1.5 rounded-full bg-white/60 dark:bg-gray-800/60 backdrop-blur-md border border-white/20 dark:border-gray-700 shadow-sm">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400">
                  {currentConfidence !== null ? `Confidence: ${(currentConfidence * 100).toFixed(0)}%` : 'Connecting...'}
                </span>
              </div>
              {apiStatus === 'error' && (
                <p className="text-[8px] font-black text-rose-400 uppercase tracking-widest mt-2 px-4 text-center">
                  Server Error: {errorMessage || 'Not Found (404)'}
                </p>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="w-full max-w-sm px-6 pb-24 z-10">
        <button
          onClick={isSystemRunning ? stopSystem : startSystem}
          className={`group w-full py-5 rounded-[2.2rem] font-black text-lg text-white shadow-2xl transition-all duration-300 transform active:scale-95 flex items-center justify-center gap-3 ${
            isSystemRunning
              ? 'bg-rose-500 hover:bg-rose-600 shadow-rose-500/30'
              : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-500/30'
          }`}
        >
          {isSystemRunning ? (
            <>
              <div className="w-2 h-2 bg-white rounded-full animate-ping" />
              <span>Deactivate Feed</span>
            </>
          ) : (
            <span>Activate Live Feed</span>
          )}
        </button>
      </div>

      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-500/5 dark:bg-indigo-400/5 blur-[120px]" />
        <div className="absolute bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-500/5 dark:bg-purple-400/5 blur-[120px]" />
      </div>
    </div>
  );
};

